INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(1, 1, 'single_choice', '电视机开机后只有声音没有图像，首先应检查哪部分电路？A. 音频功放 B. 行扫描或背光电路 C. 电源整流 D. 遥控接收', '["B"]', '有声无图通常问题出在行扫描或背光电路。', 'medium', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 2, 'single_choice', '冰箱制冷效果差，压缩机长时间运转不停机，最常见的原因是？A. 门封条老化 B. 制冷剂泄漏或温控器故障 C. 照明灯损坏 D. 电源电压过低', '["B"]', '制冷剂泄漏或温控器故障都可能导致不停机且制冷差。', 'medium', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 3, 'single_choice', '洗衣机脱水时剧烈抖动，通常是什么问题？A. 电机烧坏 B. 衣物放置不平衡或减震弹簧损坏 C. 排水管堵塞 D. 电脑板程序错乱', '["B"]', '衣物不平衡或减震部件损坏是脱水抖动的主因。', 'medium', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 4, 'single_choice', '空调开机后不制冷，室外机风扇转动但压缩机不工作，最可能的故障是？A. 遥控器电池没电 B. 压缩机启动电容损坏 C. 室内机滤网堵塞 D. 室外温度传感器故障', '["B"]', '压缩机启动电容损坏是导致外机风扇转而压缩机不工作的常见原因。', 'easy', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 5, 'single_choice', '电饭煲煮饭夹生，饭熟后自动跳闸过早，应检查？A. 发热盘变形 B. 磁钢限温器 C. 保温开关 D. 电源线断路', '["B"]', '磁钢限温器过早动作会导致饭未熟就跳闸。', 'medium', '家电维修', '["家电维修","电饭煲"]', NOW(), NOW()),
(1, 6, 'single_choice', '微波炉能通电但无法加热食物，常见原因是？A. 门开关损坏 B. 磁控管或高压二极管损坏 C. 转盘电机故障 D. 炉灯烧坏', '["B"]', '磁控管或高压二极管损坏会导致微波炉不加热。', 'hard', '家电维修', '["家电维修","微波炉"]', NOW(), NOW()),
(1, 7, 'single_choice', '电热水器出水不热，加热指示灯亮，最可能的问题是？A. 温控器设置过低 B. 加热管水垢太厚或烧断 C. 进水阀关闭 D. 漏电保护器跳闸', '["B"]', '加热管水垢过厚或烧坏会导致加热指示灯亮但不热。', 'medium', '家电维修', '["家电维修","电热水器"]', NOW(), NOW()),
(1, 8, 'single_choice', '吸尘器吸力明显下降，首先应检查？A. 电机转速 B. 尘袋或滤网是否堵塞 C. 电源线接触 D. 开关触点', '["B"]', '尘袋或滤网堵塞是吸力下降的最常见原因。', 'easy', '家电维修', '["家电维修","吸尘器"]', NOW(), NOW()),
(1, 9, 'single_choice', '电风扇通电后电机嗡嗡响但扇叶不转，可能原因是？A. 定时器损坏 B. 启动电容损坏或轴承卡死 C. 调速开关短路 D. 电源插头松动', '["B"]', '启动电容损坏或轴承卡死会导致电机有嗡嗡声但不转。', 'medium', '家电维修', '["家电维修","电风扇"]', NOW(), NOW()),
(1, 10, 'single_choice', '液晶电视屏幕出现垂直彩色条纹，最可能是？A. 背光灯管老化 B. 逻辑板或屏幕排线接触不良 C. 电源板滤波电容鼓包 D. 遥控信号干扰', '["B"]', '垂直彩色条纹通常与逻辑板或排线接触有关。', 'hard', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 11, 'single_choice', '冰箱冷藏室结冰严重，温控器正常，常见原因是？A. 制冷剂过多 B. 冷藏室门封漏气或排水孔堵塞 C. 压缩机功率过大 D. 环境温度太低', '["B"]', '门封漏气或排水孔堵塞会导致冷藏室结冰。', 'medium', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 12, 'single_choice', '滚筒洗衣机不排水，应首先检查？A. 进水阀 B. 排水泵或排水管 C. 电机皮带 D. 门锁开关', '["B"]', '排水泵或排水管堵塞是滚筒洗衣机不排水的主因。', 'easy', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 13, 'single_choice', '空调出风量很小，制冷效果差，最常见故障是？A. 缺氟 B. 室内机滤网堵塞或风轮积灰 C. 室外机风扇反转 D. 压缩机卡缸', '["B"]', '滤网堵塞或风轮积灰会直接影响出风量。', 'easy', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 14, 'single_choice', '电磁炉通电后无反应，指示灯不亮，首先检查？A. IGBT功率管 B. 保险管和电源电路 C. 锅具材质 D. 控制面板按键', '["B"]', '通电无反应应先检查保险管和电源电路。', 'medium', '家电维修', '["家电维修","电磁炉"]', NOW(), NOW()),
(1, 15, 'single_choice', '燃气热水器点着火后很快熄灭，可能原因是？A. 水压太低 B. 火焰感应针或电磁阀故障 C. 电池没电 D. 排烟管过长', '["B"]', '火焰感应针故障会导致熄火保护动作。', 'medium', '家电维修', '["家电维修","燃气热水器"]', NOW(), NOW()),
(1, 16, 'single_choice', '豆浆机通电不工作，报警提示，常见原因是？A. 电机烧坏 B. 水位传感器或防溢电极短路 C. 电源线断 D. 按键粘连', '["B"]', '传感器短路会导致豆浆机报警不工作。', 'medium', '家电维修', '["家电维修","豆浆机"]', NOW(), NOW()),
(1, 17, 'single_choice', '电吹风使用中突然不发热，但电机仍转，故障在？A. 电源线 B. 加热丝或过热保护器 C. 开关触点 D. 风扇叶片', '["B"]', '加热丝烧断或过热保护器动作会导致不发热。', 'easy', '家电维修', '["家电维修","电吹风"]', NOW(), NOW()),
(1, 18, 'single_choice', '电视机遥控器失灵，按任何键无反应，首先检查？A. 电视机主板 B. 遥控器电池和晶振 C. 接收头电压 D. 屏幕排线', '["B"]', '遥控器本身问题通常优先检查电池和晶振。', 'easy', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 19, 'single_choice', '冰箱压缩机不启动，只听到轻微嗡嗡声后保护器跳开，原因是？A. 电源电压过高 B. 压缩机卡死或启动器损坏 C. 温控器开路 D. 制冷剂完全泄漏', '["B"]', '压缩机卡死或启动器损坏会导致过载保护跳开。', 'medium', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 20, 'single_choice', '洗衣机进水不止，水满后仍不洗涤，故障在？A. 进水阀卡滞或水位开关故障 B. 排水阀未关闭 C. 电机电容坏 D. 电脑板烧毁', '["A"]', '进水阀卡滞或水位开关故障会导致进水不止。', 'medium', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(1, 21, 'single_choice', '空调开机跳闸，可能原因是？A. 遥控器故障 B. 压缩机或风扇电机漏电短路 C. 滤网太脏 D. 设定温度过高', '["B"]', '压缩机或电机漏电短路会导致跳闸保护。', 'hard', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 22, 'single_choice', '电热水壶通电后水烧开不自动断电，应检查？A. 发热盘 B. 蒸汽开关或耦合器 C. 电源底座 D. 保温元件', '["B"]', '蒸汽开关故障会导致水烧开不断电。', 'medium', '家电维修', '["家电维修","电热水壶"]', NOW(), NOW()),
(1, 23, 'single_choice', '电压力锅不能升压，锅盖漏气，常见原因是？A. 限压阀堵塞 B. 密封圈老化或锅盖变形 C. 压力开关失调 D. 发热盘烧坏', '["B"]', '密封圈老化或锅盖变形是漏气的主要原因。', 'easy', '家电维修', '["家电维修","电压力锅"]', NOW(), NOW()),
(1, 24, 'single_choice', '油烟机电机转动但吸力很小，主要原因是？A. 电容容量下降 B. 油网或风轮油垢堵塞 C. 电机绕组短路 D. 开关接触不良', '["B"]', '油网或风轮堵塞会严重影响吸力。', 'easy', '家电维修', '["家电维修","油烟机"]', NOW(), NOW()),
(1, 25, 'single_choice', '消毒柜不工作，指示灯不亮，首先检查？A. 紫外线灯管 B. 保险丝和门控开关 C. 臭氧发生器 D. 电路板电容', '["B"]', '指示灯不亮应先检查电源部分的保险丝和门控开关。', 'medium', '家电维修', '["家电维修","消毒柜"]', NOW(), NOW()),
(1, 26, 'single_choice', '音响一个声道无声，首先应排除？A. 电源变压器 B. 音量电位器或喇叭线接触 C. 滤波电容 D. 散热风扇', '["B"]', '单声道无声应优先检查电位器和喇叭线接触。', 'medium', '家电维修', '["家电维修","音响"]', NOW(), NOW()),
(1, 27, 'single_choice', '电冰箱门关不严，漏冷气，原因是？A. 制冷剂多 B. 门封条老化变形或门轴歪斜 C. 温控器失灵 D. 蒸发器结霜', '["B"]', '门封条老化变形是门关不严的主因。', 'easy', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 28, 'single_choice', '洗衣机洗涤时波轮不转，电机有嗡嗡声，可能？A. 皮带断裂或波轮卡死 B. 进水阀堵塞 C. 排水管太高 D. 水位不足', '["A"]', '皮带断裂或波轮卡死会导致电机嗡嗡响但不转。', 'medium', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 29, 'single_choice', '空调制热时室外机结霜过厚不化霜，故障在？A. 缺氟 B. 化霜传感器或四通阀 C. 内机滤网 D. 遥控设定', '["B"]', '化霜传感器或四通阀故障会导致不化霜。', 'hard', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 30, 'single_choice', '电炒锅温度失控，一直加热，原因是？A. 发热盘短路 B. 温控器触点粘连或失灵 C. 电源线太细 D. 开关指示灯坏', '["B"]', '温控器触点粘连会导致持续加热。', 'medium', '家电维修', '["家电维修","电炒锅"]', NOW(), NOW()),
(1, 31, 'single_choice', '扫地机器人无法自动回充，可能？A. 电池耗尽 B. 充电极片脏污或红外传感器故障 C. 边刷脱落 D. 尘盒未装', '["B"]', '充电极片脏污或传感器故障会影响回充。', 'easy', '家电维修', '["家电维修","扫地机器人"]', NOW(), NOW()),
(1, 32, 'single_choice', '电热毯不热，指示灯亮，故障在？A. 电源插头 B. 发热丝断路或接线处断开 C. 开关二极管 D. 保险管', '["B"]', '指示灯亮说明有电，问题在发热丝或接线。', 'medium', '家电维修', '["家电维修","电热毯"]', NOW(), NOW()),
(1, 33, 'single_choice', '投影仪开机后灯泡不亮，风扇转动，常见？A. 灯泡寿命耗尽或点灯板故障 B. 镜头脏 C. 遥控器没电 D. 信号线松', '["A"]', '风扇转说明电源正常，灯泡不亮多为灯或点灯板故障。', 'medium', '家电维修', '["家电维修","投影仪"]', NOW(), NOW()),
(1, 34, 'single_choice', '电冰箱噪音很大，嗡嗡声刺耳，原因？A. 制冷剂流动声 B. 压缩机脚垫老化或管路碰撞 C. 温控器动作 D. 门封吸力', '["B"]', '压缩机脚垫老化会引起共振噪音。', 'easy', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 35, 'single_choice', '洗衣机显示故障代码E2（常见品牌），通常指？A. 进水超时 B. 排水故障或上盖未盖好 C. 电机过热 D. 电压不稳', '["B"]', 'E2代码在常见品牌中多指排水故障或上盖问题。', 'easy', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 36, 'single_choice', '空调室内机漏水，最常见原因？A. 缺氟 B. 排水管堵塞或接水盘破裂 C. 室外温度低 D. 风速太低', '["B"]', '排水管堵塞是室内机漏水的最常见原因。', 'easy', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 37, 'single_choice', '电磁炉间歇加热，故障可能为？A. 锅具不合适 B. IGBT过热或电位器接触不良 C. 风扇不转 D. 电源线细', '["B"]', 'IGBT过热保护或电位器不良会导致间歇加热。', 'hard', '家电维修', '["家电维修","电磁炉"]', NOW(), NOW()),
(1, 38, 'single_choice', '电饭煲显示E0代码，一般指？A. 无锅具 B. 上盖传感器短路或开路 C. 电压过高 D. 继电器粘连', '["B"]', 'E0代码通常表示上盖传感器故障。', 'medium', '家电维修', '["家电维修","电饭煲"]', NOW(), NOW()),
(1, 39, 'single_choice', '微波炉门关不上，不工作，原因？A. 转盘不正 B. 门钩或门锁开关损坏 C. 磁控管坏 D. 高压电容击穿', '["B"]', '门钩或门锁开关损坏会导致门关不上且不工作。', 'easy', '家电维修', '["家电维修","微波炉"]', NOW(), NOW()),
(1, 40, 'single_choice', '电冰箱冷冻室正常，冷藏室不冷，可能是？A. 压缩机坏 B. 风扇电机或风门故障（风冷） C. 缺氟 D. 温控器最高档', '["B"]', '风冷冰箱冷藏室不冷多为风扇或风门故障。', 'medium', '家电维修', '["家电维修","冰箱"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(1, 41, 'single_choice', '吸尘器电机转速忽高忽低，原因？A. 尘满 B. 调速可控硅或电机碳刷磨损 C. 电源接触 D. 开关氧化', '["B"]', '调速可控硅或碳刷磨损会导致转速不稳。', 'medium', '家电维修', '["家电维修","吸尘器"]', NOW(), NOW()),
(1, 42, 'single_choice', '空调遥控器正常，但空调无任何反应，首先查？A. 接收头电压或主板供电 B. 室外机 C. 压缩机 D. 风扇电容', '["A"]', '遥控器正常应先检查室内机接收头和主板供电。', 'medium', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 43, 'single_choice', '洗衣机不进水，嗡嗡响，原因？A. 水龙头没开 B. 进水阀滤网堵塞或电磁阀损坏 C. 水位开关漏气 D. 电脑板无输出', '["B"]', '进水阀滤网堵塞或电磁阀损坏会导致不进水。', 'easy', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 44, 'single_choice', '电吹风噪声大且有焦味，可能？A. 进风口堵 B. 电机轴磨损或风叶擦壳 C. 加热丝短路 D. 开关打火', '["B"]', '电机轴磨损或风叶擦壳会产生异常噪声。', 'medium', '家电维修', '["家电维修","电吹风"]', NOW(), NOW()),
(1, 45, 'single_choice', '燃气灶点火针有火花但点不着火，原因？A. 电池没电 B. 喷嘴堵塞或风门调节不当 C. 点火器坏 D. 熄火保护动作', '["B"]', '有火花说明点火正常，点不着多为气路问题。', 'easy', '家电维修', '["家电维修","燃气灶"]', NOW(), NOW()),
(1, 46, 'single_choice', '电视机屏幕闪烁，图像抖动，可能？A. 信号源 B. 场扫描电路或电源滤波电容失效 C. 高频头 D. 按键漏电', '["B"]', '屏幕闪烁多与场扫描或电源滤波有关。', 'hard', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 47, 'single_choice', '电热水器漏电保护插头跳闸，原因？A. 地线带电 B. 内部加热管绝缘损坏或进水 C. 温控器短路 D. 插座零火线反', '["B"]', '加热管绝缘损坏会导致漏电保护跳闸。', 'hard', '家电维修', '["家电维修","电热水器"]', NOW(), NOW()),
(1, 48, 'single_choice', '豆浆机打浆时溢出，可能是？A. 加水太少 B. 防溢电极脏污或损坏 C. 电机转速快 D. 豆子太多', '["B"]', '防溢电极脏污会导致无法检测溢浆。', 'medium', '家电维修', '["家电维修","豆浆机"]', NOW(), NOW()),
(1, 49, 'single_choice', '滚筒洗衣机门打不开，常见？A. 门锁自锁未复位或PTC发热元件坏 B. 电机没停 C. 水位未排完 D. 程序错', '["A"]', '门锁自锁未复位是打不开门的常见原因。', 'medium', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 50, 'single_choice', '空调室外机不转，室内机工作，无冷气，先查？A. 遥控模式 B. 通讯线或室外机供电继电器 C. 内机滤网 D. 室温传感器', '["B"]', '外机不转应先查通讯线和供电继电器。', 'hard', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 51, 'single_choice', '电风扇摇头功能失灵，原因？A. 电机坏 B. 摇头齿轮箱或离合拉线损坏 C. 电容坏 D. 定时器坏', '["B"]', '摇头功能失灵多为齿轮箱或离合故障。', 'easy', '家电维修', '["家电维修","电风扇"]', NOW(), NOW()),
(1, 52, 'single_choice', '电冰箱灯不亮，压缩机也不工作，首先？A. 灯泡坏 B. 电源插头或保险丝 C. 温控器 D. 启动器', '["B"]', '两者都不工作应首先检查电源。', 'easy', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 53, 'single_choice', '电烤箱温度不均匀，一侧焦一侧生，可能？A. 温控器不准 B. 加热管有一条坏或风扇故障 C. 烤盘位置 D. 门密封', '["B"]', '加热管损坏会导致温度不均匀。', 'medium', '家电维修', '["家电维修","电烤箱"]', NOW(), NOW()),
(1, 54, 'single_choice', '净水器不出水，指示灯亮，原因？A. 进水球阀关闭 B. 滤芯堵塞或增压泵故障 C. 电源适配器 D. 水管折弯', '["B"]', '指示灯亮说明有电，不出水多为滤芯或泵问题。', 'easy', '家电维修', '["家电维修","净水器"]', NOW(), NOW()),
(1, 55, 'single_choice', '电视机有图像无声音，但外接音箱有声，故障在？A. 信号源 B. 内部功放或喇叭损坏 C. 静音电路 D. 电源滤波', '["B"]', '外接音箱有声说明信号正常，问题在内部功放或喇叭。', 'medium', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 56, 'single_choice', '洗衣机洗完后衣服有油污，可能是？A. 洗涤剂少 B. 离合器漏油或桶内异物 C. 水位低 D. 程序错', '["B"]', '离合器漏油会导致衣物沾上油污。', 'medium', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 57, 'single_choice', '空调开机几分钟后停机，显示故障代码，常见？A. 设定温度到 B. 室外机散热不良或传感器故障 C. 室内温度低 D. 遥控器电池', '["B"]', '散热不良或传感器故障会导致停机保护。', 'medium', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 58, 'single_choice', '微波炉转盘不转，其他正常，原因？A. 转盘电机坏或传动轴脱落 B. 磁控管坏 C. 高压保险断 D. 门开关', '["A"]', '转盘不转且其他正常，问题在转盘电机或传动。', 'easy', '家电维修', '["家电维修","微波炉"]', NOW(), NOW()),
(1, 59, 'single_choice', '电热水壶底座发热，但壶体不热，原因？A. 开关坏 B. 耦合器接触不良或发热管烧断 C. 电源线断 D. 温控器开路', '["B"]', '耦合器接触不良会导致底座热但壶体不热。', 'medium', '家电维修', '["家电维修","电热水壶"]', NOW(), NOW()),
(1, 60, 'single_choice', '油烟机照明灯不亮，电机正常，故障？A. 灯泡坏或灯座接触 B. 电机电容 C. 控制板供电 D. 保险管', '["A"]', '电机正常说明电源有电，灯不亮多为灯泡或灯座问题。', 'easy', '家电维修', '["家电维修","油烟机"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(1, 61, 'single_choice', '电饭煲糊底，饭焦黑，原因？A. 磁钢限温器失效或触点粘连 B. 保温开关短路 C. 发热盘变形 D. 内胆变形', '["A"]', '磁钢限温器失效会导致不跳闸而糊底。', 'medium', '家电维修', '["家电维修","电饭煲"]', NOW(), NOW()),
(1, 62, 'single_choice', '电视遥控器近距离可用，远距离不行，原因？A. 电池电压低或发射管老化 B. 电视接收头 C. 阳光干扰 D. 晶振频率偏', '["A"]', '近距离可用说明接收头正常，远距离不行多为发射功率不足。', 'easy', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 63, 'single_choice', '冰箱压缩机运行，但蒸发器不结霜，管路常温，原因？A. 缺制冷剂或系统堵塞 B. 温控器最高档 C. 门封漏气 D. 环境温度过高', '["A"]', '压缩机运行但不结霜说明制冷剂泄漏或堵塞。', 'hard', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 64, 'single_choice', '洗衣机脱水时声音异常，像飞机轰鸣，原因？A. 衣物不平衡 B. 轴承磨损或内桶松动 C. 排水泵有异物 D. 皮带打滑', '["B"]', '轴承磨损会产生类似轰鸣的异常噪音。', 'medium', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 65, 'single_choice', '空调制冷时压力正常，但出风不冷，原因？A. 内机风轮转速慢或蒸发器脏 B. 外机风扇反转 C. 四通阀串气 D. 膨胀阀堵塞', '["A"]', '压力正常但出风不冷多为风量问题或蒸发器脏。', 'medium', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 66, 'single_choice', '电磁炉不加热并报警，显示E1，常见？A. 无锅或锅具不匹配 B. IGBT短路 C. 电压过高 D. 风扇不转', '["A"]', 'E1代码通常表示无锅或锅具不匹配。', 'easy', '家电维修', '["家电维修","电磁炉"]', NOW(), NOW()),
(1, 67, 'single_choice', '电压力锅煮饭不熟就泄压，原因？A. 浮子阀漏气 B. 压力开关调得过低或触点氧化 C. 密封圈老化 D. 发热盘变形', '["B"]', '压力开关过早动作会导致提前泄压。', 'hard', '家电维修', '["家电维修","电压力锅"]', NOW(), NOW()),
(1, 68, 'single_choice', '电风扇通电后电机不转，用手拨动扇叶能转，故障？A. 启动电容失效或电机轴承缺油 B. 调速开关断 C. 定时器坏 D. 插头接触', '["A"]', '拨动能转说明转子没问题，多为启动电容失效。', 'easy', '家电维修', '["家电维修","电风扇"]', NOW(), NOW()),
(1, 69, 'single_choice', '电视机开机后黑屏但声音正常，背光不亮，原因？A. 主板坏 B. 背光驱动板或灯条损坏 C. 逻辑板 D. 电源板无12V', '["B"]', '黑屏有声音且背光不亮，问题在背光驱动或灯条。', 'hard', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 70, 'single_choice', '洗衣机进水慢，很长时间才到水位，原因？A. 水压过低 B. 进水阀滤网堵塞或阀芯卡滞 C. 水位开关漏气 D. 电脑板程序', '["B"]', '进水阀滤网堵塞是最常见的进水慢原因。', 'easy', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 71, 'single_choice', '空调室外机结冰，制冷效果差，原因？A. 缺氟或内机蒸发器脏 B. 外机风扇转速慢 C. 压缩机排气不足 D. 管路压扁', '["A"]', '缺氟或蒸发器脏会导致外机结冰。', 'medium', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 72, 'single_choice', '电吹风电机不转，也不发热，首先查？A. 电源线和开关 B. 电机绕组 C. 加热丝 D. 二极管', '["A"]', '两者都不工作应首先检查电源线和开关。', 'easy', '家电维修', '["家电维修","电吹风"]', NOW(), NOW()),
(1, 73, 'single_choice', '微波炉工作时有打火现象，噼啪响，原因？A. 电压不稳 B. 云母片烧焦或炉腔油污太多 C. 高压二极管击穿 D. 转盘未放好', '["B"]', '云母片烧焦或油污会导致打火。', 'medium', '家电维修', '["家电维修","微波炉"]', NOW(), NOW()),
(1, 74, 'single_choice', '电冰箱冷冻室结冰太厚，自动除霜失效，原因？A. 门关不严 B. 除霜定时器或加热管损坏 C. 温控器常通 D. 制冷剂多', '["B"]', '除霜定时器或加热管损坏会导致不化霜。', 'medium', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 75, 'single_choice', '电热水器水温忽冷忽热，原因？A. 水压波动或混水阀故障 B. 加热管功率不稳 C. 温控器失灵 D. 进水管堵', '["A"]', '水压波动是水温不稳定的常见原因。', 'easy', '家电维修', '["家电维修","电热水器"]', NOW(), NOW()),
(1, 76, 'single_choice', '扫地机器人行进路线混乱，乱撞，可能？A. 电池电量低 B. 红外或激光传感器脏污或故障 C. 边刷损坏 D. 主刷缠发', '["B"]', '传感器脏污会导致导航混乱。', 'easy', '家电维修', '["家电维修","扫地机器人"]', NOW(), NOW()),
(1, 77, 'single_choice', '液晶电视开机图像偏红，过会儿正常，原因？A. 信号线 B. 灯管老化或逻辑板排线接触不良 C. 电源电容 D. 主板芯片虚焊', '["B"]', '开机偏红过会儿正常多为灯管老化或排线接触问题。', 'hard', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 78, 'single_choice', '洗衣机脱水时内桶不转，电机嗡嗡响，原因？A. 皮带松或脱落 B. 刹车未放开或离合器故障 C. 电容坏 D. 电脑板无输出', '["B"]', '刹车未放开或离合器故障会导致内桶不转。', 'medium', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 79, 'single_choice', '空调遥控器显示正常，但无法开关机，可能？A. 接收板受潮或受干扰 B. 室外机故障 C. 设定模式 D. 定时设置', '["A"]', '遥控器正常但无法控制多为接收板问题。', 'medium', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 80, 'single_choice', '电饭煲不保温，饭凉得快，原因？A. 保温发热丝或保温开关损坏 B. 磁钢坏 C. 内胆变形 D. 锅盖密封圈', '["A"]', '保温发热丝或开关损坏会导致不保温。', 'easy', '家电维修', '["家电维修","电饭煲"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(1, 81, 'single_choice', '电磁炉散热风扇不转，但能加热，后果？A. 无影响 B. 会过热保护或烧毁IGBT C. 噪音小 D. 功率降低', '["B"]', '风扇不转会散热不良，可能烧毁IGBT。', 'medium', '家电维修', '["家电维修","电磁炉"]', NOW(), NOW()),
(1, 82, 'single_choice', '电视机有横线干扰，滚动，原因？A. 天线 B. 电源滤波电容或300V电容失效 C. 高频头 D. 显像管老化', '["B"]', '电源滤波电容失效会导致横线干扰。', 'hard', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 83, 'single_choice', '电冰箱侧面发热严重，烫手，正常吗？A. 故障 B. 正常散热或环境温度高 C. 制冷剂多 D. 门封损坏', '["B"]', '冰箱侧面发热是正常散热现象。', 'easy', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 84, 'single_choice', '洗衣机洗涤无力，波轮转动慢，原因？A. 皮带松弛或电容容量下降 B. 电机绕组匝间短路 C. 衣物太多 D. 水位太低', '["A"]', '皮带松弛或电容容量下降会导致洗涤无力。', 'easy', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 85, 'single_choice', '空调运行一段时间后自动停机，过会重启，原因？A. 设定温度到 B. 室外机散热不良或压缩机过热保护 C. 定时关机 D. 遥控器信号', '["B"]', '散热不良导致压缩机过热会引起自动停机保护。', 'medium', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 86, 'single_choice', '电热水壶水烧开后不断电，烧干才停，危险原因是？A. 温控器变形或开关触点粘连 B. 底座进水 C. 发热管短路 D. 电源线太细', '["A"]', '温控器变形或触点粘连会导致不断电。', 'hard', '家电维修', '["家电维修","电热水壶"]', NOW(), NOW()),
(1, 87, 'single_choice', '微波炉开门后炉灯不亮，但能加热，原因？A. 灯泡坏或门开关控制 B. 磁控管坏 C. 高压保险断 D. 电脑板坏', '["A"]', '能加热说明微波正常，炉灯不亮多为灯泡问题。', 'easy', '家电维修', '["家电维修","微波炉"]', NOW(), NOW()),
(1, 88, 'single_choice', '油烟机开关按键按不下去，原因？A. 电机卡死 B. 按键机械卡滞或油污粘连 C. 电容坏 D. 电源缺相', '["B"]', '按键机械卡滞是最常见的原因。', 'easy', '家电维修', '["家电维修","油烟机"]', NOW(), NOW()),
(1, 89, 'single_choice', '电视机伴音有杂音，滋滋声，随画面变化，原因？A. 信号差 B. 电源或行辐射干扰 C. 喇叭破损 D. 音量电位器', '["B"]', '随画面变化的杂音多为电源或行辐射干扰。', 'hard', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 90, 'single_choice', '冰箱压缩机频繁启动停机，每次运行很短，原因？A. 温控器位置过高 B. 启动器或保护器接触不良 C. 制冷剂过多 D. 门未关', '["B"]', '启动器或保护器接触不良会导致频繁启停。', 'medium', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 91, 'single_choice', '电压力锅显示故障代码E4，通常指？A. 压力开关失灵 B. 温度传感器开路 C. 锅盖未合严 D. 超压保护', '["A"]', 'E4代码通常表示压力开关失灵。', 'medium', '家电维修', '["家电维修","电压力锅"]', NOW(), NOW()),
(1, 92, 'single_choice', '洗衣机进水时从洗涤剂盒溢水，原因？A. 水压过大 B. 洗涤剂盒堵塞或进水阀弹簧失效 C. 排水阀打开 D. 水位开关坏', '["B"]', '洗涤剂盒堵塞会导致进水溢水。', 'easy', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 93, 'single_choice', '空调室外机风扇不转，压缩机也不转，原因？A. 缺氟 B. 室外机供电继电器或电脑板故障 C. 风扇电容 D. 温度传感器', '["B"]', '两者都不转多为供电继电器或电脑板故障。', 'hard', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 94, 'single_choice', '电热油汀取暖器不热，指示灯亮，原因？A. 导热油漏 B. 电热管开路或温控器保护 C. 电源插座 D. 开关坏', '["B"]', '指示灯亮说明有电，不热多为电热管或温控器问题。', 'medium', '家电维修', '["家电维修","电热油汀"]', NOW(), NOW()),
(1, 95, 'single_choice', '电冰箱噪音像流水声，正常吗？A. 故障 B. 制冷剂正常流动声 C. 压缩机坏 D. 管路共振', '["B"]', '流水声是制冷剂流动的正常声音。', 'easy', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 96, 'single_choice', '电视机开机要很久才出现图像，原因？A. 显像管老化或管座受潮（老式） B. 背光驱动 C. 主板电容 D. 信号源', '["A"]', '老式电视机开机图像慢多为显像管老化或管座受潮。', 'medium', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 97, 'single_choice', '微波炉加热不均匀，一边热一边凉，原因？A. 转盘停转或波导损坏 B. 磁控管老化 C. 高压电容损坏 D. 门密封不严', '["A"]', '转盘停转会导致加热不均匀。', 'easy', '家电维修', '["家电维修","微波炉"]', NOW(), NOW()),
(1, 98, 'single_choice', '电吹风风速档正常，但热风档不热，原因？A. 发热丝烧断或过热保护器动作 B. 电机故障 C. 开关二极管击穿 D. 电源线', '["A"]', '风速正常说明电机好，热风档不热多为发热丝问题。', 'easy', '家电维修', '["家电维修","电吹风"]', NOW(), NOW()),
(1, 99, 'single_choice', '空调开机外机启动瞬间跳闸，最可能？A. 电源线细 B. 压缩机对地短路或电容击穿 C. 风扇卡死 D. 四通阀坏', '["B"]', '启动瞬间跳闸多为压缩机对地短路。', 'hard', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 100, 'single_choice', '洗衣机不能脱水，但能正常洗涤，常见？A. 门盖开关损坏或排水管堵塞 B. 电机电容坏 C. 皮带断 D. 电脑板烧', '["A"]', '能洗涤说明电机正常，不能脱水多为门开关或排水问题。', 'easy', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(1, 101, 'fill_blank', '电视机行输出变压器损坏时，通常伴有的典型气味是______。', '["高压打火的臭氧味或烧焦味"]', '高压打火会产生臭氧的特殊气味。', 'medium', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 102, 'fill_blank', '冰箱温控器感温包泄漏会导致压缩机______。', '["不启动或运转不停"]', '感温包泄漏会导致温控器失效。', 'medium', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 103, 'fill_blank', '洗衣机电机启动电容常见容量范围约______微法。', '["4-20（根据电机功率不同）"]', '不同功率电机配不同容量电容。', 'medium', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 104, 'fill_blank', '空调制冷系统缺氟时，低压压力通常低于______MPa。', '["0.4-0.45（正常约0.5）"]', '低压压力低于0.4MPa通常表示缺氟。', 'hard', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 105, 'fill_blank', '电饭煲磁钢限温器的居里温度约为______摄氏度。', '["103±2"]', '磁钢限温器在约103度时失去磁性跳闸。', 'medium', '家电维修', '["家电维修","电饭煲"]', NOW(), NOW()),
(1, 106, 'fill_blank', '微波炉高压二极管通常可用万用表______档测量其正反向特性。', '["10k"]', '高压二极管需要高阻档测量。', 'hard', '家电维修', '["家电维修","微波炉"]', NOW(), NOW()),
(1, 107, 'fill_blank', '电热水器镁棒的作用是______。', '["牺牲阳极保护内胆防止腐蚀"]', '镁棒通过电化学原理保护内胆。', 'medium', '家电维修', '["家电维修","电热水器"]', NOW(), NOW()),
(1, 108, 'fill_blank', '吸尘器电机碳刷磨损后，常见现象是______。', '["火花大、转速不稳定、噪音增大"]', '碳刷磨损会导致接触不良。', 'easy', '家电维修', '["家电维修","吸尘器"]', NOW(), NOW()),
(1, 109, 'fill_blank', '电风扇扇叶锁紧螺母旋向一般为______牙（顺时针或逆时针）。', '["逆时针（反牙）"]', '反牙设计防止旋转时松脱。', 'medium', '家电维修', '["家电维修","电风扇"]', NOW(), NOW()),
(1, 110, 'fill_blank', '液晶电视逻辑板与屏之间的连接排线称为______。', '["COF排线或软排线"]', 'COF排线负责信号传输。', 'hard', '家电维修', '["家电维修","电视机"]', NOW(), NOW()),
(1, 111, 'fill_blank', '冰箱排水孔堵塞会导致______。', '["冷藏室积水或结冰"]', '排水孔堵塞会使化霜水无法排出。', 'easy', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 112, 'fill_blank', '滚筒洗衣机门锁内部为______元件实现延时锁定。', '["PTC热敏电阻"]', 'PTC热敏电阻通电发热后双金属片动作锁定。', 'hard', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW()),
(1, 113, 'fill_blank', '空调四通阀在制冷状态时应______通电。', '["断电（制热时通电）"]', '四通阀断电时制冷，通电时换向制热。', 'medium', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 114, 'fill_blank', '电磁炉IGBT管与散热片之间必须涂抹______。', '["导热硅脂"]', '导热硅脂保证良好热传导。', 'easy', '家电维修', '["家电维修","电磁炉"]', NOW(), NOW()),
(1, 115, 'fill_blank', '电热水壶蒸汽开关内部双金属片动作原理是______。', '["受热弯曲变形"]', '双金属片受热弯曲触发开关动作。', 'medium', '家电维修', '["家电维修","电热水壶"]', NOW(), NOW()),
(1, 116, 'fill_blank', '油烟机风轮油污过多会导致______和振动。', '["吸力下降"]', '油污过多会增加风轮重量和不平衡。', 'easy', '家电维修', '["家电维修","油烟机"]', NOW(), NOW()),
(1, 117, 'fill_blank', '消毒柜紫外线灯管两端发黑说明______。', '["寿命到期或老化"]', '灯管发黑是使用寿命将尽的表现。', 'easy', '家电维修', '["家电维修","消毒柜"]', NOW(), NOW()),
(1, 118, 'fill_blank', '音响电位器旋转有噪声，可注入______清洗。', '["酒精或触点清洁剂"]', '酒精可溶解氧化物和污垢。', 'easy', '家电维修', '["家电维修","音响"]', NOW(), NOW()),
(1, 119, 'fill_blank', '电冰箱压缩机启动器分重锤式和______式。', '["PTC"]', 'PTC启动器是常见的无触点启动方式。', 'medium', '家电维修', '["家电维修","冰箱"]', NOW(), NOW()),
(1, 120, 'fill_blank', '扫地机器人边刷更换周期约为______个月。', '["3-6"]', '边刷属于易损件，需定期更换。', 'easy', '家电维修', '["家电维修","扫地机器人"]', NOW(), NOW()),
(1, 121, 'fill_blank', '投影机灯泡寿命通常约______小时。', '["2000-5000"]', '不同类型投影机灯泡寿命不同。', 'easy', '家电维修', '["家电维修","投影仪"]', NOW(), NOW()),
(1, 122, 'fill_blank', '燃气灶熄火保护装置感应针检测的是______信号。', '["离子火焰或热电偶电势"]', '感应针利用火焰导电或热电偶电势检测火焰。', 'hard', '家电维修', '["家电维修","燃气灶"]', NOW(), NOW()),
(1, 123, 'fill_blank', '电饭煲内胆变形会导致______。', '["与发热盘接触不良，煮饭效果差"]', '内胆变形会影响热传导。', 'easy', '家电维修', '["家电维修","电饭煲"]', NOW(), NOW()),
(1, 124, 'fill_blank', '空调过滤网建议清洗周期为______。', '["每2周至1个月"]', '过滤网积灰会影响空调效果和空气质量。', 'easy', '家电维修', '["家电维修","空调"]', NOW(), NOW()),
(1, 125, 'fill_blank', '洗衣机排水阀内部堵塞物常见为______。', '["硬币、纽扣、棉絮等"]', '口袋中遗留的小物件容易堵塞排水阀。', 'easy', '家电维修', '["家电维修","洗衣机"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(2, 1, 'single_choice', '以下哪种折叠方法最节省抽屉空间存放T恤？A. 平铺叠放 B. 卷折法 C. 对折再对折 D. 悬挂', '["B"]', '卷折法可以最大化利用抽屉空间且不易皱。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 2, 'single_choice', '衣柜深度通常为多少厘米时，衣架挂放最合适？A. 40cm B. 50-55cm C. 60-65cm D. 70cm', '["B"]', '50-55cm深度保证衣架不会碰到柜门。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 3, 'single_choice', '厨房刀具最安全的收纳方式是？A. 插在筷子笼里 B. 放入刀架或磁性刀条 C. 平放在抽屉里 D. 挂在抹布钩上', '["B"]', '刀架或磁性刀条既能保护刀刃又安全。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 4, 'single_choice', '冰箱冷藏室剩菜应存放在哪一层？A. 冷藏室门架 B. 最下层 C. 中间层靠后壁 D. 任意位置', '["C"]', '中间层靠后壁温度最稳定。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 5, 'single_choice', '袜子收纳时，以下哪种方法最方便配对且节省空间？A. 两只团成球 B. 一只套一只卷起 C. 平铺叠放 D. 夹子夹住', '["B"]', '一只套一只卷起方便配对且节省空间。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 6, 'single_choice', '衣柜悬挂区上部较难拿取的位置，适合存放？A. 当季常穿外套 B. 换季衣物或被子 C. 裤子 D. 领带', '["B"]', '高处适合存放不常用的换季物品。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 7, 'single_choice', '鞋柜每层高度设计为多少厘米可收纳多数平底鞋和高跟鞋？A. 10cm B. 15-20cm C. 25-30cm D. 40cm', '["B"]', '15-20cm可容纳多数鞋型。', 'easy', '收纳整理', '["收纳整理","鞋柜"]', NOW(), NOW()),
(2, 8, 'single_choice', '厨房抽屉内分隔收纳盒的主要作用是？A. 美观 B. 防止小件物品乱滚 C. 增加容量 D. 防潮', '["B"]', '分隔盒让餐具分类摆放，整齐有序。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 9, 'single_choice', '儿童玩具收纳，以下哪种方式最有利于培养孩子自己收拾的习惯？A. 大型收纳箱 B. 透明带盖浅盒并贴标签 C. 堆放在角落 D. 挂在墙上', '["B"]', '透明标签盒让孩子容易找到和归位。', 'easy', '收纳整理', '["收纳整理","儿童收纳"]', NOW(), NOW()),
(2, 10, 'single_choice', '卫生间化妆品收纳，应优先考虑？A. 美观玻璃瓶 B. 防潮防水的收纳盒或柜 C. 开放式层板 D. 悬挂塑料袋', '["B"]', '卫生间潮湿，防潮防水最重要。', 'medium', '收纳整理', '["收纳整理","卫生间收纳"]', NOW(), NOW()),
(2, 11, 'single_choice', '换季衣物收纳前，必须做的步骤是？A. 熨烫平整 B. 清洁干燥后再收纳 C. 喷香水 D. 折叠成小方块', '["B"]', '清洁干燥可防止发霉和虫蛀。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 12, 'single_choice', '零碎小物如数据线、耳机，最佳收纳工具是？A. 塑料袋 B. 带分隔的收纳盒或理线包 C. 随意放抽屉 D. 夹子夹在桌边', '["B"]', '分隔收纳盒可避免缠绕丢失。', 'easy', '收纳整理', '["收纳整理","数码收纳"]', NOW(), NOW()),
(2, 13, 'single_choice', '衣柜内挂裤子时，以下哪种工具最节省空间？A. 普通衣架 B. 裤夹或多层裤架 C. S钩 D. 折叠挂', '["B"]', '多层裤架可一条垂直空间挂多条裤子。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 14, 'single_choice', '冰箱门架适合存放什么物品？A. 生肉 B. 鸡蛋 C. 开封的酱料和饮料 D. 剩菜', '["C"]', '门架温度波动大，适合存放酱料饮料。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 15, 'single_choice', '使用真空压缩袋收纳羽绒服的主要好处是？A. 防虫 B. 减少体积 C. 防霉 D. 保持蓬松', '["B"]', '真空压缩可大幅减少羽绒服体积。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 16, 'single_choice', '厨房调味品瓶罐收纳时，以下哪种原则最合理？A. 全部装进柜子里 B. 常用放台面小架，不常用入柜 C. 按瓶子颜色排列 D. 越高越好', '["B"]', '常用与不常用分开可提高效率。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 17, 'single_choice', '书桌抽屉浅层最适合收纳？A. 书本 B. 文具、回形针、便签纸 C. 文件夹 D. 充电宝', '["B"]', '浅层适合拿取频繁的小件文具。', 'easy', '收纳整理', '["收纳整理","办公收纳"]', NOW(), NOW()),
(2, 18, 'single_choice', '被褥收纳在床下时，最好使用？A. 普通纸箱 B. 无纺布或牛津布带拉链的扁平收纳箱 C. 塑料袋 D. 直接铺床板下', '["B"]', '扁平收纳箱防尘且充分利用床下空间。', 'easy', '收纳整理', '["收纳整理","被褥收纳"]', NOW(), NOW()),
(2, 19, 'single_choice', '衣帽间中，换季鞋子正确收纳方式是？A. 保持原鞋盒堆叠 B. 放入透明鞋盒或鞋柜并标注照片 C. 所有鞋摆在门口 D. 塞进衣柜顶柜', '["B"]', '透明鞋盒方便查找且保护鞋子。', 'easy', '收纳整理', '["收纳整理","鞋柜"]', NOW(), NOW()),
(2, 20, 'single_choice', '卫生间拖把、扫把等长柄清洁工具，最佳收纳方式是？A. 靠墙角落 B. 使用挂钩挂墙或落地式夹 C. 平躺在地上 D. 插在洗衣机侧面', '["B"]', '挂墙收纳节省空间且通风易干。', 'easy', '收纳整理', '["收纳整理","卫生间收纳"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(2, 21, 'single_choice', '药箱收纳时，内服药和外用药应？A. 混放 B. 分格或分层放置并标注 C. 都放一起扎紧 D. 外用药扔冰箱', '["B"]', '内外用药应分开避免误用。', 'easy', '收纳整理', '["收纳整理","药品收纳"]', NOW(), NOW()),
(2, 22, 'single_choice', '厨房水槽下方柜子容易潮湿，适合收纳？A. 大米面粉 B. 锅具 C. 清洁剂、百洁布等不怕湿的物品 D. 纸质菜谱', '["C"]', '水槽下方潮湿，适合放不怕湿的清洁用品。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 23, 'single_choice', '衣柜内百纳箱（布艺收纳箱）适合装什么？A. 易皱衬衫 B. 过季毛衣、围巾 C. 西装 D. 皮带', '["B"]', '百纳箱适合存放不易皱的过季衣物。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 24, 'single_choice', '叠放牛仔裤时，为了减少折痕，最好？A. 卷起来 B. 沿裤线折叠 C. 对折一次 D. 悬挂', '["A"]', '卷起来可减少折痕且节省空间。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 25, 'single_choice', '客厅遥控器、眼镜等小杂物，应使用？A. 茶几表面随意放 B. 遥控器收纳盒或托盘 C. 塞进沙发缝 D. 放进抽屉最底层', '["B"]', '收纳盒可集中小杂物，保持桌面整洁。', 'easy', '收纳整理', '["收纳整理","客厅收纳"]', NOW(), NOW()),
(2, 26, 'single_choice', '冰箱冷冻室收纳肉类，最佳方式为？A. 大块冷冻 B. 按每餐份量分装密封并标注日期 C. 带原包装堆放 D. 全部解冻再冻', '["B"]', '分装标注便于按需取用，避免反复解冻。', 'medium', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 27, 'single_choice', '化妆刷收纳时，竖插在什么容器中最干净？A. 带盖密封罐 B. 敞口笔筒或珍珠粒填充的刷筒 C. 直接放抽屉 D. 用皮筋扎一起', '["B"]', '竖插保持刷毛形状且通风防尘。', 'easy', '收纳整理', '["收纳整理","化妆品收纳"]', NOW(), NOW()),
(2, 28, 'single_choice', '衣柜悬挂区高度有限时，挂长裙会拖底，应？A. 折叠悬挂 B. 用多个衣架拉长 C. 使用可调节长度的衣架或改挂别处 D. 剪短裙子', '["C"]', '可调节衣架或换位置是最优解。', 'medium', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 29, 'single_choice', '使用标签机给收纳盒贴标签的主要目的是？A. 好看 B. 快速找到物品，家人也能归位 C. 防拆 D. 计数', '["B"]', '标签让收纳系统对所有人都清晰。', 'easy', '收纳整理', '["收纳整理","标签管理"]', NOW(), NOW()),
(2, 30, 'single_choice', '厨房保鲜膜、铝箔纸等长条盒装物品，如何收纳最好？A. 竖放在抽屉分隔栏内 B. 平堆在台面 C. 挂在门后 D. 塞进微波炉', '["A"]', '竖放可节省空间且取用方便。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 31, 'single_choice', '居家证件、说明书、保修卡等纸品，最佳收纳方式是？A. 夹在书里 B. 用活页文件夹分类存放并标注 C. 散放在抽屉 D. 贴冰箱门上', '["B"]', '活页文件夹分类便于查找和管理。', 'medium', '收纳整理', '["收纳整理","文件收纳"]', NOW(), NOW()),
(2, 32, 'single_choice', '床上四件套（床单被套）折叠后，最好放在？A. 床底收纳袋 B. 衣柜最上层或配套的收纳袋内，与同套放一起 C. 枕头下 D. 洗衣机上', '["B"]', '同套存放方便换洗时取用。', 'easy', '收纳整理', '["收纳整理","被褥收纳"]', NOW(), NOW()),
(2, 33, 'single_choice', '儿童画笔、彩泥等美术用品，适合使用？A. 带隔层的透明收纳盒 B. 鞋盒 C. 超市袋 D. 书包里', '["A"]', '透明分隔盒方便孩子自取和归位。', 'easy', '收纳整理', '["收纳整理","儿童收纳"]', NOW(), NOW()),
(2, 34, 'single_choice', '厨房锅盖收纳，以下哪种方法最省空间？A. 倒扣在锅上 B. 使用锅盖架或门背挂架 C. 平放抽屉 D. 靠墙斜立', '["B"]', '锅盖架或门背挂架可有效利用垂直空间。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 35, 'single_choice', '行李箱空置不用时，最好收纳于？A. 放满杂物 B. 内部可放换季被褥，节省空间 C. 放在阳台暴晒 D. 拆开存放', '["B"]', '行李箱内可收纳不常用的被褥。', 'easy', '收纳整理', '["收纳整理","行李箱收纳"]', NOW(), NOW()),
(2, 36, 'single_choice', '衣柜抽屉内折叠衣物立起来摆放（竖向放置）的主要优点是？A. 不易皱 B. 抽取时不会弄乱其他衣物 C. 叠得快 D. 更透气', '["B"]', '竖向叠放让每件衣服都独立可见。', 'medium', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 37, 'single_choice', '电线收纳扎带或理线管的主要作用是？A. 防电 B. 美观防缠绕 C. 增加长度 D. 防水', '["B"]', '扎带和理线管让电线不再杂乱缠绕。', 'easy', '收纳整理', '["收纳整理","数码收纳"]', NOW(), NOW()),
(2, 38, 'single_choice', '冰箱冷藏室果蔬盒适合存放？A. 剩饭 B. 苹果、绿叶菜等需保湿的果蔬 C. 鸡蛋 D. 饮料', '["B"]', '果蔬盒设计为高湿度环境，适合存放果蔬。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 39, 'single_choice', '钥匙、钱包、口罩等出门零碎物品，应在玄关设置？A. 堆在鞋柜面 B. 托盘或小挂架 C. 放在口袋里 D. 扔地上', '["B"]', '玄关托盘方便出门前拿取必需品。', 'easy', '收纳整理', '["收纳整理","玄关收纳"]', NOW(), NOW()),
(2, 40, 'single_choice', '衣柜裤架上最多可以挂几条裤子不拥挤？A. 1条 B. 3-5条（多层裤架） C. 10条 D. 20条', '["B"]', '3-5条是合适的数量，过多会拥挤变形。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(2, 41, 'single_choice', '儿童房积木、乐高等小块玩具，收纳时宜选用？A. 大开口浅盒 B. 深桶 C. 网袋 D. 塑料袋', '["A"]', '浅盒方便孩子翻找和收拾。', 'easy', '收纳整理', '["收纳整理","儿童收纳"]', NOW(), NOW()),
(2, 42, 'single_choice', '梳妆台首饰收纳，以下哪种方式最防氧化？A. 敞开托盘 B. 带内衬的密封首饰盒 C. 塑料袋 D. 梳妆台面', '["B"]', '密封盒可减少空气接触，延缓氧化。', 'medium', '收纳整理', '["收纳整理","首饰收纳"]', NOW(), NOW()),
(2, 43, 'single_choice', '厨房干货如木耳、粉丝，应收纳于？A. 敞口碗 B. 密封罐或夹链袋，标注名称和日期 C. 原塑料包装 D. 冰箱冷冻', '["B"]', '密封储存可防潮防虫，标注便于查看。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 44, 'single_choice', '门后挂钩适合挂什么物品？A. 湿毛巾 B. 围裙、帆布包、次日外套 C. 吹风机 D. 生鲜食品', '["B"]', '门后挂钩适合挂常用轻便物品。', 'easy', '收纳整理', '["收纳整理","门后收纳"]', NOW(), NOW()),
(2, 45, 'single_choice', '衣柜顶层通常较高，最不适合收纳？A. 换季被褥 B. 冬季厚大衣 C. 每天穿的T恤 D. 行李箱', '["C"]', '每天穿的衣物应放在顺手位置。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 46, 'single_choice', '卫生间纸巾、洗浴备用品囤货，应收纳在？A. 马桶水箱上 B. 干区柜子或浴室柜下方密封 C. 浴缸边 D. 淋浴房内', '["B"]', '囤货应存放在干燥区域避免受潮。', 'easy', '收纳整理', '["收纳整理","卫生间收纳"]', NOW(), NOW()),
(2, 47, 'single_choice', '清洁用品如抹布、刷子，收纳时应注意？A. 混放一起 B. 悬挂晾干，分用途挂放 C. 塞进柜子 D. 放洗衣机', '["B"]', '悬挂晾干可防止细菌滋生。', 'easy', '收纳整理', '["收纳整理","清洁用品收纳"]', NOW(), NOW()),
(2, 48, 'single_choice', '柜子深处不好拿的物品，可利用什么工具？A. 伸缩杆 B. 带滑轮的收纳箱或拉篮 C. 胶带 D. 绳子', '["B"]', '滑轮收纳箱可轻松拉出取物。', 'easy', '收纳整理', '["收纳整理","柜子收纳"]', NOW(), NOW()),
(2, 49, 'single_choice', '家庭文件收纳中，重要证件（房产证、户口本）应？A. 与普通说明书一起 B. 单独防火防水文件袋存放 C. 夹在书中 D. 压在床垫下', '["B"]', '重要证件应单独安全存放。', 'medium', '收纳整理', '["收纳整理","文件收纳"]', NOW(), NOW()),
(2, 50, 'single_choice', '叠衣服时，口袋应如何处理？A. 不处理 B. 翻出来抖干净并理平 C. 塞回去 D. 剪掉', '["B"]', '翻出理平可防止口袋鼓起变形。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 51, 'single_choice', '儿童书包、帽子等小件，应设置？A. 孩子身高可及的挂钩或矮柜 B. 高处 C. 地上 D. 抽屉底部', '["A"]', '让孩子能够自己挂取，培养独立性。', 'easy', '收纳整理', '["收纳整理","儿童收纳"]', NOW(), NOW()),
(2, 52, 'single_choice', '冰箱内食物收纳，生熟应？A. 混放 B. 分开分层，熟食在上，生食在下 C. 熟食放门架 D. 无所谓', '["B"]', '生熟分开防止交叉污染。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 53, 'single_choice', '衣柜中毛衣长时间悬挂会导致？A. 发霉 B. 变形拉长 C. 掉色 D. 缩水', '["B"]', '毛衣重力作用下会拉长变形，应折叠存放。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 54, 'single_choice', '厨房调料瓶使用统一分装瓶的好处是？A. 看着整齐 B. 避免原包装大小不一，提高空间利用率 C. 保质期更长 D. 更便宜', '["B"]', '统一容器可规整排列，节省空间。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 55, 'single_choice', '搬家时，餐具（碗盘）的最佳包装方式是？A. 报纸包 B. 气泡膜或布包裹，竖直叠放于带隔层的纸箱 C. 直接堆叠 D. 用塑料袋', '["B"]', '竖直叠放可减少碰撞破损。', 'medium', '收纳整理', '["收纳整理","搬家收纳"]', NOW(), NOW()),
(2, 56, 'single_choice', '衣帽钩安装在玄关的高度最好为？A. 10cm B. 140-160cm（成人顺手）及低处为孩子 C. 200cm D. 任意', '["B"]', '多高度设计方便全家使用。', 'easy', '收纳整理', '["收纳整理","玄关收纳"]', NOW(), NOW()),
(2, 57, 'single_choice', '储物间沿墙设置层板，层板深度宜为？A. 20cm B. 40-50cm，但配合收纳箱使用 C. 80cm D. 10cm', '["B"]', '40-50cm深度适合多数收纳箱尺寸。', 'medium', '收纳整理', '["收纳整理","储物间收纳"]', NOW(), NOW()),
(2, 58, 'single_choice', '书籍收纳，为避免倾倒，应？A. 斜靠 B. 使用书立或紧密直立排列 C. 平堆 D. 随意塞', '["B"]', '书立固定可防止书籍倾倒变形。', 'easy', '收纳整理', '["收纳整理","书籍收纳"]', NOW(), NOW()),
(2, 59, 'single_choice', '衣柜内可调节隔板的作用是？A. 美观 B. 根据衣物高度灵活调整空间，减少浪费 C. 承重 D. 防虫', '["B"]', '可调节设计让衣柜更灵活实用。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 60, 'single_choice', '内衣、内裤收纳，最好使用？A. 塑料袋 B. 带分隔的抽屉盒，单独格位存放 C. 与袜子混放 D. 悬挂', '["B"]', '分隔盒让内衣裤整齐卫生。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(2, 61, 'single_choice', '充电线收纳时，用魔术贴理线带绑好后，最好？A. 放一起 B. 分别放入小自封袋并标注（安卓/苹果） C. 缠绕在充电头上 D. 扔掉', '["B"]', '分类标注便于快速识别使用。', 'easy', '收纳整理', '["收纳整理","数码收纳"]', NOW(), NOW()),
(2, 62, 'single_choice', '灶台旁常用锅铲、汤勺，应如何收纳？A. 抽屉里 B. 壁挂或灶台旁专用厨具筒 C. 放在洗菜池 D. 塞进柜子', '["B"]', '壁挂或厨具筒方便烹饪时取用。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 63, 'single_choice', '换季衣物使用真空袋后，应放置在？A. 潮湿地下室 B. 通风干燥处，避免锐物刺破 C. 暖气片上 D. 阳台直晒', '["B"]', '干燥通风处可防潮防损。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 64, 'single_choice', '健身瑜伽垫卷起后，最好用？A. 绳子捆 B. 魔术贴绑带固定，立放于门后或角落 C. 平铺地上 D. 塞进沙发底', '["B"]', '魔术贴绑带方便，立放节省空间。', 'easy', '收纳整理', '["收纳整理","运动用品收纳"]', NOW(), NOW()),
(2, 65, 'single_choice', '电脑桌面上线缆杂乱，可使用？A. 不理 B. 桌面线槽盒或理线器 C. 胶带粘 D. 剪刀剪', '["B"]', '线槽盒让桌面整洁美观。', 'easy', '收纳整理', '["收纳整理","办公收纳"]', NOW(), NOW()),
(2, 66, 'single_choice', '冰箱鸡蛋收纳，哪种方式最安全且节省空间？A. 原纸盒 B. 专用鸡蛋抽屉或侧放蛋架 C. 塑料袋 D. 冷冻', '["B"]', '专用蛋架保护鸡蛋且节省空间。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 67, 'single_choice', '袜子、内裤等小件衣物，在抽屉内使用蜂窝格收纳格的优点是？A. 透气 B. 一目了然，拿取一个不会乱 C. 防虫 D. 折叠简单', '["B"]', '蜂窝格让每件小衣物独立放置。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 68, 'single_choice', '厨房垃圾袋、保鲜袋等卷状物品，可用？A. 散放 B. 伸缩杆或挂杆贯穿轴心悬挂收纳 C. 塞在水槽下 D. 放冰箱', '["B"]', '贯穿悬挂取用方便且整洁。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 69, 'single_choice', '首饰收纳中，项链容易缠绕，应？A. 卷成一团 B. 悬挂或平铺在带钩的首饰盒内 C. 放一起 D. 用纸包', '["B"]', '悬挂或独立放置可避免缠绕。', 'medium', '收纳整理', '["收纳整理","首饰收纳"]', NOW(), NOW()),
(2, 70, 'single_choice', '衣柜内不适合使用大量小型衣架的原因是？A. 浪费空间，导致衣物拥挤变形 B. 太贵 C. 太重 D. 不好看', '["A"]', '小衣架会导致衣物拥挤且浪费空间。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 71, 'single_choice', '行李箱内收纳时，鞋子应放在？A. 和衣服混放 B. 鞋袋或浴帽包好，放行李箱底部角落 C. 放行李箱外部 D. 行李箱拉杆侧', '["B"]', '鞋子包好后放底部可避免弄脏衣物。', 'easy', '收纳整理', '["收纳整理","行李箱收纳"]', NOW(), NOW()),
(2, 72, 'single_choice', '厨房抽屉内餐具（刀叉勺）竖插式收纳比平放的优势是？A. 拿取方便，节省横向空间 B. 更干净 C. 不容易丢 D. 更美观', '["A"]', '竖插式让每件餐具都可见可取。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 73, 'single_choice', '冰箱冷冻室冰淇淋、冻水果等软质食物，应？A. 直接放 B. 先冷冻定型后再垂直摆放，避免挤压 C. 解冻再冻 D. 放在门架', '["B"]', '先定型可防止食物粘连变形。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 74, 'single_choice', '化妆棉、棉签等小物，适合放在？A. 开放式盒子 B. 带盖透明分格盒，防尘防潮 C. 抽屉角落 D. 口袋', '["B"]', '带盖盒防尘防潮，透明分格方便取用。', 'easy', '收纳整理', '["收纳整理","化妆品收纳"]', NOW(), NOW()),
(2, 75, 'single_choice', '家居维修工具如锤子、螺丝刀，应？A. 散放工具箱 B. 使用工具收纳板或带分隔的工具箱，按类别分 C. 放厨房 D. 扔阳台', '["B"]', '分类收纳便于快速找到所需工具。', 'easy', '收纳整理', '["收纳整理","工具收纳"]', NOW(), NOW()),
(2, 76, 'single_choice', '展示纪念品、奖杯等，应放在？A. 带玻璃门的展示柜防尘 B. 敞开架子落灰 C. 纸箱 D. 地面', '["A"]', '展示柜可防尘且美观。', 'easy', '收纳整理', '["收纳整理","展示收纳"]', NOW(), NOW()),
(2, 77, 'single_choice', '孩子奶粉、米粉等罐装食品，开封后应？A. 原罐随意放 B. 密封并标注开封日期，放阴凉干燥处 C. 放冰箱 D. 倒出塑料袋', '["B"]', '密封标注便于掌握保质期。', 'easy', '收纳整理', '["收纳整理","食品收纳"]', NOW(), NOW()),
(2, 78, 'single_choice', '衣柜里睡衣和家居服最适合放在？A. 悬挂区 B. 抽屉或开放格，伸手可及 C. 顶柜 D. 行李箱', '["B"]', '常用衣物应放在最顺手的位置。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 79, 'single_choice', '电线过长的电源适配器，多余线长可？A. 剪断 B. 用理线管或扎带缩短整理 C. 绕在电源上 D. 不管', '["B"]', '理线管可整齐收纳多余线长。', 'easy', '收纳整理', '["收纳整理","数码收纳"]', NOW(), NOW()),
(2, 80, 'single_choice', '冰箱冷藏室门架放饮料时，过重会导致？A. 冷藏效果好 B. 门架变形或铰链损坏 C. 省电 D. 无异味', '["B"]', '过重会损坏门架和铰链。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(2, 81, 'single_choice', '办公桌面上笔筒应选择？A. 浅口 B. 带分类隔层的稳固笔筒 C. 深口罐 D. 纸杯', '["B"]', '分类笔筒让不同笔具各归其位。', 'easy', '收纳整理', '["收纳整理","办公收纳"]', NOW(), NOW()),
(2, 82, 'single_choice', '换季被褥在压缩袋中存放过久，取出后应？A. 直接使用 B. 晾晒或低温烘干使其恢复蓬松 C. 水洗 D. 扔掉', '["B"]', '晾晒可恢复被褥蓬松度并除味。', 'easy', '收纳整理', '["收纳整理","被褥收纳"]', NOW(), NOW()),
(2, 83, 'single_choice', '儿童衣柜设计时，挂衣杆高度应？A. 与成人相同 B. 孩子身高±20cm，使其能自主挂取 C. 越高越好 D. 越低越好', '["B"]', '适中的高度培养孩子自理能力。', 'easy', '收纳整理', '["收纳整理","儿童收纳"]', NOW(), NOW()),
(2, 84, 'single_choice', '收纳箱叠放时，需注意？A. 重的在下，轻的在上 B. 任意 C. 重的在上 D. 不分', '["A"]', '重物在下可防止倒塌和压坏。', 'easy', '收纳整理', '["收纳整理","收纳箱使用"]', NOW(), NOW()),
(2, 85, 'single_choice', '厨房台面小家电（如电饭煲、水壶）收纳，应？A. 全部放台面 B. 常用留台面，不常用收纳柜中 C. 全部入柜 D. 放地上', '["B"]', '台面只留常用品可保持整洁。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 86, 'single_choice', '衣柜挂放西装时，应使用？A. 细铁丝衣架 B. 宽柄专用西服衣架，保持肩部形状 C. 裤架 D. S型衣架', '["B"]', '宽柄衣架可保持西装肩部挺括。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 87, 'single_choice', '冰箱抽屉式收纳盒比起敞开式搁板的好处是？A. 便宜 B. 拉出即可拿取后部物品，避免遗忘 C. 更容易结冰 D. 不透明', '["B"]', '抽屉设计让深处物品也能轻松取到。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 88, 'single_choice', '药盒内应每半年做一次？A. 烘干 B. 检查并清理过期药品 C. 加水 D. 晒太阳', '["B"]', '定期清理过期药品保证用药安全。', 'easy', '收纳整理', '["收纳整理","药品收纳"]', NOW(), NOW()),
(2, 89, 'single_choice', '门后挂鞋袋通常不推荐放重鞋的原因是？A. 不美观 B. 导致门铰链受损或开关不便 C. 容易脏 D. 找不到鞋', '["B"]', '重鞋会加重门铰链负担。', 'easy', '收纳整理', '["收纳整理","门后收纳"]', NOW(), NOW()),
(2, 90, 'single_choice', '衣柜内使用透明收纳盒比不透明的好处是？A. 便宜 B. 一目了然内容物，无需翻找 C. 更轻 D. 防虫', '["B"]', '透明设计让内容物一目了然。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 91, 'single_choice', '书桌上文件架应选择？A. 无分隔 B. 多层直立式，按项目分类 C. 平铺大盒子 D. 塑料袋', '["B"]', '直立式文件架节省桌面空间且分类清晰。', 'easy', '收纳整理', '["收纳整理","文件收纳"]', NOW(), NOW()),
(2, 92, 'single_choice', '冰箱冷藏室剩菜覆盖保鲜膜后，最好？A. 任意放 B. 贴标签注明日期，方便按时间先后食用 C. 放门架 D. 不盖', '["B"]', '标注日期可掌握食物存放时间。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 93, 'single_choice', '衣架材质选择，挂湿衣应选？A. 木质 B. 塑料或浸塑防滑衣架 C. 金属裸线 D. 绒面', '["B"]', '防滑衣架可防止湿衣滑落。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 94, 'single_choice', '清洁剂收纳在原瓶不换容器，但应注意？A. 保留原标签，放置于儿童不可及处 B. 倒入饮料瓶 C. 混合存放 D. 放厨房', '["A"]', '保留标签可避免误用，远离儿童保安全。', 'easy', '收纳整理', '["收纳整理","清洁用品收纳"]', NOW(), NOW()),
(2, 95, 'single_choice', '衣柜抽屉深度太深，衣物只放一半浪费空间，可用？A. 填充泡沫 B. 抽屉内加分隔板或小收纳盒分成两层 C. 不管 D. 抽屉倒放', '["B"]', '分隔或分层可充分利用垂直空间。', 'medium', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 96, 'single_choice', '儿童图书收纳，应使封面朝前展示还是书脊朝外？A. 书脊朝外节省空间 B. 封面朝前更易吸引孩子拿取 C. 无区别 D. 堆叠', '["B"]', '封面朝前更容易吸引孩子阅读兴趣。', 'easy', '收纳整理', '["收纳整理","儿童收纳"]', NOW(), NOW()),
(2, 97, 'single_choice', '洗脸池周边的牙刷、牙膏，应？A. 放台面 B. 挂墙漱口杯或镜柜内，保持干爽 C. 放抽屉 D. 放淋浴房', '["B"]', '挂墙或镜柜内可保持干爽卫生。', 'easy', '收纳整理', '["收纳整理","卫生间收纳"]', NOW(), NOW()),
(2, 98, 'single_choice', '冰箱冷冻室长期囤积食材，应遵循？A. 先进先出原则，定期清理 B. 只管往里塞 C. 全部扔掉重买 D. 不标记', '["A"]', '先进先出避免食材过期浪费。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 99, 'single_choice', '铁丝衣架挂钩容易损坏衣物领口，最好？A. 用胶带缠 B. 用热缩管或换成塑料衣架 C. 继续用 D. 反着挂', '["B"]', '塑料衣架或加保护套可保护领口。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 100, 'single_choice', '衣柜内长条储存空间（如侧面窄缝），适合用？A. 闲置 B. 窄缝推车或鞋架 C. 放大箱子 D. 堆杂物', '["B"]', '窄缝推车可完美利用被忽视的空间。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(2, 101, 'fill_blank', 'T恤卷折法存放于抽屉内，最常见的摆放方式是______。', '["竖向排列（像放书一样）"]', '竖向排列让每件T恤都可见可取。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 102, 'fill_blank', '冰箱冷藏室温度应设置在______摄氏度左右，利于食物保鲜且不过耗电。', '["3-5"]', '3-5℃是冷藏室的最佳温度范围。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 103, 'fill_blank', '衣柜内方便拿取的黄金区域是______。', '["视线到腰部高度（约60-150cm）"]', '黄金区域应存放最常用的衣物。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 104, 'fill_blank', '丝巾、领带等小件丝织品，最好使用______式衣架或专用挂袋。', '["多孔围巾架"]', '多孔设计可整齐悬挂多条丝巾。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 105, 'fill_blank', '真空压缩袋抽气后体积可缩小至原来的______。', '["1/3到1/2"]', '真空压缩可显著减小体积。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 106, 'fill_blank', '厨房抽屉分隔盒的材质宜选用______，方便清洗。', '["塑料或硅胶"]', '塑料硅胶材质防水易清洁。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 107, 'fill_blank', '收纳箱标签应贴在箱体的______面，以便叠放时仍能看清。', '["侧面"]', '侧面标签在叠放时仍可见。', 'easy', '收纳整理', '["收纳整理","标签管理"]', NOW(), NOW()),
(2, 108, 'fill_blank', '鞋柜底部留空______厘米，可放置常穿的拖鞋。', '["15-20"]', '底部留空便于换鞋和收纳常穿鞋。', 'easy', '收纳整理', '["收纳整理","鞋柜"]', NOW(), NOW()),
(2, 109, 'fill_blank', '卧室衣柜内，被褥类物品收纳于______部。', '["顶"]', '被褥体积大且不常用，适合放顶部。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 110, 'fill_blank', '使用伸缩分隔板可以将抽屉分为多个______。', '["独立单元格"]', '分隔板让抽屉空间更有条理。', 'easy', '收纳整理', '["收纳整理","抽屉收纳"]', NOW(), NOW()),
(2, 111, 'fill_blank', '冰箱门架温度波动大，不适合存放______。', '["鸡蛋或鲜奶"]', '门架温度波动影响鲜奶鸡蛋的保质期。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 112, 'fill_blank', '化妆刷长期裸放桌面容易______。', '["沾灰滋生细菌"]', '裸放易积灰且滋生细菌。', 'easy', '收纳整理', '["收纳整理","化妆品收纳"]', NOW(), NOW()),
(2, 113, 'fill_blank', '换季衣物收纳前必须保证______。', '["完全干燥"]', '干燥可防止发霉。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 114, 'fill_blank', '儿童房玩具收纳盒最好选用______色或透明的，方便孩子辨认。', '["浅色或透明"]', '浅色透明盒让孩子能看到内部玩具。', 'easy', '收纳整理', '["收纳整理","儿童收纳"]', NOW(), NOW()),
(2, 115, 'fill_blank', '厨房调味品收纳架应远离______。', '["灶台高温和蒸汽"]', '远离高温可防止调味品变质。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 116, 'fill_blank', '电线收纳扎带使用后应______存放。', '["分类按设备单独捆绑"]', '分类捆绑避免电线混淆。', 'easy', '收纳整理', '["收纳整理","数码收纳"]', NOW(), NOW()),
(2, 117, 'fill_blank', '衣柜挂衣杆高度根据使用者身高，通常为______厘米。', '["身高+30左右（约170-190cm）"]', '合适的高度便于取挂衣物。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW()),
(2, 118, 'fill_blank', '床底收纳箱选购时注意高度不超过______厘米，以免塞不进。', '["15-20"]', '标准床底高度约15-20cm。', 'easy', '收纳整理', '["收纳整理","被褥收纳"]', NOW(), NOW()),
(2, 119, 'fill_blank', '冰箱冷冻肉类分装后，应标注______和名称。', '["日期"]', '标注日期可掌握存放时间。', 'easy', '收纳整理', '["收纳整理","冰箱收纳"]', NOW(), NOW()),
(2, 120, 'fill_blank', '卫生间镜柜深度通常为______厘米，能收纳化妆品又不易碰头。', '["10-15"]', '10-15cm深度适合化妆品且不碰头。', 'easy', '收纳整理', '["收纳整理","卫生间收纳"]', NOW(), NOW()),
(2, 121, 'fill_blank', '玄关钥匙托盘材质建议选用______，防止滑落刮花。', '["软木、皮革或塑料"]', '柔软材质可保护桌面和钥匙。', 'easy', '收纳整理', '["收纳整理","玄关收纳"]', NOW(), NOW()),
(2, 122, 'fill_blank', '大型储物架层板间距可调节，原则是______。', '["存放物品高度+5cm余量"]', '加余量方便取放物品。', 'easy', '收纳整理', '["收纳整理","储物架"]', NOW(), NOW()),
(2, 123, 'fill_blank', '袜子配对收纳时，常见的错误做法是______。', '["两只团成一个大球（易变形）"]', '团成球会拉伸袜口导致变形。', 'easy', '收纳整理', '["收纳整理","衣物收纳"]', NOW(), NOW()),
(2, 124, 'fill_blank', '厨房过期食品清理频率建议为______。', '["每月一次"]', '每月检查清理可保证食品安全。', 'easy', '收纳整理', '["收纳整理","厨房收纳"]', NOW(), NOW()),
(2, 125, 'fill_blank', '衣柜中挂放皮衣需使用______衣架并套防尘袋。', '["宽肩"]', '宽肩衣架保持皮衣肩部形状。', 'easy', '收纳整理', '["收纳整理","衣柜"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(3, 1, 'single_choice', '绿萝叶子发黄，最常见的原因是什么？A. 光照过强或浇水不当 B. 缺铁 C. 温度太低 D. 虫害', '["A"]', '绿萝黄叶多与光照和浇水管理有关。', 'easy', '绿植养护', '["绿植养护","绿萝"]', NOW(), NOW()),
(3, 2, 'single_choice', '多肉植物夏季养护，以下哪项最重要？A. 多浇水 B. 遮阴通风、控水 C. 暴晒 D. 大量施肥', '["B"]', '夏季多肉休眠，需遮阴控水通风。', 'medium', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 3, 'single_choice', '室内植物浇水原则“见干见湿”是指？A. 一直保持湿润 B. 盆土干透再浇透 C. 只喷水不浇土 D. 每天少量浇水', '["B"]', '见干见湿指盆土干透后浇透水。', 'easy', '绿植养护', '["绿植养护","浇水技巧"]', NOW(), NOW()),
(3, 4, 'single_choice', '以下哪种植物适合放在卫生间，耐阴耐湿？A. 仙人掌 B. 常春藤或蕨类 C. 芦荟 D. 长寿花', '["B"]', '常春藤和蕨类喜阴湿环境。', 'easy', '绿植养护', '["绿植养护","耐阴植物"]', NOW(), NOW()),
(3, 5, 'single_choice', '植物叶片边缘焦枯，最可能的原因是？A. 空气干燥或施肥过量 B. 光照不足 C. 浇水太多 D. 温度过低', '["A"]', '空气干燥和肥害都会导致叶缘焦枯。', 'medium', '绿植养护', '["绿植养护","病害诊断"]', NOW(), NOW()),
(3, 6, 'single_choice', '君子兰不开花，常见原因是什么？A. 光照不足或温差不够 B. 浇水太多 C. 盆太小 D. 土壤偏碱', '["A"]', '君子兰开花需要充足光照和昼夜温差。', 'medium', '绿植养护', '["绿植养护","君子兰"]', NOW(), NOW()),
(3, 7, 'single_choice', '给植物换盆的最佳季节是？A. 夏季 B. 春秋季 C. 冬季 D. 任何时候', '["B"]', '春秋季是植物生长旺盛期，换盆易服盆。', 'easy', '绿植养护', '["绿植养护","换盆技巧"]', NOW(), NOW()),
(3, 8, 'single_choice', '发财树树干发软腐烂，主要原因是？A. 施肥过多 B. 浇水过多导致烂根 C. 光照太强 D. 虫害', '["B"]', '浇水过多导致根部缺氧腐烂。', 'easy', '绿植养护', '["绿植养护","发财树"]', NOW(), NOW()),
(3, 9, 'single_choice', '虎皮兰适合放在什么光照条件下？A. 强光直射 B. 半阴到明亮散射光 C. 完全黑暗 D. 长期暴晒', '["B"]', '虎皮兰耐阴，明亮散射光最适宜。', 'easy', '绿植养护', '["绿植养护","虎皮兰"]', NOW(), NOW()),
(3, 10, 'single_choice', '月季花常见病虫害“白粉病”的症状是？A. 叶片有白色粉末状物 B. 叶片有黑斑 C. 叶片卷曲 D. 根部腐烂', '["A"]', '白粉病表现为叶片白色粉状霉层。', 'easy', '绿植养护', '["绿植养护","月季"]', NOW(), NOW()),
(3, 11, 'single_choice', '水培植物烂根时，应如何处理？A. 加更多水 B. 剪掉烂根，换清水并消毒 C. 加营养液 D. 晒太阳', '["B"]', '剪除烂根并消毒可防止扩散。', 'easy', '绿植养护', '["绿植养护","水培"]', NOW(), NOW()),
(3, 12, 'single_choice', '以下哪种植物是著名的空气净化能手，能吸收甲醛？A. 仙人球 B. 吊兰或绿萝 C. 蝴蝶兰 D. 文竹', '["B"]', '吊兰和绿萝是公认的空气净化植物。', 'easy', '绿植养护', '["绿植养护","空气净化"]', NOW(), NOW()),
(3, 13, 'single_choice', '多肉植物叶片化水（透明变软），通常是因为？A. 缺水 B. 浇水过多或闷热不通风 C. 光照太强 D. 冻伤', '["B"]', '水多闷热导致细胞破裂化水。', 'medium', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 14, 'single_choice', '植物施肥应遵循什么原则？A. 浓肥勤施 B. 薄肥勤施 C. 不施肥 D. 厚肥一次', '["B"]', '薄肥勤施避免烧根，利于吸收。', 'easy', '绿植养护', '["绿植养护","施肥技巧"]', NOW(), NOW()),
(3, 15, 'single_choice', '以下哪种植物有毒，不适合有儿童或宠物的家庭？A. 薄荷 B. 滴水观音（海芋） C. 罗勒 D. 迷迭香', '["B"]', '滴水观音汁液有毒，误食会中毒。', 'easy', '绿植养护', '["绿植养护","有毒植物"]', NOW(), NOW()),
(3, 16, 'single_choice', '长寿花花期过后，应如何处理？A. 剪掉残花和部分枝条 B. 大量浇水 C. 换大盆 D. 放到暗处', '["A"]', '修剪残花可促进复壮和下次开花。', 'easy', '绿植养护', '["绿植养护","长寿花"]', NOW(), NOW()),
(3, 17, 'single_choice', '植物叶片发软下垂，但土壤湿润，可能是什么问题？A. 缺水 B. 烂根或闷根 C. 缺肥 D. 光照过强', '["B"]', '土湿但叶软说明根系已受损。', 'medium', '绿植养护', '["绿植养护","病害诊断"]', NOW(), NOW()),
(3, 18, 'single_choice', '给植物叶片喷水的主要作用是？A. 施肥 B. 增加空气湿度、清洁叶片 C. 杀虫 D. 降温', '["B"]', '喷水可增湿除尘，利于光合作用。', 'easy', '绿植养护', '["绿植养护","日常护理"]', NOW(), NOW()),
(3, 19, 'single_choice', '以下哪种植物耐旱，适合经常忘记浇水的上班族？A. 铜钱草 B. 仙人掌或芦荟 C. 铁线蕨 D. 薄荷', '["B"]', '仙人掌和芦荟耐旱，浇水过多反而易烂。', 'easy', '绿植养护', '["绿植养护","耐旱植物"]', NOW(), NOW()),
(3, 20, 'single_choice', '植物出现蚜虫，家庭简易处理方法有？A. 用洗洁精水喷洒 B. 用浓盐水 C. 用食用油 D. 用醋精', '["A"]', '洗洁精水可溶解蚜虫体表蜡质层。', 'easy', '绿植养护', '["绿植养护","病虫害防治"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(3, 21, 'single_choice', '绿萝长期不生长，节间距拉长，原因是？A. 光线太暗徒长 B. 施肥太多 C. 浇水太少 D. 温度太低', '["A"]', '光照不足会导致徒长，节间距变长。', 'easy', '绿植养护', '["绿植养护","绿萝"]', NOW(), NOW()),
(3, 22, 'single_choice', '以下哪种土壤介质最有利于多肉植物排水透气？A. 纯园土 B. 泥炭土加珍珠岩 C. 黏土 D. 沙子', '["B"]', '泥炭土加珍珠岩疏松透气，利于多肉根系。', 'medium', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 23, 'single_choice', '琴叶榕养护中，叶片出现锈斑，可能原因？A. 光照不足 B. 浇水过多或叶面长期积水 C. 缺氮 D. 温度过低', '["B"]', '叶面积水加上湿度大易导致锈斑病。', 'medium', '绿植养护', '["绿植养护","琴叶榕"]', NOW(), NOW()),
(3, 24, 'single_choice', '冬季室内植物应如何浇水？A. 和夏天一样多 B. 减少浇水频率，水温接近室温 C. 浇冰水 D. 断水', '["B"]', '冬季植物休眠，需减少浇水，避免冷水刺激。', 'easy', '绿植养护', '["绿植养护","浇水技巧"]', NOW(), NOW()),
(3, 25, 'single_choice', '修剪植物枯黄叶子的作用是？A. 美观 B. 减少养分消耗，防止病害 C. 促进开花 D. 增加湿度', '["B"]', '修剪枯叶可减少养分消耗和病害传播。', 'easy', '绿植养护', '["绿植养护","修剪技巧"]', NOW(), NOW()),
(3, 26, 'single_choice', '以下哪种植物开花需要短日照处理（如遮光）？A. 月季 B. 菊花或蟹爪兰 C. 栀子花 D. 茉莉', '["B"]', '菊花和蟹爪兰是短日照植物，需遮光促花。', 'medium', '绿植养护', '["绿植养护","开花植物"]', NOW(), NOW()),
(3, 27, 'single_choice', '富贵竹水培时，茎秆发黄，应如何处理？A. 加铁钉 B. 剪掉黄茎，换水并去掉底部叶片 C. 加白糖 D. 暴晒', '["B"]', '剪除黄化部分，换水可防止扩散。', 'easy', '绿植养护', '["绿植养护","富贵竹"]', NOW(), NOW()),
(3, 28, 'single_choice', '植物红蜘蛛危害的症状是？A. 叶片背面有细丝网和小红点 B. 叶片有白色粉末 C. 叶片有黑色霉斑 D. 根部长瘤', '["A"]', '红蜘蛛在叶背结网，叶片出现细小黄点。', 'medium', '绿植养护', '["绿植养护","病虫害防治"]', NOW(), NOW()),
(3, 29, 'single_choice', '龟背竹叶子边缘开裂是正常现象吗？A. 病害 B. 正常成熟叶片特征 C. 缺水 D. 肥害', '["B"]', '龟背竹成熟叶片自然开裂，是其特征。', 'easy', '绿植养护', '["绿植养护","龟背竹"]', NOW(), NOW()),
(3, 30, 'single_choice', '使用陶粒铺在盆土表面的作用是？A. 施肥 B. 保湿防溅土，防止虫害产卵 C. 增加营养 D. 调节酸碱度', '["B"]', '陶粒铺面可保湿、防溅土、阻隔虫害。', 'easy', '绿植养护', '["绿植养护","盆面装饰"]', NOW(), NOW()),
(3, 31, 'single_choice', '植物扦插繁殖时，基质最好选用？A. 园土 B. 蛭石或珍珠岩（无菌保湿） C. 黏土 D. 粗砂加水泥', '["B"]', '蛭石和珍珠岩无菌透气，利于生根。', 'medium', '绿植养护', '["绿植养护","扦插繁殖"]', NOW(), NOW()),
(3, 32, 'single_choice', '以下哪种植物喜酸性土壤，叶片容易黄化缺铁？A. 仙人掌 B. 栀子花或杜鹃 C. 虎皮兰 D. 芦荟', '["B"]', '栀子花和杜鹃喜酸，缺铁易黄叶。', 'easy', '绿植养护', '["绿植养护","喜酸植物"]', NOW(), NOW()),
(3, 33, 'single_choice', '植物花盆底部必须有孔的主要原因是？A. 透气排水，防止烂根 B. 美观 C. 方便移动 D. 节省土', '["A"]', '底孔可排水透气，避免积水烂根。', 'easy', '绿植养护', '["绿植养护","花盆选择"]', NOW(), NOW()),
(3, 34, 'single_choice', '夏季中午给植物浇水，可能导致？A. 植物更精神 B. 叶片灼伤或根系温度骤变 C. 促进生长 D. 防止虫害', '["B"]', '中午高温浇水易造成叶片灼伤和根系应激。', 'easy', '绿植养护', '["绿植养护","浇水技巧"]', NOW(), NOW()),
(3, 35, 'single_choice', '以下哪种植物适合放在卧室，夜间释放氧气？A. 绿萝 B. 虎皮兰或长寿花 C. 百合 D. 玫瑰', '["B"]', '虎皮兰等景天酸代谢植物夜间释放氧气。', 'medium', '绿植养护', '["绿植养护","卧室植物"]', NOW(), NOW()),
(3, 36, 'single_choice', '兰花养护中，“根要透气”意味着应使用？A. 普通营养土 B. 树皮、水苔等粗植料 C. 黏土 D. 沙子', '["B"]', '兰花气生根需要疏松透气的粗植料。', 'medium', '绿植养护', '["绿植养护","兰花"]', NOW(), NOW()),
(3, 37, 'single_choice', '植物叶片向上卷曲，常见原因是？A. 缺水或空气干燥 B. 水多 C. 肥多 D. 光照弱', '["A"]', '缺水时叶片卷曲减少水分蒸发。', 'easy', '绿植养护', '["绿植养护","病害诊断"]', NOW(), NOW()),
(3, 38, 'single_choice', '幸福树（菜豆树）落叶严重，可能原因是？A. 室内通风不良或浇水不当 B. 光照太强 C. 缺肥 D. 正常现象', '["A"]', '幸福树对通风和水分敏感，不良环境易落叶。', 'medium', '绿植养护', '["绿植养护","幸福树"]', NOW(), NOW()),
(3, 39, 'single_choice', '多肉植物上盆前，根系需要？A. 泡水一天 B. 修剪干枯根并晾干伤口 C. 用酒精消毒 D. 不处理', '["B"]', '修剪干枯根并晾干可防上盆后腐烂。', 'easy', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 40, 'single_choice', '以下哪种病虫害表现为叶片有黏黏的蜜露？A. 红蜘蛛 B. 蚧壳虫或蚜虫 C. 白粉病 D. 黑斑病', '["B"]', '蚧壳虫和蚜虫分泌蜜露，招引蚂蚁。', 'easy', '绿植养护', '["绿植养护","病虫害防治"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(3, 41, 'single_choice', '铜钱草叶子越长越小，原因可能是？A. 光照不足或未及时分盆 B. 浇水太多 C. 温度高 D. 虫害', '["A"]', '光照不足会徒长，根满盆需分盆。', 'easy', '绿植养护', '["绿植养护","铜钱草"]', NOW(), NOW()),
(3, 42, 'single_choice', '给植物施复合肥时，应避免？A. 撒在盆边 B. 直接接触根系或茎基部 C. 溶解后浇灌 D. 少量多次', '["B"]', '肥料直接接触根系会烧根。', 'easy', '绿植养护', '["绿植养护","施肥技巧"]', NOW(), NOW()),
(3, 43, 'single_choice', '文竹叶子发黄，常见原因有哪些？A. 烟尘污染或光照过强 B. 浇水太多 C. 温度低 D. 缺铁', '["A"]', '文竹怕烟尘和强光，空气质量差易黄叶。', 'easy', '绿植养护', '["绿植养护","文竹"]', NOW(), NOW()),
(3, 44, 'single_choice', '以下哪种植物在冬季会进入休眠，应断水断肥？A. 常春藤 B. 仙人掌类 C. 绿萝 D. 吊兰', '["B"]', '仙人掌类冬季休眠，需停水停肥。', 'easy', '绿植养护', '["绿植养护","休眠植物"]', NOW(), NOW()),
(3, 45, 'single_choice', '植物叶片出现黑色霉斑，通常是什么病害？A. 炭疽病或煤污病 B. 白粉病 C. 锈病 D. 霜霉病', '["A"]', '炭疽病和煤污病表现为黑色霉斑。', 'medium', '绿植养护', '["绿植养护","病害诊断"]', NOW(), NOW()),
(3, 46, 'single_choice', '换盆时，在盆底垫碎瓦片或陶粒的作用是？A. 排水层，防止积水烂根 B. 增加营养 C. 固定根系 D. 美观', '["A"]', '盆底垫排水层可防止积水。', 'easy', '绿植养护', '["绿植养护","换盆技巧"]', NOW(), NOW()),
(3, 47, 'single_choice', '以下哪种植物对光照要求最高，需要全日照？A. 蕨类 B. 月季或向日葵 C. 绿萝 D. 富贵竹', '["B"]', '月季和向日葵喜全日照环境。', 'easy', '绿植养护', '["绿植养护","喜光植物"]', NOW(), NOW()),
(3, 48, 'single_choice', '水培绿萝长出水生根后，应如何换水？A. 每天换 B. 每周换一次，保留部分原水 C. 不换只加 D. 用开水冷却后换', '["B"]', '保留部分原水可维持微生物平衡。', 'easy', '绿植养护', '["绿植养护","水培"]', NOW(), NOW()),
(3, 49, 'single_choice', '多肉植物徒长（茎拉长、叶片稀疏）的原因是？A. 浇水多且光照不足 B. 施肥多 C. 温度高 D. 盆太小', '["A"]', '水多光少是多肉徒长的主因。', 'easy', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 50, 'single_choice', '植物叶片夜间水滴现象（吐水）是正常吗？A. 病害 B. 正常生理现象，说明根系活跃 C. 浇水太多 D. 施肥过量', '["B"]', '吐水是植物根系活跃的正常现象。', 'easy', '绿植养护', '["绿植养护","植物生理"]', NOW(), NOW()),
(3, 51, 'single_choice', '以下哪种肥料主要用于促进开花结果？A. 氮肥 B. 磷钾肥 C. 铁肥 D. 钙肥', '["B"]', '磷钾肥促进花芽分化和果实发育。', 'easy', '绿植养护', '["绿植养护","施肥技巧"]', NOW(), NOW()),
(3, 52, 'single_choice', '琴叶榕适合摆放在什么位置？A. 阴暗角落 B. 明亮散射光，远离空调出风口 C. 阳光直射阳台 D. 卫生间', '["B"]', '琴叶榕喜明亮散射光，怕空调直吹。', 'medium', '绿植养护', '["绿植养护","琴叶榕"]', NOW(), NOW()),
(3, 53, 'single_choice', '盆栽土壤板结，应如何改善？A. 浇肥皂水 B. 松土或掺入珍珠岩、粗砂 C. 压实 D. 换盆不换土', '["B"]', '掺入粗颗粒可增加土壤孔隙度。', 'easy', '绿植养护', '["绿植养护","土壤改良"]', NOW(), NOW()),
(3, 54, 'single_choice', '以下哪种植物属于多肉植物？A. 绿萝 B. 玉露或熊童子 C. 龟背竹 D. 薄荷', '["B"]', '玉露和熊童子是景天科多肉植物。', 'easy', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 55, 'single_choice', '植物烂根的典型气味是？A. 清香 B. 酸臭味 C. 无味 D. 甜味', '["B"]', '烂根会产生厌氧发酵的酸臭味。', 'easy', '绿植养护', '["绿植养护","病害诊断"]', NOW(), NOW()),
(3, 56, 'single_choice', '室内植物生长期施肥频率一般为？A. 每天 B. 每1-2周一次 C. 每月一次 D. 一年一次', '["B"]', '生长期每1-2周施一次薄肥。', 'easy', '绿植养护', '["绿植养护","施肥技巧"]', NOW(), NOW()),
(3, 57, 'single_choice', '以下哪种植物的汁液可能引起皮肤过敏？A. 吊兰 B. 滴水观音 C. 虎皮兰 D. 文竹', '["B"]', '滴水观音汁液含草酸钙针晶，致过敏。', 'easy', '绿植养护', '["绿植养护","有毒植物"]', NOW(), NOW()),
(3, 58, 'single_choice', '盆栽边缘出现白色结晶物，可能是什么？A. 霉菌 B. 水垢或肥料盐分积累 C. 虫卵 D. 正常', '["B"]', '白色结晶是水垢或肥料盐分沉积。', 'easy', '绿植养护', '["绿植养护","土壤问题"]', NOW(), NOW()),
(3, 59, 'single_choice', '薄荷徒长、香味变淡，应如何处理？A. 增加光照并打顶修剪 B. 多浇水 C. 施肥 D. 换大盆', '["A"]', '打顶可促分枝，增加光照可提升香味。', 'easy', '绿植养护', '["绿植养护","薄荷"]', NOW(), NOW()),
(3, 60, 'single_choice', '植物叶片小且颜色发紫，可能缺乏什么？A. 氮 B. 磷 C. 钾 D. 铁', '["B"]', '缺磷会导致叶片变小、呈紫色或红色。', 'medium', '绿植养护', '["绿植养护","缺素症"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(3, 61, 'single_choice', '夏季高温时，哪些植物会进入半休眠？A. 月季 B. 仙客来、多肉（部分） C. 绿萝 D. 吊兰', '["B"]', '仙客来和部分多肉夏季休眠。', 'medium', '绿植养护', '["绿植养护","休眠植物"]', NOW(), NOW()),
(3, 62, 'single_choice', '自制有机肥（如淘米水）必须？A. 直接浇 B. 发酵稀释后使用 C. 煮开浇 D. 加盐', '["B"]', '淘米水需发酵腐熟后稀释使用，防烧根。', 'easy', '绿植养护', '["绿植养护","自制肥料"]', NOW(), NOW()),
(3, 63, 'single_choice', '以下哪种植物耐阴，适合办公室无窗环境？A. 仙人球 B. 短叶虎尾兰或绿萝 C. 茉莉 D. 栀子', '["B"]', '虎尾兰和绿萝极耐阴，适合室内。', 'easy', '绿植养护', '["绿植养护","耐阴植物"]', NOW(), NOW()),
(3, 64, 'single_choice', '植物蚧壳虫常用防治药剂是？A. 多菌灵 B. 吡虫啉或酒精擦拭 C. 百菌清 D. 代森锰锌', '["B"]', '吡虫啉是蚧壳虫特效药，酒精可物理清除。', 'easy', '绿植养护', '["绿植养护","病虫害防治"]', NOW(), NOW()),
(3, 65, 'single_choice', '平安树（兰屿肉桂）叶片下垂，应首先检查？A. 湿度 B. 盆土干湿和根系 C. 光照 D. 施肥', '["B"]', '叶垂应先检查土壤干湿和根系健康。', 'easy', '绿植养护', '["绿植养护","平安树"]', NOW(), NOW()),
(3, 66, 'single_choice', '使用自来水浇花前，最好？A. 直接浇 B. 晾晒1-2天去氯 C. 加热 D. 加盐', '["B"]', '晾晒可挥发余氯，避免伤害植物。', 'easy', '绿植养护', '["绿植养护","浇水技巧"]', NOW(), NOW()),
(3, 67, 'single_choice', '以下哪种植物在花期不宜向花朵喷水？A. 绿萝 B. 蝴蝶兰或百合 C. 吊兰 D. 铜钱草', '["B"]', '向花朵喷水易导致花瓣腐烂和缩短花期。', 'easy', '绿植养护', '["绿植养护","开花植物"]', NOW(), NOW()),
(3, 68, 'single_choice', '植物新叶比老叶黄，可能缺什么？A. 氮 B. 铁或镁 C. 钾 D. 磷', '["B"]', '新叶黄化多为缺铁或镁，影响叶绿素合成。', 'medium', '绿植养护', '["绿植养护","缺素症"]', NOW(), NOW()),
(3, 69, 'single_choice', '小苗上盆后应如何浇水？A. 浇透定根水 B. 不浇水 C. 浇半杯 D. 喷雾', '["A"]', '浇透定根水可使土壤与根系紧密结合。', 'easy', '绿植养护', '["绿植养护","上盆技巧"]', NOW(), NOW()),
(3, 70, 'single_choice', '以下哪种植物适合水培？A. 仙人掌 B. 白掌或富贵竹 C. 月季 D. 多肉', '["B"]', '白掌和富贵竹极易水培生根。', 'easy', '绿植养护', '["绿植养护","水培"]', NOW(), NOW()),
(3, 71, 'single_choice', '植物叶片边缘发黄干枯，且老叶先黄，可能缺？A. 氮 B. 钾 C. 钙 D. 铁', '["B"]', '老叶边缘黄化干枯是典型缺钾症状。', 'medium', '绿植养护', '["绿植养护","缺素症"]', NOW(), NOW()),
(3, 72, 'single_choice', '给大型绿植清洁叶片，可以用？A. 食用油 B. 稀释啤酒或清水擦拭 C. 洗洁精 D. 酒精', '["B"]', '啤酒含营养物质，擦拭后叶片光亮。', 'easy', '绿植养护', '["绿植养护","叶片清洁"]', NOW(), NOW()),
(3, 73, 'single_choice', '多肉植物叶插繁殖时，叶片应？A. 插入土中 B. 平放于土面，保持湿度 C. 泡水 D. 暴晒', '["B"]', '叶插叶片平放土面，保持湿度等待发芽。', 'easy', '绿植养护', '["绿植养护","多肉繁殖"]', NOW(), NOW()),
(3, 74, 'single_choice', '植物长期不换盆，会导致？A. 根系盘结，生长不良 B. 开花更多 C. 抗病增强 D. 叶片变大', '["A"]', '根满盆后会盘结，导致生长不良。', 'easy', '绿植养护', '["绿植养护","换盆技巧"]', NOW(), NOW()),
(3, 75, 'single_choice', '以下哪种土壤酸碱度适合大多数室内植物？A. 强碱性 B. 中性至微酸性（pH 6-7） C. 强酸性 D. 任意', '["B"]', '大多数室内植物喜中性至微酸性土壤。', 'easy', '绿植养护', '["绿植养护","土壤酸碱度"]', NOW(), NOW()),
(3, 76, 'single_choice', '蕨类植物喜欢什么环境？A. 干燥暴晒 B. 高湿度、半阴 C. 低温 D. 强风', '["B"]', '蕨类喜阴湿环境，需保持高湿度。', 'easy', '绿植养护', '["绿植养护","蕨类植物"]', NOW(), NOW()),
(3, 77, 'single_choice', '植物修剪后伤口应如何处理？A. 涂抹多菌灵或自然风干 B. 浇水 C. 涂食用油 D. 用土覆盖', '["A"]', '涂抹杀菌剂可防伤口感染。', 'easy', '绿植养护', '["绿植养护","修剪技巧"]', NOW(), NOW()),
(3, 78, 'single_choice', '以下哪种植物开花时花香浓郁，但不适合放在卧室？A. 长寿花 B. 百合或夜来香 C. 蟹爪兰 D. 君子兰', '["B"]', '百合和夜来香花香过浓，影响睡眠。', 'easy', '绿植养护', '["绿植养护","卧室植物"]', NOW(), NOW()),
(3, 79, 'single_choice', '盆底积水盘长期积水会导致？A. 增加湿度 B. 烂根 C. 叶片更绿 D. 防虫', '["B"]', '积水盘长期积水会导致盆土过湿烂根。', 'easy', '绿植养护', '["绿植养护","浇水技巧"]', NOW(), NOW()),
(3, 80, 'single_choice', '仙人球长时间不浇水，球体萎缩，应？A. 大量浇透 B. 逐步增加浇水，恢复饱满 C. 换盆 D. 施肥', '["B"]', '逐步恢复浇水，可避免突然大量浇水烂根。', 'medium', '绿植养护', '["绿植养护","仙人掌"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(3, 81, 'single_choice', '春羽（羽裂蔓绿绒）叶片开裂是？A. 病害 B. 成熟自然开裂 C. 缺光 D. 水多', '["B"]', '春羽成熟叶片自然开裂是其品种特征。', 'easy', '绿植养护', '["绿植养护","春羽"]', NOW(), NOW()),
(3, 82, 'single_choice', '柠檬树盆栽叶片发黄掉落，常见原因？A. 酸性不足或浇水不当 B. 光照不足 C. 温度高 D. 正常落叶', '["A"]', '柠檬喜酸，土壤偏碱或水多易黄叶。', 'medium', '绿植养护', '["绿植养护","柠檬树"]', NOW(), NOW()),
(3, 83, 'single_choice', '以下哪种方法不能增加空气湿度？A. 喷雾 B. 开空调除湿 C. 使用加湿器 D. 植物旁放水盘', '["B"]', '空调除湿会降低空气湿度，适得其反。', 'easy', '绿植养护', '["绿植养护","湿度管理"]', NOW(), NOW()),
(3, 84, 'single_choice', '植物出现根结线虫，根部有瘤状物，应？A. 灌药或丢弃带病土 B. 多浇水 C. 晒太阳 D. 施肥', '["A"]', '根结线虫需用药剂处理，严重时弃土。', 'hard', '绿植养护', '["绿植养护","病虫害防治"]', NOW(), NOW()),
(3, 85, 'single_choice', '三角梅不开花，控水催花的做法是？A. 多浇水 B. 等叶片微蔫再浇水，反复几次 C. 断水一个月 D. 浇冰水', '["B"]', '控水至叶片微蔫再浇水，可促进花芽分化。', 'medium', '绿植养护', '["绿植养护","三角梅"]', NOW(), NOW()),
(3, 86, 'single_choice', '新买的盆栽带回家后，应？A. 立即换盆 B. 先原盆适应环境一周再换 C. 放在阳光暴晒 D. 多施肥', '["B"]', '先适应环境再换盆可减少缓苗期。', 'easy', '绿植养护', '["绿植养护","新植物养护"]', NOW(), NOW()),
(3, 87, 'single_choice', '以下哪种植物对氟化物敏感，不宜用自来水直接浇？A. 绿萝 B. 龙血树或富贵竹 C. 吊兰 D. 虎皮兰', '["B"]', '龙血树和富贵竹对氟化物敏感，宜用晾晒水。', 'medium', '绿植养护', '["绿植养护","浇水技巧"]', NOW(), NOW()),
(3, 88, 'single_choice', '冬季室内加温干燥，对植物最不利的影响是？A. 冻伤 B. 红蜘蛛易爆发，叶片焦尖 C. 烂根 D. 休眠', '["B"]', '干燥环境红蜘蛛易爆发，叶片也易焦尖。', 'medium', '绿植养护', '["绿植养护","冬季养护"]', NOW(), NOW()),
(3, 89, 'single_choice', '植物叶片上有透明粘液，可能是什么？A. 花蜜 B. 蚜虫分泌物 C. 露水 D. 施肥残留', '["B"]', '蚜虫分泌蜜露，呈透明粘稠状。', 'easy', '绿植养护', '["绿植养护","病虫害防治"]', NOW(), NOW()),
(3, 90, 'single_choice', '自制杀虫剂大蒜水的配制浓度约为？A. 1:10 浸泡过滤 B. 1:100 C. 1:500 D. 纯蒜汁', '["A"]', '大蒜水浓度约1:10，过滤后喷洒。', 'easy', '绿植养护', '["绿植养护","自制杀虫剂"]', NOW(), NOW()),
(3, 91, 'single_choice', '以下哪种植物开花后花序会枯死，需要剪掉花梗？A. 月季 B. 蝴蝶兰（避免消耗） C. 茉莉 D. 栀子', '["B"]', '蝴蝶兰花后剪花梗可减少养分消耗。', 'medium', '绿植养护', '["绿植养护","蝴蝶兰"]', NOW(), NOW()),
(3, 92, 'single_choice', '植物叶片变薄、颜色变浅，可能是？A. 光照不足 B. 光照过强 C. 温度过低 D. 水多', '["A"]', '光照不足导致叶片变薄，叶绿素减少。', 'easy', '绿植养护', '["绿植养护","光照管理"]', NOW(), NOW()),
(3, 93, 'single_choice', '多肉植物夏季浇水的最佳时间是？A. 中午 B. 凉爽的傍晚 C. 凌晨 D. 任何时间', '["B"]', '傍晚浇水可避免高温高湿导致腐烂。', 'easy', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 94, 'single_choice', '月季黑斑病的典型特征是？A. 叶片黑色霉层 B. 叶片圆形黑斑，边缘黄色 C. 白色粉末 D. 锈色孢子', '["B"]', '黑斑病表现为圆形黑斑，边缘呈放射状。', 'easy', '绿植养护', '["绿植养护","月季"]', NOW(), NOW()),
(3, 95, 'single_choice', '水培植物营养液浓度应？A. 越高越好 B. 按说明书稀释，宁稀勿浓 C. 用纯水不加 D. 加糖', '["B"]', '营养液过浓会烧根，宁稀勿浓。', 'easy', '绿植养护', '["绿植养护","水培"]', NOW(), NOW()),
(3, 96, 'single_choice', '金枝玉叶（马齿苋树）修剪造型最好在？A. 冬季 B. 生长旺季春秋季 C. 夏季 D. 任何时候', '["B"]', '春秋季生长快，修剪后易恢复。', 'easy', '绿植养护', '["绿植养护","金枝玉叶"]', NOW(), NOW()),
(3, 97, 'single_choice', '植物服盆期（换盆后适应期）应？A. 施肥 B. 避免暴晒，正常浇水见干见湿 C. 多浇水 D. 强光刺激', '["B"]', '服盆期需避免暴晒，正常浇水养护。', 'easy', '绿植养护', '["绿植养护","换盆技巧"]', NOW(), NOW()),
(3, 98, 'single_choice', '以下哪种植物在黑暗中也能合成叶绿素？A. 所有植物 B. 没有，叶绿素合成需要光 C. 蕨类 D. 多肉', '["B"]', '叶绿素合成需要光照，无光会黄化。', 'easy', '绿植养护', '["绿植养护","植物生理"]', NOW(), NOW()),
(3, 99, 'single_choice', '植物开花期间施肥应选择？A. 高氮肥 B. 磷钾肥（花多多2号等） C. 不施肥 D. 复合肥', '["B"]', '花期施磷钾肥可延长花期、增加花色。', 'easy', '绿植养护', '["绿植养护","施肥技巧"]', NOW(), NOW()),
(3, 100, 'single_choice', '绿萝气生根的主要作用是？A. 吸收空气中的水分和养分 B. 固定植株 C. 开花 D. 呼吸', '["A"]', '绿萝气生根可吸收空气湿度和养分。', 'easy', '绿植养护', '["绿植养护","绿萝"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(3, 101, 'fill_blank', '绿萝水培时，水位不宜超过根系体积的______。', '["1/2到2/3"]', '水位过高会导致烂根。', 'easy', '绿植养护', '["绿植养护","水培"]', NOW(), NOW()),
(3, 102, 'fill_blank', '多肉植物叶片化水后，应立即______。', '["摘除化水叶片并加强通风"]', '化水叶片会腐烂，需及时摘除。', 'easy', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 103, 'fill_blank', '常见室内植物浇水频率口诀“干透浇透”，适用于______植物。', '["多数耐旱绿植如虎皮兰"]', '耐旱植物适合干透浇透原则。', 'easy', '绿植养护', '["绿植养护","浇水技巧"]', NOW(), NOW()),
(3, 104, 'fill_blank', '月季白粉病在______季节高发。', '["春秋干燥少雨时"]', '春秋干燥少雨时白粉病易高发。', 'medium', '绿植养护', '["绿植养护","月季"]', NOW(), NOW()),
(3, 105, 'fill_blank', '植物新芽卷曲、叶片畸形，可能是______危害。', '["蓟马或蚜虫"]', '蓟马和蚜虫吸食汁液导致新芽畸形。', 'medium', '绿植养护', '["绿植养护","病虫害防治"]', NOW(), NOW()),
(3, 106, 'fill_blank', '栀子花缺铁黄化的典型表现是______。', '["新叶叶肉黄而叶脉绿"]', '缺铁表现为新叶叶脉绿色、叶肉黄色。', 'easy', '绿植养护', '["绿植养护","栀子花"]', NOW(), NOW()),
(3, 107, 'fill_blank', '换盆时，若原土坨根系健康，宜______移栽以减少缓苗。', '["带土球"]', '带土球移栽可保护根系，减少缓苗。', 'easy', '绿植养护', '["绿植养护","换盆技巧"]', NOW(), NOW()),
(3, 108, 'fill_blank', '多肉植物叶插成功的关键是______。', '["保持湿度但不积水"]', '湿度适宜利于生根，积水易烂。', 'easy', '绿植养护', '["绿植养护","多肉繁殖"]', NOW(), NOW()),
(3, 109, 'fill_blank', '植物叶片焦边往往与______有关。', '["空气干燥或盐分积累"]', '空气干燥和盐分积累都会导致焦边。', 'easy', '绿植养护', '["绿植养护","病害诊断"]', NOW(), NOW()),
(3, 110, 'fill_blank', '君子兰花期后应及时______。', '["剪掉花箭"]', '剪花箭可减少养分消耗。', 'easy', '绿植养护', '["绿植养护","君子兰"]', NOW(), NOW()),
(3, 111, 'fill_blank', '龟背竹气生根可引导______。', '["扎入土中或辅助生长"]', '气生根扎入土中可吸收更多养分。', 'easy', '绿植养护', '["绿植养护","龟背竹"]', NOW(), NOW()),
(3, 112, 'fill_blank', '自制杀菌剂可用______稀释喷洒。', '["小苏打水或肉桂粉浸液"]', '小苏打和肉桂都有一定杀菌作用。', 'easy', '绿植养护', '["绿植养护","自制杀菌剂"]', NOW(), NOW()),
(3, 113, 'fill_blank', '植物长期放在空调出风口下会导致______。', '["叶片失水焦枯"]', '空调直吹造成叶片水分快速蒸发。', 'easy', '绿植养护', '["绿植养护","养护环境"]', NOW(), NOW()),
(3, 114, 'fill_blank', '仙客来夏季休眠期应______。', '["断水断肥，置阴凉处"]', '休眠期需停水停肥，保持阴凉。', 'medium', '绿植养护', '["绿植养护","仙客来"]', NOW(), NOW()),
(3, 115, 'fill_blank', '水培植物烂根处理后，可在水中加入______消毒。', '["多菌灵或高锰酸钾（极稀）"]', '极稀的多菌灵或高锰酸钾可消毒。', 'medium', '绿植养护', '["绿植养护","水培"]', NOW(), NOW()),
(3, 116, 'fill_blank', '发财树黄叶且土壤长期湿润，最可能原因是______。', '["烂根"]', '土湿却黄叶说明根系已腐烂。', 'easy', '绿植养护', '["绿植养护","发财树"]', NOW(), NOW()),
(3, 117, 'fill_blank', '虎皮兰不耐______，冬季低于10度会冻伤。', '["低温"]', '虎皮兰喜暖怕冷，冬季需保温。', 'easy', '绿植养护', '["绿植养护","虎皮兰"]', NOW(), NOW()),
(3, 118, 'fill_blank', '植物叶片上的灰尘会影响______。', '["光合作用"]', '灰尘阻挡光照，影响光合作用。', 'easy', '绿植养护', '["绿植养护","叶片清洁"]', NOW(), NOW()),
(3, 119, 'fill_blank', '花盆大小选择原则：新盆比原盆大______厘米直径即可。', '["3-5"]', '过大易积水，3-5cm最适宜。', 'easy', '绿植养护', '["绿植养护","换盆技巧"]', NOW(), NOW()),
(3, 120, 'fill_blank', '常春藤对______敏感，需远离新装修污染源。', '["甲醛（其实能吸收但会受害）"]', '常春藤可吸收甲醛但也会受害。', 'medium', '绿植养护', '["绿植养护","常春藤"]', NOW(), NOW()),
(3, 121, 'fill_blank', '多肉植物铺面石的作用包括美观和______。', '["防虫及底层叶片接触湿土"]', '铺面可防虫、避免叶片接触湿土。', 'easy', '绿植养护', '["绿植养护","多肉植物"]', NOW(), NOW()),
(3, 122, 'fill_blank', '植物扦插后覆盖保鲜膜的目的是______。', '["保湿"]', '覆膜可保持高湿度，利于生根。', 'easy', '绿植养护', '["绿植养护","扦插繁殖"]', NOW(), NOW()),
(3, 123, 'fill_blank', '长寿花属于______日照植物。', '["短"]', '长寿花是短日照植物，需短日照促花。', 'easy', '绿植养护', '["绿植养护","长寿花"]', NOW(), NOW()),
(3, 124, 'fill_blank', '土壤中加入椰糠可提高______。', '["保水性和透气性"]', '椰糠保水透气，改良土壤结构。', 'easy', '绿植养护', '["绿植养护","土壤改良"]', NOW(), NOW()),
(3, 125, 'fill_blank', '绿萝柱（棕柱）养植时，气生根应______。', '["引导缠绕在柱上"]', '气生根缠绕棕柱可吸收水分养分。', 'easy', '绿植养护', '["绿植养护","绿萝"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(4, 1, 'single_choice', '折纸基础形状“双正方形”通常由什么基础形变化而来？A. 双三角形 B. 方形基础折出对角线 C. 风车形 D. 纸鹤基础', '["B"]', '双正方形由方形纸折出对角线后再折叠而成。', 'medium', '手工制作', '["手工制作","折纸"]', NOW(), NOW()),
(4, 2, 'single_choice', '制作不织布玩偶时，最常用的缝合针法是？A. 回针缝 B. 锁边缝或毛边缝 C. 平针缝 D. 藏针缝', '["B"]', '锁边缝可防止不织布边缘起毛且牢固。', 'easy', '手工制作', '["手工制作","不织布"]', NOW(), NOW()),
(4, 3, 'single_choice', '十字绣绣布常用的规格“14CT”指的是什么？A. 每英寸14个格子 B. 每厘米14个格子 C. 绣布厚度 D. 绣线股数', '["A"]', 'CT指每英寸的格子数，14CT即每英寸14格。', 'easy', '手工制作', '["手工制作","十字绣"]', NOW(), NOW()),
(4, 4, 'single_choice', '制作纸质立体贺卡时，使图案弹起的结构通常称为？A. 折叠杆 B. 弹出机制或V形折 C. 滑轨 D. 黏贴块', '["B"]', 'V形折是最常见的立体贺卡弹出结构。', 'medium', '手工制作', '["手工制作","立体贺卡"]', NOW(), NOW()),
(4, 5, 'single_choice', '橡皮章雕刻时，刻掉图案以外部分的刀法叫做？A. 留白 B. 外斜刀 C. 内斜刀 D. 平刀', '["B"]', '外斜刀刻掉外围，保留图案。', 'medium', '手工制作', '["手工制作","橡皮章"]', NOW(), NOW()),
(4, 6, 'single_choice', '羊毛毡湿毡和针毡的主要区别是？A. 用针或用水和肥皂 B. 羊毛种类不同 C. 颜色不同 D. 大小不同', '["A"]', '针毡用戳针，湿毡用水和肥皂。', 'easy', '手工制作', '["手工制作","羊毛毡"]', NOW(), NOW()),
(4, 7, 'single_choice', '制作马赛克杯垫时，瓷砖缝隙填充的材料是？A. 白乳胶 B. 填缝剂 C. 水晶滴胶 D. 热熔胶', '["B"]', '填缝剂专门用于填充瓷砖缝隙。', 'easy', '手工制作', '["手工制作","马赛克"]', NOW(), NOW()),
(4, 8, 'single_choice', '纸藤编织前，通常需要将纸藤？A. 泡水变软 B. 搓成绳状或喷湿 C. 剪成小段 D. 染色', '["B"]', '喷湿后纸藤柔软易编织。', 'easy', '手工制作', '["手工制作","纸藤编织"]', NOW(), NOW()),
(4, 9, 'single_choice', '中国结中“盘长结”象征什么？A. 长寿连绵 B. 爱情 C. 财富 D. 平安', '["A"]', '盘长结寓意连绵不断、长寿吉祥。', 'easy', '手工制作', '["手工制作","中国结"]', NOW(), NOW()),
(4, 10, 'single_choice', '自制手工皂时，碱液（氢氧化钠）应倒入什么容器？A. 铝锅 B. 耐碱塑料杯或不锈钢 C. 玻璃杯 D. 陶瓷碗', '["B"]', '碱液腐蚀性强，须用耐碱容器。', 'hard', '手工制作', '["手工制作","手工皂"]', NOW(), NOW()),
(4, 11, 'single_choice', '串珠制作立体玩偶时，通常使用什么线材？A. 棉线 B. 尼龙线或鱼线 C. 毛线 D. 铁丝', '["B"]', '尼龙线或鱼线强度高、有弹性。', 'easy', '手工制作', '["手工制作","串珠"]', NOW(), NOW()),
(4, 12, 'single_choice', '衍纸（纸艺卷）的基础形状中，将圆形一端捏尖形成？A. 泪滴卷 B. 眼形卷 C. 心形卷 D. 月牙卷', '["A"]', '圆形一端捏尖呈水滴状，称为泪滴卷。', 'easy', '手工制作', '["手工制作","衍纸"]', NOW(), NOW()),
(4, 13, 'single_choice', '缝纫机缝制薄布料时，应选用几号机针？A. 14号 B. 9号或11号 C. 18号 D. 22号', '["B"]', '薄布料用细针号，9-11号合适。', 'easy', '手工制作', '["手工制作","缝纫"]', NOW(), NOW()),
(4, 14, 'single_choice', '热缩片制作钥匙扣，最后一步是？A. 上色 B. 加热收缩 C. 打孔 D. 剪形状', '["B"]', '加热收缩是热缩片制作的最后关键步骤。', 'easy', '手工制作', '["手工制作","热缩片"]', NOW(), NOW()),
(4, 15, 'single_choice', '拼布中的“贴布缝”主要用于？A. 拼接两块布 B. 将一块布缝在另一块布表面 C. 包边 D. 压线', '["B"]', '贴布缝是将小块布缝在大块布表面。', 'medium', '手工制作', '["手工制作","拼布"]', NOW(), NOW()),
(4, 16, 'single_choice', '滴胶（环氧树脂）固化时，AB胶配比不准确会导致？A. 不固化或发粘 B. 更透明 C. 更快干 D. 更硬', '["A"]', '配比不准会导致固化不完全或不固化。', 'medium', '手工制作', '["手工制作","滴胶"]', NOW(), NOW()),
(4, 17, 'single_choice', '制作丝网花时，将尼龙丝网套在花瓣铁丝圈上，需用？A. 热熔胶 B. QQ线（弹性线）缠绕固定 C. 白乳胶 D. 双面胶', '["B"]', 'QQ线可紧密缠绕且不滑脱。', 'medium', '手工制作', '["手工制作","丝网花"]', NOW(), NOW()),
(4, 18, 'single_choice', '钩针编织中，“锁针”（辫子针）通常作为？A. 起针基础 B. 收针 C. 加针 D. 减针', '["A"]', '锁针是最基础的起针方法。', 'easy', '手工制作', '["手工制作","钩针"]', NOW(), NOW()),
(4, 19, 'single_choice', '纸模型制作时，切割厚纸板应使用？A. 普通剪刀 B. 美工刀加切割垫 C. 指甲剪 D. 菜刀', '["B"]', '美工刀配合切割垫可精确切割。', 'easy', '手工制作', '["手工制作","纸模型"]', NOW(), NOW()),
(4, 20, 'single_choice', '黏土制作中，为防止干燥开裂，应？A. 暴晒 B. 覆盖保湿或缓慢阴干 C. 放入烤箱 D. 冷冻', '["B"]', '缓慢阴干可防止水分蒸发过快开裂。', 'easy', '手工制作', '["手工制作","黏土"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(4, 21, 'single_choice', '缝纽扣时，纽扣与布料之间留出线梗（约1-2mm）的作用是？A. 方便扣合 B. 美观 C. 节省线 D. 易拆', '["A"]', '留线梗使纽扣有活动空间，方便扣合。', 'easy', '手工制作', '["手工制作","缝纫"]', NOW(), NOW()),
(4, 22, 'single_choice', '不织布材料的特点是不需要？A. 裁剪 B. 锁边处理（不脱线） C. 缝合 D. 配色', '["B"]', '不织布边缘不脱线，无需锁边。', 'easy', '手工制作', '["手工制作","不织布"]', NOW(), NOW()),
(4, 23, 'single_choice', '折纸千纸鹤的基础形是？A. 双正方形 B. 双三角形 C. 方形折 D. 鸟形基础', '["B"]', '千纸鹤由双三角形基础演变而来。', 'easy', '手工制作', '["手工制作","折纸"]', NOW(), NOW()),
(4, 24, 'single_choice', '制作蜡烛时，添加香精的最佳温度是？A. 沸腾时 B. 蜡液70-80度左右 C. 凝固后 D. 任意', '["B"]', '70-80度添加香精可均匀融合且不挥发。', 'medium', '手工制作', '["手工制作","蜡烛制作"]', NOW(), NOW()),
(4, 25, 'single_choice', '十字绣绣线通常由几股组成？A. 1股 B. 6股（可拆分） C. 3股 D. 8股', '["B"]', '十字绣绣线通常为6股，可拆分使用。', 'easy', '手工制作', '["手工制作","十字绣"]', NOW(), NOW()),
(4, 26, 'single_choice', 'DIY手工皮具中，给皮革边缘打磨封边使用？A. 酒精 B. 封边液或床面剂 C. 水 D. 油', '["B"]', '封边液可使皮革边缘光滑美观。', 'medium', '手工制作', '["手工制作","皮具"]', NOW(), NOW()),
(4, 27, 'single_choice', '编织围巾起针时，一般宽度为？A. 10针 B. 30-40针（视毛线和针号） C. 5针 D. 100针', '["B"]', '根据毛线粗细和针号决定起针数。', 'easy', '手工制作', '["手工制作","编织"]', NOW(), NOW()),
(4, 28, 'single_choice', '制作水晶滴胶时，消除气泡的方法是？A. 搅拌越快越好 B. 静置或使用加热枪喷 C. 加水 D. 加酒精', '["B"]', '静置或加热枪可让气泡上浮消除。', 'medium', '手工制作', '["手工制作","滴胶"]', NOW(), NOW()),
(4, 29, 'single_choice', '压花（押花）制作中，鲜花干燥常用方法？A. 微波炉压花板或书本压制 B. 水煮 C. 冷冻 D. 油炸', '["A"]', '压花板或书本压制是最常见的干燥方法。', 'easy', '手工制作', '["手工制作","压花"]', NOW(), NOW()),
(4, 30, 'single_choice', '手工编织中国结常用的线材是？A. 棉线 B. 5号或7号中国结线（涤纶） C. 毛线 D. 铁丝', '["B"]', '中国结线硬度适中，适合定型。', 'easy', '手工制作', '["手工制作","中国结"]', NOW(), NOW()),
(4, 31, 'single_choice', '使用热熔胶枪时，胶棒融化后应？A. 用手触摸 B. 接触纸张或布料快速粘合 C. 涂在皮肤上 D. 加水', '["B"]', '热熔胶需快速粘合，冷却即固化。', 'easy', '手工制作', '["手工制作","热熔胶"]', NOW(), NOW()),
(4, 32, 'single_choice', '废旧玻璃瓶改造花瓶，可用的装饰材料包括？A. 麻绳或丙烯颜料 B. 水 C. 食用油 D. 洗洁精', '["A"]', '麻绳缠绕或丙烯手绘是常用改造方法。', 'easy', '手工制作', '["手工制作","旧物改造"]', NOW(), NOW()),
(4, 33, 'single_choice', '手工皂制作中，“皂化反应”是指？A. 油脂+碱生成肥皂+甘油 B. 油脂加水 C. 碱加水 D. 香料混合', '["A"]', '皂化反应是油脂与碱反应生成皂和甘油。', 'hard', '手工制作', '["手工制作","手工皂"]', NOW(), NOW()),
(4, 34, 'single_choice', '制作毛线球时，两个圆形纸板中间留空绕线，最后？A. 剪开边缘并扎紧 B. 全部拆掉 C. 用胶水固定 D. 加热', '["A"]', '剪开边缘后扎紧即得毛线球。', 'easy', '手工制作', '["手工制作","毛线球"]', NOW(), NOW()),
(4, 35, 'single_choice', '折纸玫瑰花（经典款）常用的基本折法是？A. 川崎玫瑰折法 B. 纸鹤折法 C. 盒子折法 D. 飞机折法', '["A"]', '川崎玫瑰是最经典的折纸玫瑰。', 'medium', '手工制作', '["手工制作","折纸"]', NOW(), NOW()),
(4, 36, 'single_choice', '十字绣绣绷的作用是？A. 保持布料平整 B. 防止脱线 C. 染色 D. 画图', '["A"]', '绣绷可保持绣布平整，便于刺绣。', 'easy', '手工制作', '["手工制作","十字绣"]', NOW(), NOW()),
(4, 37, 'single_choice', '用黏土制作小摆件后，上色最适合用什么颜料？A. 水彩 B. 丙烯颜料 C. 油画颜料 D. 马克笔', '["B"]', '丙烯附着力强，干后防水不褪色。', 'easy', '手工制作', '["手工制作","黏土"]', NOW(), NOW()),
(4, 38, 'single_choice', '毛线刺绣（在毛衣上绣花）常用何种针法？A. 回针绣或缎面绣 B. 机缝 C. 锁边 D. 打结', '["A"]', '回针绣和缎面绣适合毛线刺绣。', 'medium', '手工制作', '["手工制作","刺绣"]', NOW(), NOW()),
(4, 39, 'single_choice', '制作纸质灯笼的骨架，可用？A. 铁丝 B. 竹签或一次性筷子 C. 橡皮泥 D. 吸管', '["B"]', '竹签轻便有韧性，适合做骨架。', 'easy', '手工制作', '["手工制作","纸灯笼"]', NOW(), NOW()),
(4, 40, 'single_choice', '衍纸笔的笔尖通常有？A. 针状 B. 带缝隙的金属叉 C. 圆头 D. 平头', '["B"]', '带缝的金属叉头可夹住纸条卷曲。', 'easy', '手工制作', '["手工制作","衍纸"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(4, 41, 'single_choice', '用旧牛仔裤改造包包，首先应？A. 直接裁剪 B. 拆线、清洗、熨烫 C. 染色 D. 加内衬', '["B"]', '旧衣改造前需清洁熨烫平整。', 'easy', '手工制作', '["手工制作","旧物改造"]', NOW(), NOW()),
(4, 42, 'single_choice', '滴胶作品中出现气泡且已固化，应？A. 重新打磨抛光 B. 加热融化 C. 加水 D. 无法修复', '["A"]', '打磨抛光可去除表面气泡。', 'medium', '手工制作', '["手工制作","滴胶"]', NOW(), NOW()),
(4, 43, 'single_choice', '钩针符号“X”通常代表？A. 短针 B. 长针 C. 引拔针 D. 锁针', '["A"]', 'X是短针的标准符号。', 'easy', '手工制作', '["手工制作","钩针"]', NOW(), NOW()),
(4, 44, 'single_choice', '雪糕棒DIY笔筒，粘合主要使用？A. 502胶 B. 白乳胶或木工胶 C. 热熔胶 D. 双面胶', '["B"]', '白乳胶固化后牢固，适合木制品。', 'easy', '手工制作', '["手工制作","雪糕棒手工"]', NOW(), NOW()),
(4, 45, 'single_choice', '不织布粘贴比缝合更快捷，常用胶是？A. 502 B. 酒精胶或热熔胶 C. 白乳胶 D. 浆糊', '["B"]', '酒精胶和热熔胶粘合力强且干得快。', 'easy', '手工制作', '["手工制作","不织布"]', NOW(), NOW()),
(4, 46, 'single_choice', '串珠戒指的结尾如何固定？A. 打死结后藏线头 B. 用火烧 C. 用胶带 D. 不固定', '["A"]', '打死结是结束编织的常用方式。', 'easy', '手工制作', '["手工制作","串珠"]', NOW(), NOW()),
(4, 47, 'single_choice', '中国结的“酢浆草结”外形像什么？A. 心形 B. 三叶草 C. 方形 D. 蝴蝶', '["B"]', '酢浆草结形似三叶草。', 'easy', '手工制作', '["手工制作","中国结"]', NOW(), NOW()),
(4, 48, 'single_choice', '使用打孔器给皮革打孔后，下一步通常是？A. 缝线 B. 浸泡 C. 打磨 D. 染色', '["A"]', '打孔后即可进行缝线工序。', 'medium', '手工制作', '["手工制作","皮具"]', NOW(), NOW()),
(4, 49, 'single_choice', '马赛克拼贴时，切割小瓷砖使用的工具是？A. 瓷砖钳或玻璃刀 B. 普通剪刀 C. 美工刀 D. 锯子', '["A"]', '瓷砖钳是专门切割小瓷砖的工具。', 'medium', '手工制作', '["手工制作","马赛克"]', NOW(), NOW()),
(4, 50, 'single_choice', '制作纸质风车时，如何让风车转动？A. 折角后中心固定，留空隙 B. 全部粘死 C. 用铁钉钉死 D. 不穿孔', '["A"]', '中心留空隙可让风车自由转动。', 'easy', '手工制作', '["手工制作","风车"]', NOW(), NOW()),
(4, 51, 'single_choice', '金属丝弯折做造型，应选用？A. 铝线（软易塑形） B. 钢丝 C. 铜丝退火后 D. 铁丝', '["A"]', '铝线柔软易弯折，适合手工造型。', 'easy', '手工制作', '["手工制作","金属丝"]', NOW(), NOW()),
(4, 52, 'single_choice', '纸飞机飞得远的折法原理是？A. 重心靠前，机翼对称 B. 机翼越大越好 C. 飞机越重越好 D. 纸越薄越好', '["A"]', '重心靠前和对称设计使飞行更稳定。', 'medium', '手工制作', '["手工制作","纸飞机"]', NOW(), NOW()),
(4, 53, 'single_choice', '羊毛毡针毡时，戳针断裂的原因是？A. 用力过猛或垂直拔针 B. 戳得太浅 C. 羊毛太少 D. 泡沫工作台太硬', '["A"]', '受力不均或角度不对易断针。', 'easy', '手工制作', '["手工制作","羊毛毡"]', NOW(), NOW()),
(4, 54, 'single_choice', '做串珠花瓶时，起线通常需要？A. 加挡珠或回穿固定 B. 打一个结 C. 用胶水 D. 不处理', '["A"]', '挡珠或回穿可固定线头不松散。', 'medium', '手工制作', '["手工制作","串珠"]', NOW(), NOW()),
(4, 55, 'single_choice', '纸雕灯箱的光源通常用？A. 蜡烛 B. LED灯带 C. 白炽灯 D. 荧光灯', '["B"]', 'LED灯带发热小，安全且色彩丰富。', 'easy', '手工制作', '["手工制作","纸雕"]', NOW(), NOW()),
(4, 56, 'single_choice', '石膏翻模制作手模，石膏粉和水比例大致为？A. 1:1 B. 2:1（粉2水1） C. 5:1 D. 10:1', '["B"]', '2:1比例可调出合适稠度的石膏浆。', 'medium', '手工制作', '["手工制作","石膏翻模"]', NOW(), NOW()),
(4, 57, 'single_choice', '折纸蝴蝶结的基本步骤包括？A. 折双正方形再翻折 B. 折纸鹤 C. 折盒子 D. 折飞机', '["A"]', '蝴蝶结由双正方形基础变化而成。', 'medium', '手工制作', '["手工制作","折纸"]', NOW(), NOW()),
(4, 58, 'single_choice', '儿童手工安全剪刀的刀尖通常设计为？A. 圆形 B. 尖锐形 C. 锯齿形 D. 波浪形', '["A"]', '圆形刀尖可防止戳伤。', 'easy', '手工制作', '["手工制作","儿童手工"]', NOW(), NOW()),
(4, 59, 'single_choice', '橡皮章转印图案时，常用？A. 洗甲水或铅笔画后转印 B. 水彩 C. 油墨直接印 D. 圆珠笔', '["A"]', '洗甲水或铅笔转印是常用方法。', 'medium', '手工制作', '["手工制作","橡皮章"]', NOW(), NOW()),
(4, 60, 'single_choice', '制作不织布花束，花瓣边缘不上色也可用？A. 色粉笔擦色 B. 马克笔 C. 水彩 D. 指甲油', '["A"]', '色粉笔擦色可做出渐变效果。', 'easy', '手工制作', '["手工制作","不织布"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(4, 61, 'single_choice', '编织毛衣时，单片织完后需要缝合，常用？A. 回针缝或挑针缝合 B. 锁边缝 C. 平针缝 D. 藏针缝', '["A"]', '回针缝和挑针缝合是常用毛衣缝合方法。', 'medium', '手工制作', '["手工制作","编织"]', NOW(), NOW()),
(4, 62, 'single_choice', '热缩片打孔应该在？A. 加热前 B. 加热后 C. 任意 D. 不打孔', '["A"]', '加热前打孔，加热后孔会缩小。', 'easy', '手工制作', '["手工制作","热缩片"]', NOW(), NOW()),
(4, 63, 'single_choice', '木工DIY小物件，打磨木料的顺序是？A. 粗砂纸到细砂纸 B. 细到粗 C. 只用一种 D. 不用砂纸', '["A"]', '从粗到细打磨可达到光滑效果。', 'easy', '手工制作', '["手工制作","木工"]', NOW(), NOW()),
(4, 64, 'single_choice', '软陶（聚合物黏土）需要用什么方式定型？A. 风干 B. 烤箱烘烤 C. 水煮 D. 日晒', '["B"]', '软陶需烤箱烘烤固化。', 'easy', '手工制作', '["手工制作","软陶"]', NOW(), NOW()),
(4, 65, 'single_choice', '纸模型粘贴时，胶水涂在粘贴边上，这种边称为？A. 黏贴襟片 B. 折痕线 C. 切割线 D. 参考线', '["A"]', '黏贴襟片是用于涂胶粘贴的边。', 'easy', '手工制作', '["手工制作","纸模型"]', NOW(), NOW()),
(4, 66, 'single_choice', '制作丝带绣时，丝带穿针后需？A. 打结 B. 将针尖扎过丝带尾部固定 C. 双股穿 D. 涂胶', '["B"]', '扎过丝带可固定不滑脱。', 'medium', '手工制作', '["手工制作","丝带绣"]', NOW(), NOW()),
(4, 67, 'single_choice', '旧T恤改造环保袋，无需缝合的方法？A. 剪下袖口和领口，底部剪成流苏打结 B. 用胶水 C. 用订书机 D. 用别针', '["A"]', '底部流苏打结可成型，无需针线。', 'easy', '手工制作', '["手工制作","旧物改造"]', NOW(), NOW()),
(4, 68, 'single_choice', '黏土调色时，少量多次加入颜料，否则？A. 黏土变软塌 B. 颜色过深无法补救 C. 更容易干 D. 粘手', '["B"]', '颜料过量颜色会过深且无法褪色。', 'easy', '手工制作', '["手工制作","黏土"]', NOW(), NOW()),
(4, 69, 'single_choice', '中国结常用的固定针（珠针）用于？A. 临时固定线圈 B. 永久固定 C. 作为结体 D. 剪线', '["A"]', '珠针在编织过程中临时固定线材。', 'easy', '手工制作', '["手工制作","中国结"]', NOW(), NOW()),
(4, 70, 'single_choice', '串珠时，右手线穿过左手的珠子，这个动作叫做？A. 回穿 B. 对穿 C. 加珠 D. 跳过', '["B"]', '对穿是左右线交叉穿过同一珠子。', 'medium', '手工制作', '["手工制作","串珠"]', NOW(), NOW()),
(4, 71, 'single_choice', '用鸡蛋托做手工花，上色最好用？A. 丙烯颜料 B. 水彩 C. 马克笔 D. 油画棒', '["A"]', '丙烯附着力强，适合纸浆材质。', 'easy', '手工制作', '["手工制作","变废为宝"]', NOW(), NOW()),
(4, 72, 'single_choice', '十字绣绣图尺寸计算，14CT绣布绣100格大约需多少厘米？A. 5cm B. 18cm C. 30cm D. 50cm', '["B"]', '14CT每英寸14格，约每厘米5.5格，100格约18cm。', 'hard', '手工制作', '["手工制作","十字绣"]', NOW(), NOW()),
(4, 73, 'single_choice', '树脂粘土和超轻粘土的主要区别是？A. 树脂粘土干后半透明且有韧性 B. 一个有毒 C. 颜色不同 D. 价格不同', '["A"]', '树脂粘土干后呈半透明，质感类似树脂。', 'medium', '手工制作', '["手工制作","黏土"]', NOW(), NOW()),
(4, 74, 'single_choice', '毛线编织换线时，新线应在？A. 上一行结束时打结 B. 任意位置 C. 中间打结 D. 不换', '["A"]', '行末换线可保持图案完整。', 'easy', '手工制作', '["手工制作","编织"]', NOW(), NOW()),
(4, 75, 'single_choice', '纸玫瑰花染色可以使用？A. 水彩或喷漆 B. 油彩 C. 指甲油 D. 酱油', '["A"]', '水彩和喷漆上色均匀。', 'easy', '手工制作', '["手工制作","纸艺花"]', NOW(), NOW()),
(4, 76, 'single_choice', '冰棒棍制作相框，连接处除了胶水还可？A. 用热熔胶枪固定夹子 B. 用钉子 C. 用绳子 D. 用订书机', '["A"]', '热熔胶枪可快速固定。', 'easy', '手工制作', '["手工制作","雪糕棒手工"]', NOW(), NOW()),
(4, 77, 'single_choice', '不织布卡通发夹，粘贴发夹底座可用？A. 酒精胶或E6000 B. 双面胶 C. 白乳胶 D. 浆糊', '["A"]', '酒精胶和E6000粘合力强，适合金属和布料。', 'easy', '手工制作', '["手工制作","不织布"]', NOW(), NOW()),
(4, 78, 'single_choice', '衍纸条的宽度常见规格有？A. 3mm或5mm B. 1cm C. 2cm D. 5cm', '["A"]', '3mm和5mm是最常见的衍纸条宽度。', 'easy', '手工制作', '["手工制作","衍纸"]', NOW(), NOW()),
(4, 79, 'single_choice', '制作毛绒球器比用纸板绕线的优点是？A. 更圆且效率高 B. 更省钱 C. 更易断线 D. 颜色多', '["A"]', '毛球器可做出更规整的圆球。', 'easy', '手工制作', '["手工制作","毛线球"]', NOW(), NOW()),
(4, 80, 'single_choice', '手工香皂包装前需等待？A. 1-2天脱模，再放置4-6周熟化 B. 立即包装 C. 冷冻后包装 D. 加热后包装', '["A"]', '手工皂需熟化使pH值降低。', 'medium', '手工制作', '["手工制作","手工皂"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(4, 81, 'single_choice', '纸艺花制作时，给花瓣做出卷边效果可用？A. 用笔杆或牙签卷压 B. 用手撕 C. 烧边 D. 沾水', '["A"]', '用笔杆卷压可使花瓣自然卷曲。', 'easy', '手工制作', '["手工制作","纸艺花"]', NOW(), NOW()),
(4, 82, 'single_choice', '钩针环形起针（圈钩）常用于？A. 玩偶头部或帽子顶部 B. 围巾 C. 毯子 D. 平面图案', '["A"]', '环形起针适合圆形编织起始。', 'easy', '手工制作', '["手工制作","钩针"]', NOW(), NOW()),
(4, 83, 'single_choice', 'DIY手机壳滴胶时，如何让胶均匀覆盖？A. 倾斜流动或用棒子刮平 B. 厚涂一次 C. 刷子刷 D. 喷枪', '["A"]', '倾斜流动可使胶自然流平。', 'medium', '手工制作', '["手工制作","滴胶"]', NOW(), NOW()),
(4, 84, 'single_choice', '拼布压线时，使用什么工具画线？A. 水消笔或热消笔 B. 圆珠笔 C. 铅笔 D. 钢笔', '["A"]', '水消笔遇水消失，热消笔加热消失。', 'easy', '手工制作', '["手工制作","拼布"]', NOW(), NOW()),
(4, 85, 'single_choice', '制作植物标本相框，干燥的植物如何固定？A. 用白乳胶或双面胶 B. 缝上去 C. 压膜 D. 不固定', '["A"]', '胶水固定可防止植物移动。', 'easy', '手工制作', '["手工制作","压花"]', NOW(), NOW()),
(4, 86, 'single_choice', '纸模型制作中，压折痕的工具最好用？A. 无墨圆珠笔或折痕笔 B. 指甲 C. 刀背 D. 尺子边缘', '["A"]', '圆珠笔可压出清晰的折痕而不划伤纸。', 'easy', '手工制作', '["手工制作","纸模型"]', NOW(), NOW()),
(4, 87, 'single_choice', '羊毛毡湿毡缩绒的原理是？A. 温水加肥皂使鳞片张开并纠缠 B. 用针戳 C. 加热 D. 冷冻', '["A"]', '热水和肥皂使羊毛鳞片张开并互相纠缠。', 'hard', '手工制作', '["手工制作","羊毛毡"]', NOW(), NOW()),
(4, 88, 'single_choice', '缝纫机底线用完时，面线会？A. 无法形成线迹，空走 B. 正常缝 C. 断针 D. 报警', '["A"]', '无底线时面线无法勾连，形成空走。', 'easy', '手工制作', '["手工制作","缝纫"]', NOW(), NOW()),
(4, 89, 'single_choice', '手工皮具打斩（打缝线孔）应使用？A. 菱斩或斜平斩 B. 普通钉子 C. 电钻 D. 锥子', '["A"]', '菱斩可打出规整的缝线孔。', 'medium', '手工制作', '["手工制作","皮具"]', NOW(), NOW()),
(4, 90, 'single_choice', '串珠苹果的主体通常采用什么穿法？A. 球形穿法（6珠圈起） B. 平面穿 C. 线性穿 D. 随意', '["A"]', '球形穿法可做出立体苹果造型。', 'medium', '手工制作', '["手工制作","串珠"]', NOW(), NOW()),
(4, 91, 'single_choice', '水晶滴胶分层灌注时，需等下层？A. 半固化（果冻状）再浇上层 B. 完全固化再浇 C. 液态时浇 D. 加热时浇', '["A"]', '半固化时浇上层可使两层融合。', 'medium', '手工制作', '["手工制作","滴胶"]', NOW(), NOW()),
(4, 92, 'single_choice', '不织布字母贴片，字体镂空效果怎么做？A. 挖洞后缝衬底布 B. 直接剪字母 C. 绣上去 D. 画上去', '["A"]', '挖洞后加衬布可做出镂空效果。', 'easy', '手工制作', '["手工制作","不织布"]', NOW(), NOW()),
(4, 93, 'single_choice', '使用木工胶粘合木片后，一般需要？A. 夹子固定加压几小时 B. 立即松开 C. 加热 D. 浇水', '["A"]', '加压固定可保证粘合牢固。', 'easy', '手工制作', '["手工制作","木工"]', NOW(), NOW()),
(4, 94, 'single_choice', '纸风车的叶片数量常见是？A. 4叶 B. 3叶 C. 6叶 D. 8叶', '["A"]', '四叶风车是最经典的造型。', 'easy', '手工制作', '["手工制作","风车"]', NOW(), NOW()),
(4, 95, 'single_choice', '橡皮章留白中，“搓衣板留白”是？A. 平行条状刻痕 B. 完全铲平 C. 保留原样 D. 挖圆形', '["A"]', '搓衣板留白是平行条状刻痕。', 'medium', '手工制作', '["手工制作","橡皮章"]', NOW(), NOW()),
(4, 96, 'single_choice', '废旧牛仔裤改围裙，应保留原裤的？A. 裤袢和口袋 B. 拉链 C. 裤腿 D. 标签', '["A"]', '保留裤袢可穿带，口袋可放东西。', 'easy', '手工制作', '["手工制作","旧物改造"]', NOW(), NOW()),
(4, 97, 'single_choice', '毛线编织麻花针法需要借助什么工具？A. 麻花针或额外棒针 B. 钩针 C. 记号扣 D. 剪刀', '["A"]', '麻花针用于临时挪移线圈。', 'medium', '手工制作', '["手工制作","编织"]', NOW(), NOW()),
(4, 98, 'single_choice', '陶泥作品烧制前需要？A. 完全干燥（素烧） B. 上釉 C. 浸泡 D. 冷冻', '["A"]', '完全干燥可防止烧制时爆裂。', 'medium', '手工制作', '["手工制作","陶艺"]', NOW(), NOW()),
(4, 99, 'single_choice', '用毛线球做小动物，修剪绒毛使用？A. 锋利剪刀 B. 指甲剪 C. 菜刀 D. 打火机', '["A"]', '锋利剪刀可精细修剪造型。', 'easy', '手工制作', '["手工制作","毛线球"]', NOW(), NOW()),
(4, 100, 'single_choice', '制作干花滴胶手机壳，放入干花前应先？A. 倒一层薄胶封底 B. 直接放干花 C. 加湿 D. 上色', '["A"]', '封底可固定干花位置且防止气泡。', 'medium', '手工制作', '["手工制作","滴胶"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(4, 101, 'fill_blank', '折纸中，将一个角折向对边形成的线称为______。', '["折痕"]', '折痕是折叠留下的痕迹。', 'easy', '手工制作', '["手工制作","折纸"]', NOW(), NOW()),
(4, 102, 'fill_blank', '十字绣绣法中最基础的是全针绣，形状为______。', '["X形"]', '全针绣是两针交叉形成X形。', 'easy', '手工制作', '["手工制作","十字绣"]', NOW(), NOW()),
(4, 103, 'fill_blank', '羊毛毡针毡时，工作台通常使用______。', '["泡沫垫或刷子垫"]', '泡沫垫可保护戳针和工作台。', 'easy', '手工制作', '["手工制作","羊毛毡"]', NOW(), NOW()),
(4, 104, 'fill_blank', '制作串珠时，用于防止珠子滑落的挡珠（小圆珠）也叫______。', '["定位珠或挡珠"]', '定位珠用于固定线头。', 'easy', '手工制作', '["手工制作","串珠"]', NOW(), NOW()),
(4, 105, 'fill_blank', '纸艺花瓣边缘涂色做出渐变效果，可用______。', '["色粉或印台"]', '色粉可擦出自然渐变。', 'easy', '手工制作', '["手工制作","纸艺花"]', NOW(), NOW()),
(4, 106, 'fill_blank', '橡皮章雕刻时，笔刀握法类似______。', '["握铅笔"]', '握笔姿势便于精确控制。', 'easy', '手工制作', '["手工制作","橡皮章"]', NOW(), NOW()),
(4, 107, 'fill_blank', '滴胶AB胶重量比通常为______（A胶：B胶）。', '["3:1"]', '常见滴胶比例为重量比3:1。', 'medium', '手工制作', '["手工制作","滴胶"]', NOW(), NOW()),
(4, 108, 'fill_blank', '钩针基础针法中，长针的符号是______。', '["T（中间一横）"]', 'T带横线表示长针。', 'easy', '手工制作', '["手工制作","钩针"]', NOW(), NOW()),
(4, 109, 'fill_blank', '黏土制作中用亚克力板压扁土块，作用是______。', '["均匀厚度"]', '亚克力板可压出平整均匀的厚度。', 'easy', '手工制作', '["手工制作","黏土"]', NOW(), NOW()),
(4, 110, 'fill_blank', '不织布的热切边缘可防止______。', '["起毛"]', '热切可熔合纤维边缘。', 'easy', '手工制作', '["手工制作","不织布"]', NOW(), NOW()),
(4, 111, 'fill_blank', '中国结的线头处理用打火机烧一下是为了______。', '["防散"]', '烧熔可固定线头不散开。', 'easy', '手工制作', '["手工制作","中国结"]', NOW(), NOW()),
(4, 112, 'fill_blank', '纸模型零件编号应______后再剪下。', '["核对"]', '核对编号确保零件正确对应。', 'easy', '手工制作', '["手工制作","纸模型"]', NOW(), NOW()),
(4, 113, 'fill_blank', '制作丝网花花蕊可使用______。', '["乳胶或假花蕊"]', '乳胶可浸渍做花蕊。', 'easy', '手工制作', '["手工制作","丝网花"]', NOW(), NOW()),
(4, 114, 'fill_blank', '手工皂入模后需用______包裹保温。', '["毛巾或保温箱"]', '保温可促进皂化反应。', 'easy', '手工制作', '["手工制作","手工皂"]', NOW(), NOW()),
(4, 115, 'fill_blank', '编织围巾收针时，将线圈套过的动作称为______。', '["套收针或平收"]', '套收针是常见的收针方法。', 'easy', '手工制作', '["手工制作","编织"]', NOW(), NOW()),
(4, 116, 'fill_blank', '热缩片加热后体积缩小至原来的约______分之一。', '["3-5"]', '热缩片收缩率约1/3到1/5。', 'medium', '手工制作', '["手工制作","热缩片"]', NOW(), NOW()),
(4, 117, 'fill_blank', '马赛克填缝剂未干时，可用______擦除多余的。', '["海绵"]', '湿海绵可擦去表面多余的填缝剂。', 'easy', '手工制作', '["手工制作","马赛克"]', NOW(), NOW()),
(4, 118, 'fill_blank', '衍纸工具中，卷纸后取下纸卷可用______辅助。', '["镊子"]', '镊子可小心取下纸卷不破坏形状。', 'easy', '手工制作', '["手工制作","衍纸"]', NOW(), NOW()),
(4, 119, 'fill_blank', '旧衣物改造前必须______。', '["清洗"]', '清洁是改造前的必要步骤。', 'easy', '手工制作', '["手工制作","旧物改造"]', NOW(), NOW()),
(4, 120, 'fill_blank', '毛球器绕线后，用剪刀从______剪开。', '["中间凹槽"]', '沿凹槽剪开可得到规整的毛线束。', 'easy', '手工制作', '["手工制作","毛线球"]', NOW(), NOW()),
(4, 121, 'fill_blank', '皮革床面剂打磨后会使皮边______。', '["光滑发亮"]', '床面剂可封住皮革纤维边缘。', 'medium', '手工制作', '["手工制作","皮具"]', NOW(), NOW()),
(4, 122, 'fill_blank', '滴胶固化后表面不平，可______修复。', '["再封一层薄胶"]', '再封一层可填平表面凹陷。', 'medium', '手工制作', '["手工制作","滴胶"]', NOW(), NOW()),
(4, 123, 'fill_blank', '折纸鹤最后一步需要______才能鼓起。', '["吹气"]', '吹气可使纸鹤身体立体化。', 'easy', '手工制作', '["手工制作","折纸"]', NOW(), NOW()),
(4, 124, 'fill_blank', '拼布中被子的三层结构是表布、铺棉和______。', '["底布"]', '底布是拼布被子的最下层。', 'easy', '手工制作', '["手工制作","拼布"]', NOW(), NOW()),
(4, 125, 'fill_blank', '软陶烘烤温度通常在______摄氏度。', '["110-130"]', '软陶烘烤温度约110-130℃。', 'easy', '手工制作', '["手工制作","软陶"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(5, 1, 'single_choice', '发现家中燃气泄漏，以下哪项操作是正确的？A. 打开抽油烟机排风 B. 关闭燃气总阀，开窗通风 C. 立即打电话报警 D. 开灯检查', '["B"]', '关闭阀门和开窗可防止燃气聚集爆炸。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 2, 'single_choice', '电器起火时，首先应做什么？A. 用水泼灭 B. 切断电源，再用灭火器扑救 C. 用棉被盖住 D. 直接逃跑', '["B"]', '断电可防止触电，再用灭火器灭火。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 3, 'single_choice', '油锅起火时，正确的灭火方法是？A. 用水浇灭 B. 盖上锅盖或放入青菜 C. 用面粉撒盖 D. 端起油锅', '["B"]', '隔绝空气可熄灭油锅火焰。', 'easy', '安全常识', '["安全常识","厨房安全"]', NOW(), NOW()),
(5, 4, 'single_choice', '当身上衣物着火时，正确的做法是？A. 快速奔跑呼救 B. 就地打滚压灭火焰 C. 用手拍打 D. 跳入水中', '["B"]', '就地打滚可隔绝空气灭火。', 'easy', '安全常识', '["安全常识","火灾逃生"]', NOW(), NOW()),
(5, 5, 'single_choice', '乘坐电梯时，电梯突然下坠，应如何保护自己？A. 跳跃缓冲 B. 背部和头部紧贴电梯内壁，膝盖弯曲，手抱颈 C. 躺平 D. 扒门逃生', '["B"]', '屈膝可缓冲冲击力，保护脊椎。', 'medium', '安全常识', '["安全常识","电梯安全"]', NOW(), NOW()),
(5, 6, 'single_choice', '雷雨天气时，以下哪种行为最危险？A. 室内关窗 B. 打手机 C. 拔掉电器插头 D. 站在大树下避雨', '["D"]', '大树易遭雷击，站树下极其危险。', 'easy', '安全常识', '["安全常识","防雷安全"]', NOW(), NOW()),
(5, 7, 'single_choice', '发现有人触电，首先应？A. 用手拉开触电者 B. 切断电源或用干燥木棍挑开电线 C. 立即做人工呼吸 D. 呼叫名字', '["B"]', '先断电或用绝缘物分离，再施救。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 8, 'single_choice', '食物中毒后，第一时间应做什么？A. 吃止泻药 B. 大量喝水催吐并尽快就医 C. 喝醋 D. 运动出汗', '["B"]', '催吐可排出毒物，尽快就医是关键。', 'easy', '安全常识', '["安全常识","食品安全"]', NOW(), NOW()),
(5, 9, 'single_choice', '以下哪个不是灭火器的正确使用方法（口诀）？A. 提 B. 拔 C. 握 D. 扔', '["D"]', '灭火器使用口诀：提、拔、握、压。', 'easy', '安全常识', '["安全常识","消防器材"]', NOW(), NOW()),
(5, 10, 'single_choice', '家中保险丝熔断，应如何解决？A. 用铁丝代替 B. 用铜丝代替 C. 更换相同规格的保险丝 D. 用铝丝代替', '["C"]', '必须使用相同规格保险丝，不可替代。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 11, 'single_choice', '遇到地震时，在室内应优先躲避在哪里？A. 窗口边 B. 吊灯下 C. 坚固的桌子下或墙角 D. 电梯内', '["C"]', '桌下或墙角可形成三角安全区。', 'easy', '安全常识', '["安全常识","地震避险"]', NOW(), NOW()),
(5, 12, 'single_choice', '心肺复苏时，胸外按压的深度至少应为多少厘米？A. 1-2cm B. 5-6cm C. 10cm D. 15cm', '["B"]', '成人按压深度应达到5-6厘米。', 'hard', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 13, 'single_choice', '以下哪种情况需要拨打120急救电话？A. 轻微擦伤 B. 意识丧失或严重胸痛 C. 感冒流涕 D. 失眠', '["B"]', '意识丧失和严重胸痛需紧急就医。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 14, 'single_choice', '使用燃气热水器时，为防止一氧化碳中毒，应注意？A. 紧闭门窗保暖 B. 保持通风，排烟管通向室外 C. 长时间连续使用 D. 安装在浴室内部', '["B"]', '通风和排烟是防中毒的关键。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 15, 'single_choice', '电动车应在哪里充电最安全？A. 楼道内 B. 室内客厅 C. 室外集中充电桩 D. 地下室', '["C"]', '室外充电桩最安全，楼道室内禁止。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 16, 'single_choice', '高层建筑发生火灾时，正确的逃生方向是？A. 乘电梯下楼 B. 向楼下疏散，不可盲目跳楼 C. 往楼顶跑 D. 躲在卫生间', '["B"]', '向下疏散最安全，切勿乘坐电梯。', 'easy', '安全常识', '["安全常识","火灾逃生"]', NOW(), NOW()),
(5, 17, 'single_choice', '以下哪个是海姆立克急救法用于？A. 外伤出血 B. 气道异物梗阻 C. 心脏病发作 D. 骨折', '["B"]', '海姆立克法用于解除气道异物堵塞。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 18, 'single_choice', '发现陌生人尾随时，以下做法错误的是？A. 快速走向人多的地方 B. 立即跑回家开门 C. 大声呼救 D. 打电话给家人', '["B"]', '跑回家开门可能让歹徒跟进，危险。', 'easy', '安全常识', '["安全常识","人身安全"]', NOW(), NOW()),
(5, 19, 'single_choice', '网络安全中，以下哪个密码最安全？A. 123456 B. 生日日期 C. 大小写字母+数字+符号组合 D. 重复数字', '["C"]', '复杂组合密码更难被破解。', 'easy', '安全常识', '["安全常识","网络安全"]', NOW(), NOW()),
(5, 20, 'single_choice', '烫伤后，正确的急救步骤是？A. 涂抹牙膏 B. 冲流动冷水15-30分钟，再就医 C. 用冰块直接冰敷 D. 刺破水泡', '["B"]', '冷水冲洗可降温止痛。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(5, 21, 'single_choice', '使用微波炉时，以下哪种容器不能放入？A. 陶瓷碗 B. 耐热玻璃 C. 金属容器或锡纸 D. 塑料PP5餐盒', '["C"]', '金属会反射微波，产生火花。', 'easy', '安全常识', '["安全常识","家电安全"]', NOW(), NOW()),
(5, 22, 'single_choice', '陌生人敲门声称是燃气检修员，应如何做？A. 立即开门 B. 不开门，先电话核实身份 C. 让其直接进门 D. 给工具', '["B"]', '核实身份可防止诈骗和坏人闯入。', 'easy', '安全常识', '["安全常识","居家安全"]', NOW(), NOW()),
(5, 23, 'single_choice', '游泳时发生腿部抽筋，应？A. 惊慌挣扎 B. 保持镇定，呼救并拉伸抽筋部位 C. 继续往前游 D. 下沉', '["B"]', '保持镇定并拉伸可缓解抽筋。', 'easy', '安全常识', '["安全常识","运动安全"]', NOW(), NOW()),
(5, 24, 'single_choice', '以下哪个标志表示“当心触电”？A. 黄色闪电符号 B. 红色圆圈斜杠 C. 蓝色水滴 D. 绿色箭头', '["A"]', '黄色闪电是当心触电的警示标志。', 'easy', '安全常识', '["安全常识","安全标志"]', NOW(), NOW()),
(5, 25, 'single_choice', '被猫狗咬伤后，首要处理是？A. 包扎伤口 B. 用肥皂水和流动清水交替冲洗15分钟，并就医打疫苗 C. 止血 D. 热敷', '["B"]', '冲洗消毒后需尽快接种狂犬疫苗。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 26, 'single_choice', '火灾逃生时，用湿毛巾捂住口鼻的主要作用是？A. 防止吸入有毒烟雾 B. 保暖 C. 美观 D. 增加体力', '["A"]', '湿毛巾可过滤部分有毒烟雾。', 'easy', '安全常识', '["安全常识","火灾逃生"]', NOW(), NOW()),
(5, 27, 'single_choice', '使用电器时，发现电源线发热发软，应？A. 继续使用 B. 立即停止使用并检查更换 C. 用胶带缠一下 D. 浇水降温', '["B"]', '电源线发热是过载或老化的危险信号。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 28, 'single_choice', '以下哪项是安全过马路的做法？A. 翻越护栏 B. 闯黄灯 C. 走斑马线，红灯停绿灯行 D. 低头看手机', '["C"]', '遵守交通规则是安全通行的基础。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 29, 'single_choice', '暴雨天遇到积水路段，应？A. 强行涉水通过 B. 绕行，警惕井盖被冲开 C. 在水中玩耍 D. 快速奔跑', '["B"]', '井盖被冲开易踩空溺水。', 'easy', '安全常识', '["安全常识","极端天气"]', NOW(), NOW()),
(5, 30, 'single_choice', '发现煤气中毒者，应首先？A. 给其喝水 B. 立即开窗通风并移至空气新鲜处 C. 心肺复苏 D. 等待', '["B"]', '先脱离中毒环境是关键。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 31, 'single_choice', '扑救精密仪器火灾，应使用哪种灭火器？A. 泡沫灭火器 B. 干粉灭火器 C. 二氧化碳灭火器 D. 水', '["C"]', '二氧化碳灭火器无残留，不损坏仪器。', 'medium', '安全常识', '["安全常识","消防器材"]', NOW(), NOW()),
(5, 32, 'single_choice', '以下哪个是安全电压等级？A. 220V B. 380V C. 36V或12V D. 110V', '["C"]', '安全电压为36V、24V、12V。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 33, 'single_choice', '遇到山洪暴发，应向哪个方向逃生？A. 沿山谷向下 B. 向与洪流垂直的高处 C. 顺着水流方向 D. 原地不动', '["B"]', '垂直方向往高处逃可避开洪水。', 'easy', '安全常识', '["安全常识","自然灾害"]', NOW(), NOW()),
(5, 34, 'single_choice', '使用梯子时，梯脚应？A. 放在光滑地面上 B. 有人扶稳或防滑处理，角度约75度 C. 倾斜45度 D. 放在台阶上', '["B"]', '75度夹角最稳定安全。', 'easy', '安全常识', '["安全常识","作业安全"]', NOW(), NOW()),
(5, 35, 'single_choice', '以下哪项不是中暑的正确处理方法？A. 移至阴凉处 B. 喝冰水或淡盐水 C. 用酒精擦拭全身降温 D. 服用退烧药', '["D"]', '退烧药对中暑无效且可能有害。', 'medium', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 36, 'single_choice', '饮酒后多久可以开车？A. 休息一小时 B. 等感觉清醒 C. 至少24小时以上，确保酒精代谢完 D. 喝咖啡后', '["C"]', '酒精代谢需较长时间，24小时以上更安全。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 37, 'single_choice', '遇到电梯困人，应？A. 强行扒门 B. 按紧急呼叫按钮等待救援 C. 跳跃 D. 从天花板爬出', '["B"]', '等待专业救援最安全。', 'easy', '安全常识', '["安全常识","电梯安全"]', NOW(), NOW()),
(5, 38, 'single_choice', '以下哪个是易燃易爆品？A. 矿泉水 B. 空气清新剂（压缩罐） C. 书本 D. 陶瓷', '["B"]', '压缩气体罐遇高温可能爆炸。', 'easy', '安全常识', '["安全常识","危险品"]', NOW(), NOW()),
(5, 39, 'single_choice', '雷雨天气中，在室内应？A. 洗澡 B. 靠近金属门窗 C. 拔掉电器插头，远离水管 D. 看电视', '["C"]', '雷击可能通过金属管道传导。', 'easy', '安全常识', '["安全常识","防雷安全"]', NOW(), NOW()),
(5, 40, 'single_choice', '以下哪个是安全使用燃气的正确顺序？A. 先关火再关气 B. 先关气再关火 C. 只关气 D. 只关火', '["A"]', '先关火可防止回火。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(5, 41, 'single_choice', '汽车行驶中，儿童应坐在？A. 副驾驶 B. 后排安全座椅上 C. 大人怀里 D. 后备箱', '["B"]', '儿童安全座椅是法律规定的最安全方式。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 42, 'single_choice', '干粉灭火器上的压力表指针在绿色区域表示？A. 压力过高 B. 压力正常 C. 压力偏低 D. 失效', '["B"]', '绿色区域表示压力正常可用。', 'easy', '安全常识', '["安全常识","消防器材"]', NOW(), NOW()),
(5, 43, 'single_choice', '使用高压锅前，必须检查？A. 锅盖是否旋合到位及排气孔畅通 B. 锅底是否干净 C. 手柄是否烫 D. 颜色', '["A"]', '排气孔堵塞会导致爆炸危险。', 'easy', '安全常识', '["安全常识","厨房安全"]', NOW(), NOW()),
(5, 44, 'single_choice', '以下哪种行为容易导致手机爆炸？A. 原装充电器充电 B. 边充电边玩发热严重 C. 放在通风处 D. 使用合格电池', '["B"]', '边充边玩导致过热，可能引起爆炸。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 45, 'single_choice', '遇到踩踏事件时，保护自己的姿势是？A. 双手交叉抱头，侧卧蜷缩 B. 站立不动 C. 弯腰捡东西 D. 逆着人流跑', '["A"]', '侧卧蜷缩可保护重要器官。', 'medium', '安全常识', '["安全常识","公共安全"]', NOW(), NOW()),
(5, 46, 'single_choice', '冰箱应放置在什么位置以保证安全？A. 紧贴墙壁 B. 靠近燃气灶 C. 留出散热空间，远离热源 D. 潮湿角落', '["C"]', '散热空间可防止过热耗电。', 'easy', '安全常识', '["安全常识","家电安全"]', NOW(), NOW()),
(5, 47, 'single_choice', '以下哪种伤口需要打破伤风针？A. 干净刀片划伤浅口 B. 被生锈铁钉扎伤较深 C. 蚊虫叮咬 D. 擦伤', '["B"]', '深窄伤口易形成厌氧环境，破伤风杆菌易繁殖。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 48, 'single_choice', '插座过载的主要原因是？A. 同时接入过多大功率电器 B. 插头松动 C. 电压过低 D. 插座颜色', '["A"]', '过载会导致发热起火。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 49, 'single_choice', '化学实验室中，不能将水倒入浓硫酸的原因是？A. 产生大量热导致飞溅 B. 会爆炸 C. 降低浓度 D. 变色', '["A"]', '水倒入浓硫酸会剧烈放热飞溅，应酸入水。', 'medium', '安全常识', '["安全常识","化学安全"]', NOW(), NOW()),
(5, 50, 'single_choice', '台风天，应如何防护窗户？A. 打开通风 B. 贴上米字形胶带 C. 用报纸糊上 D. 拆除', '["B"]', '胶带可增加玻璃强度，防止破碎飞溅。', 'easy', '安全常识', '["安全常识","极端天气"]', NOW(), NOW()),
(5, 51, 'single_choice', '炒菜时油锅着火，盖上锅盖后还应？A. 立即打开 B. 关闭燃气阀门 C. 浇水 D. 加盐', '["B"]', '关闭气源可防止复燃。', 'easy', '安全常识', '["安全常识","厨房安全"]', NOW(), NOW()),
(5, 52, 'single_choice', '安全帽的主要作用是？A. 防风 B. 防砸防冲击 C. 保暖 D. 装饰', '["B"]', '安全帽可保护头部免受冲击伤害。', 'easy', '安全常识', '["安全常识","作业安全"]', NOW(), NOW()),
(5, 53, 'single_choice', '高层建筑发生火灾，如果楼道被浓烟封锁，应？A. 强行冲出 B. 退回室内，封堵门缝，在窗口求救 C. 跳楼 D. 躲进柜子', '["B"]', '封堵门缝可防止烟雾进入室内。', 'easy', '安全常识', '["安全常识","火灾逃生"]', NOW(), NOW()),
(5, 54, 'single_choice', '使用电热毯时，以下哪项错误？A. 睡前通电预热，睡觉时关闭 B. 折叠使用 C. 不折叠，铺平 D. 不长时间通电', '["B"]', '折叠使用会导致局部过热起火。', 'easy', '安全常识', '["安全常识","家电安全"]', NOW(), NOW()),
(5, 55, 'single_choice', '交通事故报警电话是？A. 110 B. 119 C. 122 D. 120', '["C"]', '122是交通事故报警专用电话。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 56, 'single_choice', '发现有人溺水，不会游泳时应？A. 跳下水救人 B. 大声呼救，抛漂浮物或竹竿 C. 旁观 D. 跑开', '["B"]', '利用工具施救最安全。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 57, 'single_choice', '以下哪种食物容易出现黄曲霉素（强致癌物）？A. 新鲜蔬菜 B. 发霉的花生或玉米 C. 冷冻肉 D. 大米', '["B"]', '发霉的花生玉米易产生黄曲霉素。', 'easy', '安全常识', '["安全常识","食品安全"]', NOW(), NOW()),
(5, 58, 'single_choice', '安全出口标志的颜色通常是？A. 红色 B. 绿色 C. 黄色 D. 蓝色', '["B"]', '绿色是安全出口的标准颜色。', 'easy', '安全常识', '["安全常识","安全标志"]', NOW(), NOW()),
(5, 59, 'single_choice', '电焊作业时，必须佩戴？A. 太阳镜 B. 防护面罩或护目镜 C. 普通眼镜 D. 泳镜', '["B"]', '防护面罩可防弧光灼伤眼睛。', 'easy', '安全常识', '["安全常识","作业安全"]', NOW(), NOW()),
(5, 60, 'single_choice', '以下哪种情况不能使用心肺复苏？A. 无呼吸无意识 B. 胸廓有起伏有呼吸 C. 溺水后无呼吸 D. 电击后无呼吸', '["B"]', '有呼吸有心跳无需进行心肺复苏。', 'medium', '安全常识', '["安全常识","急救知识"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(5, 61, 'single_choice', '防烟面罩（过滤式）的有效时间约为？A. 10分钟 B. 30-60分钟 C. 2小时 D. 5小时', '["B"]', '防烟面罩有效时间约30-60分钟。', 'easy', '安全常识', '["安全常识","消防器材"]', NOW(), NOW()),
(5, 62, 'single_choice', '家庭药箱中应常备？A. 创可贴、碘伏、退烧药 B. 抗生素 C. 安眠药 D. 农药', '["A"]', '常备基础药品和消毒用品。', 'easy', '安全常识', '["安全常识","家庭安全"]', NOW(), NOW()),
(5, 63, 'single_choice', '使用杀虫剂后，应？A. 立即点蚊香 B. 通风后再进入房间 C. 关窗密闭 D. 开火做饭', '["B"]', '通风可散去有毒气体。', 'easy', '安全常识', '["安全常识","化学品安全"]', NOW(), NOW()),
(5, 64, 'single_choice', '吃火锅时，酒精炉添加酒精应？A. 在燃烧时直接加 B. 灭火冷却后再加 C. 加满 D. 泼洒', '["B"]', '直接倒酒精会引起火焰喷溅伤人。', 'easy', '安全常识', '["安全常识","厨房安全"]', NOW(), NOW()),
(5, 65, 'single_choice', '以下哪个是安全用电行为？A. 湿手插拔插头 B. 电器不用时拔掉插头 C. 用湿布擦拭通电的电风扇 D. 电线乱拉乱接', '["B"]', '拔掉插头可消除待机耗电和安全风险。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 66, 'single_choice', '遇到诈骗电话要求转账，应？A. 立即转账 B. 挂断并报警核实 C. 按指示操作 D. 提供验证码', '["B"]', '不听不信不转账，立即报警。', 'easy', '安全常识', '["安全常识","网络安全"]', NOW(), NOW()),
(5, 67, 'single_choice', '燃气灶具的使用年限一般是？A. 3年 B. 8年 C. 15年 D. 无限制', '["B"]', '燃气灶具使用寿命一般为8年。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 68, 'single_choice', '骨折伤员搬运前，应？A. 立刻背起 B. 先固定伤处，避免移动 C. 按摩 D. 热敷', '["B"]', '固定可防止二次损伤。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 69, 'single_choice', '使用剪刀等锐器传递时，应？A. 刀尖朝自己，手柄朝向对方 B. 直接扔 C. 刀尖朝对方 D. 抛过去', '["A"]', '刀尖朝自己可防止误伤他人。', 'easy', '安全常识', '["安全常识","日常安全"]', NOW(), NOW()),
(5, 70, 'single_choice', '以下哪项是易燃液体？A. 水 B. 汽油 C. 醋 D. 盐水', '["B"]', '汽油闪点低，极易燃烧。', 'easy', '安全常识', '["安全常识","危险品"]', NOW(), NOW()),
(5, 71, 'single_choice', '被蜜蜂蜇伤后，应？A. 挤压伤口 B. 用镊子拔刺，肥皂水清洗 C. 涂抹风油精 D. 热敷', '["B"]', '拔刺后清洗可中和蜂毒。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 72, 'single_choice', '出现不明气体臭味，怀疑燃气泄漏，以下不能做的是？A. 开窗 B. 关闭阀门 C. 按门铃或打电话 D. 离开', '["C"]', '电器开关和电话可能产生电火花引爆燃气。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 73, 'single_choice', '机动车儿童安全座椅应安装在？A. 副驾驶位 B. 后排座位 C. 后备箱 D. 车顶', '["B"]', '后排座位最安全，副驾驶有气囊风险。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 74, 'single_choice', '以下哪项属于高处作业的安全要求？A. 不系安全带 B. 戴安全帽系安全绳，下方设防护网 C. 穿拖鞋 D. 酒后作业', '["B"]', '安全带和防护网是高处作业必备。', 'easy', '安全常识', '["安全常识","作业安全"]', NOW(), NOW()),
(5, 75, 'single_choice', '洪水来临时，来不及转移应？A. 爬到屋顶或大树高处等待救援 B. 游泳逃生 C. 钻进车内 D. 跳入水中', '["A"]', '高处躲避可争取救援时间。', 'easy', '安全常识', '["安全常识","自然灾害"]', NOW(), NOW()),
(5, 76, 'single_choice', '火场中浓烟较大，应尽量？A. 直立奔跑 B. 弯腰低姿匍匐前进 C. 大声喊叫 D. 坐电梯', '["B"]', '贴近地面的空气更清洁。', 'easy', '安全常识', '["安全常识","火灾逃生"]', NOW(), NOW()),
(5, 77, 'single_choice', '使用电暖器时，应远离？A. 窗帘、床单等可燃物 B. 墙壁 C. 瓷砖 D. 水泥地', '["A"]', '电暖器高温易引燃可燃物。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 78, 'single_choice', '发现液化气罐着火，应先？A. 用水泼 B. 用湿布盖住火苗并关闭阀门 C. 把罐踢倒 D. 报警', '["B"]', '先灭火再关阀最安全。', 'medium', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 79, 'single_choice', '游泳前的热身主要目的是？A. 减肥 B. 防止抽筋 C. 提高速度 D. 美观', '["B"]', '热身可防止入水后抽筋。', 'easy', '安全常识', '["安全常识","运动安全"]', NOW(), NOW()),
(5, 80, 'single_choice', '长期不用的电器，应？A. 保持待机 B. 拔掉插头 C. 盖布 D. 放冰箱', '["B"]', '拔掉插头可消除待机耗电和安全隐患。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(5, 81, 'single_choice', '以下哪个是食品安全的正确做法？A. 生熟砧板分开使用 B. 食物掉地捡起继续吃 C. 冰箱食物存放不分层 D. 过期食品试吃后决定', '["A"]', '生熟分开可防止交叉污染。', 'easy', '安全常识', '["安全常识","食品安全"]', NOW(), NOW()),
(5, 82, 'single_choice', '电动自行车充电时间过长可能导致？A. 省电 B. 电池过热起火 C. 跑更远 D. 正常', '["B"]', '过充会导致电池热失控起火。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 83, 'single_choice', '危险化学品容器上骷髅头标志表示？A. 腐蚀 B. 有毒 C. 易燃 D. 辐射', '["B"]', '骷髅头表示该物质有毒。', 'easy', '安全常识', '["安全常识","安全标志"]', NOW(), NOW()),
(5, 84, 'single_choice', '突发心脏病患者，意识模糊，应？A. 立刻扶起喂水 B. 让其平躺，解开衣领，拨打120并取急救药 C. 不停摇晃 D. 掐人中', '["B"]', '平躺并保持呼吸道通畅是关键。', 'medium', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 85, 'single_choice', '以下哪种行为能防范网络诈骗？A. 点击不明链接 B. 不透露验证码和密码 C. 扫陌生二维码 D. 相信中奖信息', '["B"]', '保护个人信息是防诈骗的关键。', 'easy', '安全常识', '["安全常识","网络安全"]', NOW(), NOW()),
(5, 86, 'single_choice', '大雾天开车应？A. 开远光灯 B. 开雾灯和危险报警灯，减速慢行 C. 加速超车 D. 关闭所有灯', '["B"]', '雾灯穿透力强，减速保安全。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 87, 'single_choice', '使用壁挂炉时，压力表指针低于多少需补水？A. 3.0 bar B. 1.0 bar以下 C. 2.5 bar D. 4.0 bar', '["B"]', '低于1.0bar时需补水维持正常压力。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 88, 'single_choice', '遇到绑架危险，以下错误的是？A. 激怒歹徒 B. 找机会留下线索或逃跑 C. 记住特征 D. 保持冷静周旋', '["A"]', '激怒歹徒可能危及生命。', 'easy', '安全常识', '["安全常识","人身安全"]', NOW(), NOW()),
(5, 89, 'single_choice', '老人或小孩噎食不能发声时，应使用？A. 拍背 B. 海姆立克腹部冲击法 C. 喝水 D. 等待', '["B"]', '海姆立克法是解除气道阻塞的标准方法。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 90, 'single_choice', '干粉灭火器可用于扑救哪类火灾？A. 带电设备、油类、可燃固体 B. 金属火灾 C. 精密仪器 D. 碱金属', '["A"]', '干粉灭火器适用A、B、C类火灾。', 'easy', '安全常识', '["安全常识","消防器材"]', NOW(), NOW()),
(5, 91, 'single_choice', '燃气软管建议多久更换一次？A. 每1-2年 B. 5年 C. 10年 D. 不坏不换', '["A"]', '软管老化易泄漏，应定期更换。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 92, 'single_choice', '乘坐飞机时，安全须知卡应？A. 不看 B. 仔细阅读并确认最近出口 C. 扔掉 D. 收藏', '["B"]', '熟悉安全出口位置，以备紧急情况。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 93, 'single_choice', '被困在车内时，可敲击车窗的哪个部位？A. 玻璃中心 B. 玻璃边缘四角 C. 任何位置 D. 敲不碎', '["B"]', '四角是最脆弱的部位，易敲碎。', 'easy', '安全常识', '["安全常识","自救知识"]', NOW(), NOW()),
(5, 94, 'single_choice', '以下哪个不是地震避险的“活命三角区”？A. 坚固家具旁 B. 承重墙墙角 C. 窗户下方 D. 立柱旁边', '["C"]', '窗户下方是危险区域，玻璃易碎。', 'easy', '安全常识', '["安全常识","地震避险"]', NOW(), NOW()),
(5, 95, 'single_choice', '使用酒精消毒时，应注意？A. 大面积喷洒后点火 B. 远离火源，通风使用 C. 在灶台旁使用 D. 吸烟时使用', '["B"]', '酒精易燃，必须远离明火。', 'easy', '安全常识', '["安全常识","化学品安全"]', NOW(), NOW()),
(5, 96, 'single_choice', '发现野生蘑菇，应？A. 采回家吃 B. 不采不食 C. 给动物试吃 D. 晒干', '["B"]', '毒蘑菇无法靠外观辨别，不采不食最安全。', 'easy', '安全常识', '["安全常识","食品安全"]', NOW(), NOW()),
(5, 97, 'single_choice', '遇到抢劫时，首要原则是？A. 拼命反抗 B. 确保人身安全，舍财保命 C. 记住车牌 D. 呼叫', '["B"]', '生命安全高于财产安全。', 'easy', '安全常识', '["安全常识","人身安全"]', NOW(), NOW()),
(5, 98, 'single_choice', '以下哪种情况不适合使用创可贴？A. 小而浅的伤口 B. 被生锈铁钉扎的深伤口 C. 手指划伤 D. 擦伤', '["B"]', '深窄伤口应就医，创可贴可能加重感染。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 99, 'single_choice', '安全电压36V适用于什么环境？A. 潮湿环境 B. 干燥环境 C. 水下 D. 高温', '["B"]', '潮湿环境下安全电压更低（12V）。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 100, 'single_choice', '搬动重物时，保护腰部的正确姿势是？A. 弯腰搬起 B. 屈膝下蹲，保持腰背挺直，靠腿部力量 C. 扭腰搬 D. 单手搬', '["B"]', '腿部发力可保护腰椎。', 'easy', '安全常识', '["安全常识","日常安全"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(5, 101, 'fill_blank', '我国火警电话号码是______。', '["119"]', '119是全国统一火警电话。', 'easy', '安全常识', '["安全常识","消防知识"]', NOW(), NOW()),
(5, 102, 'fill_blank', '使用灭火器扑救火灾时，应对准火焰的______喷射。', '["根部"]', '对准火焰根部才能有效灭火。', 'easy', '安全常识', '["安全常识","消防器材"]', NOW(), NOW()),
(5, 103, 'fill_blank', '燃气泄漏时，绝对不能开关任何______或使用电话。', '["电器（或电气设备）"]', '电器开关可能产生电火花。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 104, 'fill_blank', '心肺复苏中，胸外按压与人工呼吸的比例为______（单人）。', '["30:2"]', '单人施救时按压30次吹气2次。', 'hard', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 105, 'fill_blank', '发现有人触电，应使用______等绝缘物分离电线。', '["干燥木棍或塑料棒"]', '绝缘物可防止施救者触电。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 106, 'fill_blank', '高层建筑火灾逃生时，不可乘坐______。', '["电梯"]', '火灾时电梯可能断电或成为烟囱。', 'easy', '安全常识', '["安全常识","火灾逃生"]', NOW(), NOW()),
(5, 107, 'fill_blank', '海姆立克急救法操作时，拳眼对准患者______与肚脐之间。', '["剑突（或上腹部）"]', '正确位置是脐上两指处。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 108, 'fill_blank', '安全使用电器，应避免多个大功率电器共用同一个______。', '["插线板或插座"]', '过载会导致发热起火。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 109, 'fill_blank', '油锅起火盖上锅盖后，还需关闭______。', '["燃气阀门"]', '关闭气源防止复燃。', 'easy', '安全常识', '["安全常识","厨房安全"]', NOW(), NOW()),
(5, 110, 'fill_blank', '烫伤后不可涂抹牙膏、酱油等，应______。', '["冲冷水"]', '涂抹牙膏会加重伤情，应先降温。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 111, 'fill_blank', '电热毯的使用寿命一般为______年。', '["6"]', '超过6年应更换，防止老化起火。', 'easy', '安全常识', '["安全常识","家电安全"]', NOW(), NOW()),
(5, 112, 'fill_blank', '汽车内避免放置打火机、香水等，因高温可能______。', '["爆炸或自燃"]', '高温下这些物品易爆燃。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 113, 'fill_blank', '防烟面罩使用时，需拔掉前后两个______。', '["密封塞"]', '拔掉塞子才能正常呼吸。', 'easy', '安全常识', '["安全常识","消防器材"]', NOW(), NOW()),
(5, 114, 'fill_blank', '雷雨天气，不宜在______下避雨。', '["大树"]', '大树易遭雷击。', 'easy', '安全常识', '["安全常识","防雷安全"]', NOW(), NOW()),
(5, 115, 'fill_blank', '冰箱应远离______等热源，留出散热空间。', '["灶台或暖气"]', '靠近热源会增加耗电和故障风险。', 'easy', '安全常识', '["安全常识","家电安全"]', NOW(), NOW()),
(5, 116, 'fill_blank', '发现煤气中毒者，应将其移至______处。', '["空气流通（或新鲜空气）"]', '新鲜空气可缓解中毒症状。', 'easy', '安全常识', '["安全常识","燃气安全"]', NOW(), NOW()),
(5, 117, 'fill_blank', '机动车行驶中，驾驶员和乘客都应系好______。', '["安全带"]', '安全带可大幅降低伤亡率。', 'easy', '安全常识', '["安全常识","交通安全"]', NOW(), NOW()),
(5, 118, 'fill_blank', '安全帽的下颏带必须系紧，防止______。', '["脱落"]', '带不紧则帽易脱落，失去保护。', 'easy', '安全常识', '["安全常识","作业安全"]', NOW(), NOW()),
(5, 119, 'fill_blank', '社区消防通道应保持______。', '["畅通（或不得占用）"]', '堵塞消防通道违法且危害公共安全。', 'easy', '安全常识', '["安全常识","消防知识"]', NOW(), NOW()),
(5, 120, 'fill_blank', '使用梯子时，梯子与地面的夹角约为______度。', '["75"]', '75度角最稳定安全。', 'easy', '安全常识', '["安全常识","作业安全"]', NOW(), NOW()),
(5, 121, 'fill_blank', '被动物咬伤后，应在______小时内注射狂犬疫苗。', '["24"]', '越早注射效果越好。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 122, 'fill_blank', '火灾中浓烟主要危害是______和有毒气体。', '["缺氧"]', '浓烟会导致缺氧窒息和中毒。', 'easy', '安全常识', '["安全常识","火灾逃生"]', NOW(), NOW()),
(5, 123, 'fill_blank', '电动自行车严禁在______充电。', '["室内或楼道"]', '室内充电火灾风险极高。', 'easy', '安全常识', '["安全常识","用电安全"]', NOW(), NOW()),
(5, 124, 'fill_blank', '化学品进入眼睛，应立即用______冲洗至少15分钟。', '["清水"]', '大量清水冲洗是最佳急救措施。', 'easy', '安全常识', '["安全常识","急救知识"]', NOW(), NOW()),
(5, 125, 'fill_blank', '地震时如果在室外，应远离______、高压线等。', '["建筑物"]', '建筑物倒塌是室外主要危险源。', 'easy', '安全常识', '["安全常识","地震避险"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(6, 1, 'single_choice', '炒菜时，热锅冷油的主要好处是什么？A. 省油 B. 防止粘锅，减少油烟 C. 更健康 D. 菜熟得快', '["B"]', '热锅冷油可减少粘锅和油烟产生。', 'easy', '烹饪基础', '["烹饪基础","炒菜技巧"]', NOW(), NOW()),
(6, 2, 'single_choice', '以下哪种方法能有效去除鱼肉的腥味？A. 多加盐 B. 用料酒、姜片腌制 C. 长时间炖煮 D. 加醋', '["B"]', '料酒和姜可有效去腥。', 'easy', '烹饪基础', '["烹饪基础","去腥技巧"]', NOW(), NOW()),
(6, 3, 'single_choice', '煮面条时，怎样防止面条粘连？A. 加冷水 B. 水中加少量盐和油，煮开后加凉水 C. 一直大火 D. 盖盖子煮', '["B"]', '加盐油可使面条不易粘连。', 'easy', '烹饪基础', '["烹饪基础","面食制作"]', NOW(), NOW()),
(6, 4, 'single_choice', '炒青菜时，为保持翠绿，应？A. 盖盖子焖煮 B. 大火快炒，出锅前放盐 C. 小火慢炒 D. 加酱油', '["B"]', '大火快炒可保持叶绿素不分解。', 'easy', '烹饪基础', '["烹饪基础","蔬菜烹饪"]', NOW(), NOW()),
(6, 5, 'single_choice', '煮米饭时，米和水的体积比大约是多少？A. 1:1 B. 1:1.2至1:1.5 C. 1:2 D. 1:3', '["B"]', '米水比1:1.2-1.5煮出的米饭软硬适中。', 'easy', '烹饪基础', '["烹饪基础","主食制作"]', NOW(), NOW()),
(6, 6, 'single_choice', '焯烫蔬菜时，加入少量油和盐的作用是？A. 调味 B. 保持色泽和减少营养流失 C. 去农药 D. 增加口感', '["B"]', '油盐可锁色锁营养。', 'easy', '烹饪基础', '["烹饪基础","焯水技巧"]', NOW(), NOW()),
(6, 7, 'single_choice', '煎鱼时怎样防止鱼皮粘锅？A. 鱼身不擦干 B. 锅不烧热就下油 C. 鱼身拍干淀粉，油热后下锅，不急着翻动 D. 加大量水', '["C"]', '拍淀粉和热油可使鱼皮酥脆不粘。', 'easy', '烹饪基础', '["烹饪基础","煎制技巧"]', NOW(), NOW()),
(6, 8, 'single_choice', '以下哪种肉类需要焯水去血沫？A. 新鲜牛排 B. 排骨或冷冻肉 C. 刺身 D. 火腿', '["B"]', '排骨焯水可去血沫去腥。', 'easy', '烹饪基础', '["烹饪基础","肉类处理"]', NOW(), NOW()),
(6, 9, 'single_choice', '勾芡用的淀粉水，通常比例是？A. 1份淀粉10份水 B. 1份淀粉2-3份水 C. 淀粉和水的比例1:1 D. 纯淀粉', '["B"]', '1:2-3的淀粉水勾芡效果最佳。', 'easy', '烹饪基础', '["烹饪基础","勾芡技巧"]', NOW(), NOW()),
(6, 10, 'single_choice', '烘焙中，低筋面粉最适合做什么？A. 面包 B. 蛋糕和饼干 C. 面条 D. 披萨饼底', '["B"]', '低筋面粉筋度低，适合松软糕点。', 'easy', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 11, 'single_choice', '煮鸡蛋时，怎样容易剥壳？A. 冷水下锅，煮好后立即放入冰水 B. 开水下锅煮15分钟 C. 加碱 D. 煮前摇匀', '["A"]', '冰水急冷可使蛋膜收缩易剥。', 'easy', '烹饪基础', '["烹饪基础","蛋类烹饪"]', NOW(), NOW()),
(6, 12, 'single_choice', '以下哪种油适合高温油炸？A. 橄榄油（初榨） B. 大豆油或精炼菜籽油 C. 芝麻油 D. 黄油', '["B"]', '大豆油菜籽油烟点高，适合油炸。', 'easy', '烹饪基础', '["烹饪基础","用油知识"]', NOW(), NOW()),
(6, 13, 'single_choice', '炖肉时，中途加水应加？A. 冷水 B. 热水或开水 C. 冰水 D. 加汤', '["B"]', '加热水可防止肉质紧缩变老。', 'easy', '烹饪基础', '["烹饪基础","炖煮技巧"]', NOW(), NOW()),
(6, 14, 'single_choice', '切洋葱时怎样避免流泪？A. 戴隐形眼镜 B. 刀沾水或冷藏后再切 C. 闭上眼睛切 D. 加醋', '["B"]', '低温可减少刺激性气体挥发。', 'easy', '烹饪基础', '["烹饪基础","刀工技巧"]', NOW(), NOW()),
(6, 15, 'single_choice', '制作凉拌菜时，为何最后放油？A. 更入味 B. 防止出水，锁住味道 C. 减少油腻 D. 好看', '["B"]', '油可包裹食材，防止出水。', 'easy', '烹饪基础', '["烹饪基础","凉拌技巧"]', NOW(), NOW()),
(6, 16, 'single_choice', '以下哪种是发酵面粉常用的膨松剂？A. 小苏打 B. 酵母 C. 泡打粉 D. 碱面', '["B"]', '酵母是生物发酵剂，产生气体使面团膨胀。', 'easy', '烹饪基础', '["烹饪基础","面点制作"]', NOW(), NOW()),
(6, 17, 'single_choice', '煮粥时怎样防止溢锅？A. 加食用油 B. 加冷水 C. 锅盖留缝或加几滴油 D. 始终大火', '["C"]', '油可降低表面张力，防溢锅。', 'easy', '烹饪基础', '["烹饪基础","粥品制作"]', NOW(), NOW()),
(6, 18, 'single_choice', '以下哪种刀法适合切肉丝？A. 直切 B. 顺纹切 C. 逆纹切（切断纤维） D. 剁', '["C"]', '逆纹切可切断肌肉纤维，使肉嫩。', 'easy', '烹饪基础', '["烹饪基础","刀工技巧"]', NOW(), NOW()),
(6, 19, 'single_choice', '蒸鱼时，盘底垫葱姜的作用是？A. 防粘和去腥 B. 装饰 C. 增加重量 D. 保鲜', '["A"]', '葱姜可去腥增香，垫底防粘。', 'easy', '烹饪基础', '["烹饪基础","蒸菜技巧"]', NOW(), NOW()),
(6, 20, 'single_choice', '炸花生米怎样才酥脆不回潮？A. 冷油下锅，小火炸，出锅喷少许白酒 B. 热油下锅 C. 水煮后炸 D. 加糖', '["A"]', '冷油小火炸得酥脆，白酒助挥发防回潮。', 'medium', '烹饪基础', '["烹饪基础","油炸技巧"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(6, 21, 'single_choice', '烘焙中，黄油软化是指？A. 融化液态 B. 室温软化至牙膏状 C. 冷冻 D. 加热沸腾', '["B"]', '软化黄油便于打发和混合。', 'easy', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 22, 'single_choice', '煮汤太咸，可以如何补救？A. 加糖 B. 加水或加土豆块吸盐 C. 加醋 D. 加酱油', '["B"]', '土豆可吸盐，加水稀释最直接。', 'easy', '烹饪基础', '["烹饪基础","汤品制作"]', NOW(), NOW()),
(6, 23, 'single_choice', '以下哪种烹饪方式营养保留最好？A. 油炸 B. 长时间炖煮 C. 快速蒸或白灼 D. 烧烤', '["C"]', '快速蒸煮可最大限度保留营养。', 'easy', '烹饪基础', '["烹饪基础","健康烹饪"]', NOW(), NOW()),
(6, 24, 'single_choice', '糖醋菜中，糖醋汁的常用比例是？A. 无固定，按口味 B. 糖:醋=1:1 或 5:4 C. 糖多醋少 D. 醋多糖少', '["B"]', '1:1是最经典的糖醋比例。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 25, 'single_choice', '使用不粘锅时，应避免？A. 硅胶铲 B. 木铲 C. 金属铲 D. 竹铲', '["C"]', '金属铲会刮伤不粘涂层。', 'easy', '烹饪基础', '["烹饪基础","厨具使用"]', NOW(), NOW()),
(6, 26, 'single_choice', '炒肉丝想要嫩滑，需先做什么？A. 加淀粉和少许油抓匀腌制 B. 直接下锅 C. 焯水 D. 冷冻', '["A"]', '淀粉上浆可锁住水分，使肉嫩滑。', 'easy', '烹饪基础', '["烹饪基础","肉类处理"]', NOW(), NOW()),
(6, 27, 'single_choice', '煮水饺时，点冷水的目的是？A. 防粘 B. 使皮更筋道，防止破皮 C. 加快熟 D. 调味', '["B"]', '点冷水可使皮紧实不破。', 'easy', '烹饪基础', '["烹饪基础","面食制作"]', NOW(), NOW()),
(6, 28, 'single_choice', '以下是健康的烹饪用油选择？A. 反复使用的油 B. 棕榈油 C. 富含单不饱和脂肪酸的橄榄油 D. 猪油', '["C"]', '橄榄油富含健康的不饱和脂肪酸。', 'easy', '烹饪基础', '["烹饪基础","用油知识"]', NOW(), NOW()),
(6, 29, 'single_choice', '烧烤时，防止食物烧焦的方法是？A. 大火快速烤 B. 勤翻动，刷油，控制火候 C. 远离火源 D. 加厚涂层', '["B"]', '勤翻动可均匀受热防止烧焦。', 'easy', '烹饪基础', '["烹饪基础","烧烤技巧"]', NOW(), NOW()),
(6, 30, 'single_choice', '熬糖色（炒糖色）用水熬还是油熬？A. 只能用水 B. 只能用油 C. 油水混合或油熬后加水 D. 干炒', '["C"]', '油水混合法最易掌握。', 'medium', '烹饪基础', '["烹饪基础","调色技巧"]', NOW(), NOW()),
(6, 31, 'single_choice', '以下哪种食材不适合长时间浸泡？A. 木耳 B. 干香菇 C. 大米 D. 切好的土豆丝', '["D"]', '土豆丝泡久会流失淀粉和营养。', 'easy', '烹饪基础', '["烹饪基础","食材处理"]', NOW(), NOW()),
(6, 32, 'single_choice', '做蛋糕时，蛋白打发的最佳温度是？A. 常温 B. 冷藏低温（易打发细腻） C. 加热 D. 冷冻', '["B"]', '冷藏蛋白打发更稳定细腻。', 'medium', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 33, 'single_choice', '炒土豆丝前，用清水浸泡的作用是？A. 去淀粉防粘锅 B. 更脆 C. 去异味 D. 以上都是', '["D"]', '浸泡可去淀粉、防粘、保持脆度。', 'easy', '烹饪基础', '["烹饪基础","蔬菜处理"]', NOW(), NOW()),
(6, 34, 'single_choice', '以下哪种情况表示油温已达七成热（约180-210度）？A. 油面平静 B. 筷子插入冒大量气泡，有青烟 C. 轻微波动 D. 无反应', '["B"]', '大量气泡和青烟是七成热的标志。', 'medium', '烹饪基础', '["烹饪基础","油温判断"]', NOW(), NOW()),
(6, 35, 'single_choice', '煮牛奶时，怎样防止糊底？A. 大火煮 B. 小火并搅拌或隔水加热 C. 加糖 D. 加盖', '["B"]', '小火搅拌可防止牛奶糊底。', 'easy', '烹饪基础', '["烹饪基础","奶制品烹饪"]', NOW(), NOW()),
(6, 36, 'single_choice', '做鱼汤想要汤白，应？A. 加牛奶 B. 先煎鱼再加热水大火煮 C. 冷水煮 D. 加豆腐', '["B"]', '煎鱼后大火煮可使脂肪乳化变白。', 'medium', '烹饪基础', '["烹饪基础","汤品制作"]', NOW(), NOW()),
(6, 37, 'single_choice', '以下哪种是中式烹饪“五香”常见组合？A. 花椒、八角、桂皮、丁香、小茴香 B. 辣椒、姜、蒜 C. 香叶、胡椒 D. 陈皮、甘草', '["A"]', '五香粉由这五种香料组成。', 'easy', '烹饪基础', '["烹饪基础","香料知识"]', NOW(), NOW()),
(6, 38, 'single_choice', '制作饺子馅时，怎样不出水？A. 菜切碎直接拌肉 B. 菜先焯水挤干，肉馅打水，最后加油锁水 C. 加大量盐 D. 加酱油', '["B"]', '先挤干菜再加油可锁住水分。', 'medium', '烹饪基础', '["烹饪基础","馅料制作"]', NOW(), NOW()),
(6, 39, 'single_choice', '以下哪种是制作面包必须用的原料？A. 泡打粉 B. 高筋面粉和酵母 C. 低筋面粉 D. 玉米淀粉', '["B"]', '高筋面粉提供面筋，酵母负责发酵。', 'easy', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 40, 'single_choice', '烹饪叶菜类蔬菜时，应？A. 提前切好放置 B. 先洗后切，急火快炒 C. 先切后洗 D. 加水焖煮', '["B"]', '先洗后切可减少营养流失。', 'easy', '烹饪基础', '["烹饪基础","蔬菜烹饪"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(6, 41, 'single_choice', '判断油温三四成热（约90-120度）适合？A. 炸酥肉 B. 滑肉丝、滑鸡丁 C. 炸花生米 D. 炸鱼', '["B"]', '低温油适合滑炒嫩肉。', 'medium', '烹饪基础', '["烹饪基础","油温判断"]', NOW(), NOW()),
(6, 42, 'single_choice', '以下哪种是去皮的西红柿更容易出汁的方法？A. 冷冻 B. 开水烫后去皮，切碎炒 C. 生吃 D. 榨汁', '["B"]', '去皮后炒更容易出汁。', 'easy', '烹饪基础', '["烹饪基础","食材处理"]', NOW(), NOW()),
(6, 43, 'single_choice', '蒸鸡蛋羹时，怎样使表面光滑无蜂窝？A. 加冷水 B. 加温水，过筛，盖保鲜膜，小火蒸 C. 大火蒸 D. 加盐', '["B"]', '过筛和盖膜可防蜂窝。', 'medium', '烹饪基础', '["烹饪基础","蛋类烹饪"]', NOW(), NOW()),
(6, 44, 'single_choice', '以下哪种食材含有天然毒素，必须煮熟？A. 西红柿 B. 四季豆（豆角） C. 黄瓜 D. 生菜', '["B"]', '四季豆含皂苷和血球凝集素，必须煮熟。', 'easy', '烹饪基础', '["烹饪基础","食品安全"]', NOW(), NOW()),
(6, 45, 'single_choice', '炒饭用以下哪种米饭最好？A. 刚煮好的热饭 B. 隔夜冷藏米饭 C. 稀饭 D. 糯米饭', '["B"]', '隔夜米饭水分少，粒粒分明。', 'easy', '烹饪基础', '["烹饪基础","主食制作"]', NOW(), NOW()),
(6, 46, 'single_choice', '制作红烧肉时，炒糖色的目的是？A. 上色和增香 B. 去腥 C. 提鲜 D. 解腻', '["A"]', '糖色可使肉色红亮且增加焦香味。', 'easy', '烹饪基础', '["烹饪基础","调色技巧"]', NOW(), NOW()),
(6, 47, 'single_choice', '以下哪种刀适合切面包？A. 中式菜刀 B. 锯齿刀 C. 削皮刀 D. 砍骨刀', '["B"]', '锯齿刀可切面包不掉渣。', 'easy', '烹饪基础', '["烹饪基础","刀工技巧"]', NOW(), NOW()),
(6, 48, 'single_choice', '煮绿豆汤怎样快速煮烂？A. 加碱 B. 提前冷冻后再煮 C. 加盐 D. 小火慢炖', '["B"]', '冷冻使豆子细胞壁破裂，易煮烂。', 'easy', '烹饪基础', '["烹饪基础","豆类烹饪"]', NOW(), NOW()),
(6, 49, 'single_choice', '调味时，味精或鸡精的最佳加入时机是？A. 油温最高时 B. 出锅前 C. 下锅时 D. 浸泡时', '["B"]', '出锅前加可防止高温分解失效。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 50, 'single_choice', '以下哪种烹饪方法用油最少？A. 炸 B. 煎 C. 蒸和煮 D. 煸', '["C"]', '蒸和煮几乎不需要用油。', 'easy', '烹饪基础', '["烹饪基础","健康烹饪"]', NOW(), NOW()),
(6, 51, 'single_choice', '熬骨头汤时，第一次加水应？A. 加冷水，中途不加水 B. 加热水 C. 加开水 D. 任意', '["A"]', '冷水下锅可充分熬出营养。', 'easy', '烹饪基础', '["烹饪基础","汤品制作"]', NOW(), NOW()),
(6, 52, 'single_choice', '制作西餐酱汁常用“roux”（油面酱）是指？A. 黄油炒面粉 B. 奶油加淀粉 C. 蛋黄酱 D. 番茄酱', '["A"]', '油面酱是西餐酱汁的基础。', 'medium', '烹饪基础', '["烹饪基础","西餐基础"]', NOW(), NOW()),
(6, 53, 'single_choice', '以下哪种腌肉方法能让肉更嫩？A. 加小苏打（少量） B. 加醋 C. 加碱 D. 加盐', '["A"]', '小苏打可破坏肌肉纤维，使肉嫩化。', 'medium', '烹饪基础', '["烹饪基础","肉类处理"]', NOW(), NOW()),
(6, 54, 'single_choice', '煎牛排前，牛排需要？A. 水洗 B. 室温回温，吸干表面水分 C. 冷冻状态直接煎 D. 加大量水', '["B"]', '回温并吸干水分可使牛排更好上色。', 'easy', '烹饪基础', '["烹饪基础","煎制技巧"]', NOW(), NOW()),
(6, 55, 'single_choice', '以下哪种是“醒面”的作用？A. 使面团更松弛易擀开 B. 杀菌 C. 发酵 D. 上色', '["A"]', '醒面可使面筋松弛，便于整形。', 'easy', '烹饪基础', '["烹饪基础","面点制作"]', NOW(), NOW()),
(6, 56, 'single_choice', '制作披萨时，奶酪拉丝效果最好的是？A. 切达奶酪 B. 马苏里拉奶酪 C. 奶油奶酪 D. 蓝纹奶酪', '["B"]', '马苏里拉奶酪加热后拉丝效果最佳。', 'easy', '烹饪基础', '["烹饪基础","西餐基础"]', NOW(), NOW()),
(6, 57, 'single_choice', '炒菜时，盐放早了会导致？A. 菜变咸 B. 蔬菜出水，口感不脆 C. 更入味 D. 变色', '["B"]', '早放盐会使蔬菜水分渗出，口感变软。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 58, 'single_choice', '以下哪种食用油烟点最高，适合爆炒？A. 亚麻籽油 B. 初榨橄榄油 C. 牛油果油或精炼菜籽油 D. 核桃油', '["C"]', '牛油果油烟点高，超过250度。', 'medium', '烹饪基础', '["烹饪基础","用油知识"]', NOW(), NOW()),
(6, 59, 'single_choice', '做红烧鱼时，加入醋的作用是？A. 调味 B. 去腥解腻，软化骨刺 C. 上色 D. 防腐', '["B"]', '醋可去腥并软化鱼骨。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 60, 'single_choice', '煮意面时，水中加盐的比例约为？A. 10升水加1克盐 B. 1升水加7-10克盐 C. 不加盐 D. 加糖', '["B"]', '加盐可使意面更弹牙有味道。', 'easy', '烹饪基础', '["烹饪基础","面食制作"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(6, 61, 'single_choice', '以下哪种是制作凉皮洗面的原理？A. 去除面筋留下淀粉 B. 去除淀粉留下面筋 C. 发酵 D. 糊化', '["A"]', '洗面可分离面筋和淀粉水。', 'medium', '烹饪基础', '["烹饪基础","面食制作"]', NOW(), NOW()),
(6, 62, 'single_choice', '炒鸡蛋想要嫩滑，可在蛋液中加入？A. 水或牛奶 B. 碱 C. 醋 D. 油', '["A"]', '加水可使鸡蛋更嫩滑。', 'easy', '烹饪基础', '["烹饪基础","蛋类烹饪"]', NOW(), NOW()),
(6, 63, 'single_choice', '以下哪种食材不宜空腹吃？A. 苹果 B. 香蕉 C. 柿子（含鞣酸） D. 面包', '["C"]', '柿子空腹吃易形成胃结石。', 'easy', '烹饪基础', '["烹饪基础","食品安全"]', NOW(), NOW()),
(6, 64, 'single_choice', '做寿司饭时，米饭拌入的料是？A. 糖和醋 B. 盐和油 C. 酱油 D. 芥末', '["A"]', '寿司醋是糖醋混合调味。', 'easy', '烹饪基础', '["烹饪基础","主食制作"]', NOW(), NOW()),
(6, 65, 'single_choice', '炸鸡翅想要外脆里嫩，通常需要？A. 裹干粉后复炸 B. 单次油炸 C. 水煮后炸 D. 不裹粉', '["A"]', '复炸可使外皮更酥脆。', 'easy', '烹饪基础', '["烹饪基础","油炸技巧"]', NOW(), NOW()),
(6, 66, 'single_choice', '以下哪种烹饪术语是“切成细丝”？A. 块 B. 片 C. 丝 D. 丁', '["C"]', '丝是细长的切法。', 'easy', '烹饪基础', '["烹饪基础","刀工技巧"]', NOW(), NOW()),
(6, 67, 'single_choice', '红烧菜肴中，老抽的主要作用是？A. 提鲜 B. 上色 C. 增咸 D. 去腥', '["B"]', '老抽颜色深，主要用于上色。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 68, 'single_choice', '制作奶油打发时，淡奶油的脂肪含量需在？A. 10% B. 20% C. 35%以上 D. 5%', '["C"]', '脂肪含量35%以上的淡奶油才好打发。', 'medium', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 69, 'single_choice', '以下哪种是制作泡菜必须的微生物发酵过程？A. 霉菌 B. 酵母菌 C. 乳酸菌 D. 醋酸菌', '["C"]', '乳酸菌发酵产生酸味，抑制杂菌。', 'easy', '烹饪基础', '["烹饪基础","发酵食品"]', NOW(), NOW()),
(6, 70, 'single_choice', '煮汤圆时，怎样判断熟透？A. 浮起后煮1-2分钟 B. 沉底 C. 变大 D. 变色', '["A"]', '汤圆浮起后仍需煮1-2分钟确保熟透。', 'easy', '烹饪基础', '["烹饪基础","面食制作"]', NOW(), NOW()),
(6, 71, 'single_choice', '炒茄子怎样省油？A. 切后撒盐腌制出水挤干 B. 多放油 C. 加水煮 D. 裹面糊', '["A"]', '盐腌可破坏海绵结构，减少吸油。', 'easy', '烹饪基础', '["烹饪基础","蔬菜烹饪"]', NOW(), NOW()),
(6, 72, 'single_choice', '以下哪种烘焙工具是测量面粉重量的？A. 量杯 B. 厨房秤 C. 量勺 D. 计时器', '["B"]', '烘焙建议用厨房秤精确称量。', 'easy', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 73, 'single_choice', '煮牛肉怎样易烂？A. 加盐早 B. 加茶叶或山楂 C. 一直小火 D. 加醋', '["B"]', '茶叶和山楂中的酸性物质可软化肉质。', 'easy', '烹饪基础', '["烹饪基础","肉类烹饪"]', NOW(), NOW()),
(6, 74, 'single_choice', '以下哪种是制作蛋黄酱（美乃滋）的关键步骤？A. 油慢慢滴入并不断搅拌 B. 蛋清打发 C. 加热 D. 冷冻', '["A"]', '缓慢加油并搅拌使油水乳化。', 'medium', '烹饪基础', '["烹饪基础","酱汁制作"]', NOW(), NOW()),
(6, 75, 'single_choice', '烹饪贝类海鲜前，应？A. 用盐水浸泡吐沙 B. 直接下锅 C. 开水烫 D. 冷冻', '["A"]', '盐水浸泡可让贝类吐净泥沙。', 'easy', '烹饪基础', '["烹饪基础","海鲜处理"]', NOW(), NOW()),
(6, 76, 'single_choice', '以下哪种调味品不适合高温长时间加热？A. 盐 B. 蚝油、味精 C. 酱油 D. 糖', '["B"]', '蚝油味精高温久煮会失去鲜味。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 77, 'single_choice', '制作戚风蛋糕时，为什么不能使用不粘模具？A. 不利于面糊爬升 B. 容易糊 C. 难脱模 D. 有毒', '["A"]', '不粘模具会使蛋糕无法攀爬长高。', 'medium', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 78, 'single_choice', '以下哪种是“水油焖”蔬菜的方法？A. 先放水再加油 B. 少量油加水，盖盖焖煮 C. 大量水煮 D. 油炸', '["B"]', '水油焖是健康省油的烹饪方式。', 'easy', '烹饪基础', '["烹饪基础","蔬菜烹饪"]', NOW(), NOW()),
(6, 79, 'single_choice', '烹制羊肉时，去膻常用的香料是？A. 花椒和白芷 B. 八角 C. 香叶 D. 桂皮', '["A"]', '花椒和白芷是去膻的有效香料。', 'medium', '烹饪基础', '["烹饪基础","香料知识"]', NOW(), NOW()),
(6, 80, 'single_choice', '以下哪种是煮粥前浸泡大米的作用？A. 缩短煮制时间，更软糯 B. 去淀粉 C. 增加营养 D. 去杂质', '["A"]', '浸泡使米吸水，煮粥更软糯省时。', 'easy', '烹饪基础', '["烹饪基础","粥品制作"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(6, 81, 'single_choice', '烘焙中，隔水加热法常用于？A. 烤面包 B. 融化巧克力和芝士 C. 烤饼干 D. 发酵', '["B"]', '隔水加热可温和融化，防止焦糊。', 'easy', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 82, 'single_choice', '以下哪种刀法切出的土豆片是菱形片？A. 滚刀切 B. 先斜刀切段再竖切 C. 直切 D. 剁', '["B"]', '斜刀切段后再竖切可得菱形片。', 'medium', '烹饪基础', '["烹饪基础","刀工技巧"]', NOW(), NOW()),
(6, 83, 'single_choice', '煮西米露时，西米中心有白点怎么办？A. 关火焖至透明 B. 继续大火煮 C. 捞出 D. 加冷水', '["A"]', '关火利用余温焖至透明。', 'easy', '烹饪基础', '["烹饪基础","甜品制作"]', NOW(), NOW()),
(6, 84, 'single_choice', '以下哪种是制作酥皮点心的起酥原理？A. 水油皮包裹油酥，多次折叠 B. 加泡打粉 C. 加酵母 D. 长时间揉面', '["A"]', '水油皮和油酥交替折叠形成层次。', 'hard', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 85, 'single_choice', '炒菜时，料酒的主要作用是？A. 增香去腥 B. 上色 C. 增甜 D. 杀菌', '["A"]', '料酒去腥增香，高温挥发带走异味。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 86, 'single_choice', '以下哪种肉类需要全熟食用，不能带生？A. 牛排 B. 鸡肉和猪肉 C. 三文鱼 D. 金枪鱼', '["B"]', '鸡肉和猪肉可能携带致病菌和寄生虫。', 'easy', '烹饪基础', '["烹饪基础","食品安全"]', NOW(), NOW()),
(6, 87, 'single_choice', '制作豆腐脑时，凝固剂常用的有？A. 石膏或内酯 B. 碱面 C. 盐 D. 醋', '["A"]', '石膏和内酯是常见的豆腐凝固剂。', 'easy', '烹饪基础', '["烹饪基础","豆制品制作"]', NOW(), NOW()),
(6, 88, 'single_choice', '烹饪意大利面的“al dente”意思是？A. 软烂 B. 弹牙有嚼劲 C. 很硬 D. 糊状', '["B"]', 'al dente是意面的最佳口感状态。', 'easy', '烹饪基础', '["烹饪基础","面食制作"]', NOW(), NOW()),
(6, 89, 'single_choice', '以下哪种是正确清洗葡萄的方法？A. 摘粒洗 B. 剪刀剪下留蒂，加面粉或淀粉浸泡 C. 用力搓 D. 只冲水', '["B"]', '留蒂加面粉浸泡可洗净农残。', 'easy', '烹饪基础', '["烹饪基础","水果处理"]', NOW(), NOW()),
(6, 90, 'single_choice', '制作面食时，“三光”是指？A. 面光、手光、盆光 B. 桌光、锅光、灶光 C. 色光、味光、形光 D. 油光、水光、火光', '["A"]', '三光是和面完成的标志。', 'easy', '烹饪基础', '["烹饪基础","面点制作"]', NOW(), NOW()),
(6, 91, 'single_choice', '煮咖啡时，水温一般控制在？A. 100度 B. 90-96度 C. 80度以下 D. 70度', '["B"]', '90-96度是萃取咖啡的最佳水温。', 'easy', '烹饪基础', '["烹饪基础","饮品制作"]', NOW(), NOW()),
(6, 92, 'single_choice', '以下哪种是对肉类“断筋”处理的常用工具？A. 肉锤 B. 菜刀 C. 剪刀 D. 叉子', '["A"]', '肉锤可锤断肉筋，使肉质更嫩。', 'easy', '烹饪基础', '["烹饪基础","肉类处理"]', NOW(), NOW()),
(6, 93, 'single_choice', '蒸包子时，关火后应？A. 立即开盖 B. 焖3-5分钟再开盖防塌陷 C. 开盖浇水 D. 继续加热', '["B"]', '焖几分钟可防止包子回缩塌陷。', 'easy', '烹饪基础', '["烹饪基础","面点制作"]', NOW(), NOW()),
(6, 94, 'single_choice', '以下哪种是法式高汤的基础蔬菜（mirepoix）？A. 洋葱、胡萝卜、西芹 B. 番茄、土豆、茄子 C. 青椒、大蒜、姜 D. 白菜、萝卜', '["A"]', 'mirepoix是法式高汤的经典底料。', 'medium', '烹饪基础', '["烹饪基础","西餐基础"]', NOW(), NOW()),
(6, 95, 'single_choice', '炒花生米前，最好将花生米？A. 泡水 B. 用水冲洗沥干，冷油下锅 C. 油炸 D. 冷冻', '["B"]', '冷油下锅可内外受热均匀。', 'easy', '烹饪基础', '["烹饪基础","油炸技巧"]', NOW(), NOW()),
(6, 96, 'single_choice', '以下哪种是制作珍珠奶茶中珍珠（波霸）的主要原料？A. 木薯淀粉 B. 小麦粉 C. 玉米淀粉 D. 土豆淀粉', '["A"]', '木薯淀粉是珍珠Q弹口感的来源。', 'easy', '烹饪基础', '["烹饪基础","饮品制作"]', NOW(), NOW()),
(6, 97, 'single_choice', '炖鸡汤时，为了汤清澈，应？A. 大火滚 B. 小火慢炖，撇去浮沫 C. 加冷水 D. 加醋', '["B"]', '小火慢炖并撇沫可使汤清。', 'easy', '烹饪基础', '["烹饪基础","汤品制作"]', NOW(), NOW()),
(6, 98, 'single_choice', '以下哪种是判断蛋糕烤熟的方法？A. 插入牙签拔出无湿面糊 B. 表面金黄 C. 香味出来 D. 时间到', '["A"]', '牙签测试是判断蛋糕熟度的最准确方法。', 'easy', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 99, 'single_choice', '炒菜时，最后放入蒜末葱花的目的是？A. 出香味不焦糊 B. 消毒 C. 调味 D. 美观', '["A"]', '后放蒜葱可避免焦糊，保持香味。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 100, 'single_choice', '以下哪种方式可快速解冻肉类？A. 热水浸泡 B. 微波炉解冻功能或冷藏室慢解 C. 常温放置 D. 油炸', '["B"]', '微波炉解冻最快，冷藏解冻最安全。', 'easy', '烹饪基础', '["烹饪基础","食材处理"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(6, 101, 'fill_blank', '中式烹饪中，“炝锅”通常使用______和姜蒜爆香。', '["葱花"]', '葱花姜蒜是炝锅的基础料。', 'easy', '烹饪基础', '["烹饪基础","调味技巧"]', NOW(), NOW()),
(6, 102, 'fill_blank', '煮饺子时，水中加______可以防止破皮。', '["盐"]', '盐可增强面皮筋性。', 'easy', '烹饪基础', '["烹饪基础","面食制作"]', NOW(), NOW()),
(6, 103, 'fill_blank', '鉴别油温五六成热（约150-180度）时，油面有______。', '["轻微波动和少量青烟"]', '五成热油面波动，六成热开始冒青烟。', 'medium', '烹饪基础', '["烹饪基础","油温判断"]', NOW(), NOW()),
(6, 104, 'fill_blank', '制作面食时，加入______可以使面团更筋道。', '["盐（或鸡蛋）"]', '盐和鸡蛋可增加面筋强度。', 'easy', '烹饪基础', '["烹饪基础","面点制作"]', NOW(), NOW()),
(6, 105, 'fill_blank', '糖色炒过头会变______并发苦。', '["黑"]', '糖色焦化变黑且产生苦味。', 'easy', '烹饪基础', '["烹饪基础","调色技巧"]', NOW(), NOW()),
(6, 106, 'fill_blank', '炖肉时，加入少许______可以加速肉质软烂。', '["醋或山楂"]', '酸可软化结缔组织。', 'easy', '烹饪基础', '["烹饪基础","肉类烹饪"]', NOW(), NOW()),
(6, 107, 'fill_blank', '焯烫绿叶菜时，水中加______可以保持绿色。', '["油和盐"]', '油盐可防止叶绿素氧化。', 'easy', '烹饪基础', '["烹饪基础","焯水技巧"]', NOW(), NOW()),
(6, 108, 'fill_blank', '切完辣椒手辣，可用______涂抹缓解。', '["酒精或食用油"]', '辣椒素溶于酒精和油脂。', 'easy', '烹饪基础', '["烹饪基础","食材处理"]', NOW(), NOW()),
(6, 109, 'fill_blank', '烘焙中，小苏打和酸性物质（如酸奶）反应产生______。', '["二氧化碳"]', '酸碱反应产气使糕点膨胀。', 'medium', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 110, 'fill_blank', '制作蛋挞液时，蛋和牛奶的比例一般为______。', '["1:2到1:3"]', '蛋奶比适中可使蛋挞嫩滑。', 'easy', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 111, 'fill_blank', '处理鱿鱼时，需要撕掉表面的______。', '["黑膜"]', '黑膜是腥味的主要来源。', 'easy', '烹饪基础', '["烹饪基础","海鲜处理"]', NOW(), NOW()),
(6, 112, 'fill_blank', '蒸海鲜的时间不宜过长，否则肉质会______。', '["变老变硬"]', '海鲜过火会失去嫩滑口感。', 'easy', '烹饪基础', '["烹饪基础","蒸菜技巧"]', NOW(), NOW()),
(6, 113, 'fill_blank', '煮豆子时，中途加______会使豆子变硬不易烂。', '["糖或盐"]', '糖和盐会使豆子渗透压改变变硬。', 'easy', '烹饪基础', '["烹饪基础","豆类烹饪"]', NOW(), NOW()),
(6, 114, 'fill_blank', '使用高压锅时，排气阀______后才能开盖。', '["完全泄压"]', '完全泄压后才安全开盖。', 'easy', '烹饪基础', '["烹饪基础","厨具使用"]', NOW(), NOW()),
(6, 115, 'fill_blank', '做沙拉时，生菜洗净后需______才能保持爽脆。', '["沥干或甩干水分"]', '水分残留会使生菜变软。', 'easy', '烹饪基础', '["烹饪基础","凉拌技巧"]', NOW(), NOW()),
(6, 116, 'fill_blank', '制作糯米藕时，糯米要填入藕的______中。', '["孔洞"]', '糯米填入藕孔才成型。', 'easy', '烹饪基础', '["烹饪基础","甜品制作"]', NOW(), NOW()),
(6, 117, 'fill_blank', '豆腐焯水可以去除______味。', '["豆腥"]', '焯水可去除豆腥味。', 'easy', '烹饪基础', '["烹饪基础","豆制品处理"]', NOW(), NOW()),
(6, 118, 'fill_blank', '制作曲奇饼干时，黄油和糖粉需______至颜色发白。', '["打发"]', '打发使黄油充入空气，饼干酥脆。', 'easy', '烹饪基础', '["烹饪基础","烘焙"]', NOW(), NOW()),
(6, 119, 'fill_blank', '切熟食和生食的砧板要______。', '["分开使用"]', '生熟分开防止交叉污染。', 'easy', '烹饪基础', '["烹饪基础","食品安全"]', NOW(), NOW()),
(6, 120, 'fill_blank', '煮鸡蛋时，水开后煮______分钟可得到溏心蛋。', '["6-7"]', '6-7分钟是溏心蛋的最佳时间。', 'easy', '烹饪基础', '["烹饪基础","蛋类烹饪"]', NOW(), NOW()),
(6, 121, 'fill_blank', '发面时，最适宜的温度是______摄氏度。', '["28-35"]', '28-35度是酵母最活跃的温度。', 'easy', '烹饪基础', '["烹饪基础","面点制作"]', NOW(), NOW()),
(6, 122, 'fill_blank', '制作可乐鸡翅时，可乐和酱油的比例大约为______。', '["3:1"]', '可乐酱油3:1味道最佳。', 'easy', '烹饪基础', '["烹饪基础","肉类烹饪"]', NOW(), NOW()),
(6, 123, 'fill_blank', '勾芡分为包芡、糊芡和______。', '["流芡或薄芡"]', '薄芡是稀薄透明的芡汁。', 'medium', '烹饪基础', '["烹饪基础","勾芡技巧"]', NOW(), NOW()),
(6, 124, 'fill_blank', '烤红薯时，烤箱温度设为______摄氏度左右。', '["200-220"]', '200-220度可烤出香甜红薯。', 'easy', '烹饪基础', '["烹饪基础","烘烤技巧"]', NOW(), NOW()),
(6, 125, 'fill_blank', '西餐中，切开牛排流出的红色汁水主要是______。', '["肌红蛋白"]', '红色汁水不是血，是肌红蛋白。', 'easy', '烹饪基础', '["烹饪基础","肉类烹饪"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(7, 1, 'single_choice', '衣物标签上的洗涤标志“30度水洗加一横”表示什么？A. 30度水温正常洗 B. 30度温和洗涤，减少机械力 C. 不可水洗 D. 干洗', '["B"]', '加一横表示温和洗涤程序。', 'medium', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 2, 'single_choice', '羊毛衫最好用什么方式清洗？A. 机洗强力模式 B. 手洗或洗衣机羊毛/轻柔模式，使用羊毛专用洗涤剂 C. 热水泡洗 D. 干洗店', '["B"]', '羊毛衫娇贵，需轻柔洗涤。', 'easy', '衣服护理', '["衣服护理","羊毛衫护理"]', NOW(), NOW()),
(7, 3, 'single_choice', '白色棉质T恤发黄，以下哪种方法可改善？A. 漂白水浸泡 B. 小苏打或白醋浸泡后暴晒 C. 烘干 D. 熨烫', '["B"]', '小苏打和白醋可去除黄渍。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 4, 'single_choice', '以下哪种衣物不适合用烘干机烘干？A. 纯棉毛巾 B. 羊毛衫和丝绸 C. 牛仔裤 D. 床单', '["B"]', '羊毛和丝绸高温烘干会缩水变形。', 'easy', '衣服护理', '["衣服护理","烘干技巧"]', NOW(), NOW()),
(7, 5, 'single_choice', '去除衣服上的口香糖，正确方法是？A. 用水洗 B. 冷冻硬化后刮除 C. 用热水烫 D. 用刷子刷', '["B"]', '冷冻使口香糖变脆易刮除。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 6, 'single_choice', '熨烫西装时，最好使用？A. 直接高温熨烫 B. 垫一块湿布或使用挂烫机，低温熨烫 C. 不用熨烫 D. 蒸汽大开', '["B"]', '西装需低温垫布熨烫，避免发亮。', 'medium', '衣服护理', '["衣服护理","熨烫技巧"]', NOW(), NOW()),
(7, 7, 'single_choice', '真丝衣物洗涤时应使用？A. 碱性洗衣粉 B. 中性或酸性丝绸专用洗涤剂，冷水手洗 C. 热水搓洗 D. 机洗', '["B"]', '真丝怕碱怕高温，需中性冷水手洗。', 'easy', '衣服护理', '["衣服护理","真丝护理"]', NOW(), NOW()),
(7, 8, 'single_choice', '以下哪种污渍不能用热水洗？A. 油渍 B. 血渍（蛋白质类） C. 泥土 D. 灰尘', '["B"]', '热水会使蛋白质凝固，更难去除。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 9, 'single_choice', '羽绒服机洗后羽绒结块，应如何处理？A. 再次机洗 B. 晾干后轻轻拍打或烘干机加网球拍打 C. 直接穿 D. 熨烫', '["B"]', '拍打可使羽绒恢复蓬松。', 'easy', '衣服护理', '["衣服护理","羽绒服护理"]', NOW(), NOW()),
(7, 10, 'single_choice', '衣服晾晒时，以下哪种做法容易使衣物变形？A. 用宽肩衣架挂毛衣 B. 用细铁丝衣架挂湿毛衣 C. 平铺晾晒羊毛衫 D. 用夹子夹裤腰', '["B"]', '细衣架挂湿毛衣会使肩膀变形。', 'easy', '衣服护理', '["衣服护理","晾晒技巧"]', NOW(), NOW()),
(7, 11, 'single_choice', '去除衣服上的铁锈渍，可用？A. 草酸或柠檬酸溶液 B. 漂白水 C. 酒精 D. 汽油', '["A"]', '草酸可与铁锈反应溶解。', 'medium', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 12, 'single_choice', '牛仔裤第一次洗涤，最好？A. 热水洗 B. 冷水加盐浸泡固色 C. 干洗 D. 烘干', '["B"]', '盐可帮助固色，减少褪色。', 'easy', '衣服护理', '["衣服护理","牛仔裤护理"]', NOW(), NOW()),
(7, 13, 'single_choice', '以下哪种面料最容易起球？A. 纯棉 B. 涤纶和羊毛混纺 C. 真丝 D. 亚麻', '["B"]', '化纤与羊毛混纺最易起球。', 'easy', '衣服护理', '["衣服护理","面料知识"]', NOW(), NOW()),
(7, 14, 'single_choice', '衣服标签上的三角形内带叉标志表示？A. 可用漂白剂 B. 不可用氯漂白剂 C. 可干洗 D. 不可熨烫', '["B"]', '三角形带叉表示不可氯漂。', 'easy', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 15, 'single_choice', '去除衣服上的油渍，可应急使用？A. 洗洁精涂抹后搓洗 B. 水冲洗 C. 酒精 D. 香水', '["A"]', '洗洁精可乳化油脂，快速去油。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 16, 'single_choice', '以下哪种是正确存放皮衣的方法？A. 折叠存放 B. 用宽衣架悬挂，通风处，避免暴晒 C. 套塑料袋密封 D. 放樟脑丸直接接触', '["B"]', '皮衣需悬挂通风，避免折叠和暴晒。', 'easy', '衣服护理', '["衣服护理","皮衣护理"]', NOW(), NOW()),
(7, 17, 'single_choice', '衣物柔顺剂的主要作用是？A. 去污 B. 中和洗涤剂残留，使衣物柔软抗静电 C. 漂白 D. 杀菌', '["B"]', '柔顺剂使衣物柔软并减少静电。', 'easy', '衣服护理', '["衣服护理","洗涤用品"]', NOW(), NOW()),
(7, 18, 'single_choice', '以下哪种做法可以防止黑色裤子褪色？A. 每次都用热水洗 B. 翻面洗，用冷水，阴干 C. 暴晒 D. 加漂白水', '["B"]', '翻面冷水洗可减少褪色和摩擦。', 'easy', '衣服护理', '["衣服护理","防褪色技巧"]', NOW(), NOW()),
(7, 19, 'single_choice', '衬衫领口的汗渍黄斑，可用？A. 牙膏或小苏打糊刷洗 B. 漂白水 C. 酒精 D. 汽油', '["A"]', '牙膏和小苏打可温和去黄。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 20, 'single_choice', '羊绒围巾起球，应如何处理？A. 用手拔掉 B. 使用毛球修剪器轻轻修剪 C. 用胶带粘 D. 不用管', '["B"]', '毛球修剪器可修剪而不伤纤维。', 'easy', '衣服护理', '["衣服护理","羊绒护理"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(7, 21, 'single_choice', '以下哪种衣物不能拧干？A. 牛仔裤 B. 真丝和羊毛衫 C. 棉T恤 D. 毛巾', '["B"]', '拧干会使真丝羊毛变形损坏。', 'easy', '衣服护理', '["衣服护理","洗涤技巧"]', NOW(), NOW()),
(7, 22, 'single_choice', '去除衣服上的咖啡渍，应先用？A. 热水 B. 冷水或甘油处理 C. 酒精 D. 醋', '["B"]', '冷水或甘油可防止咖啡渍扩散。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 23, 'single_choice', '干洗和水洗的主要区别是？A. 干洗不用水，使用有机溶剂 B. 干洗更伤衣物 C. 水洗只能手洗 D. 干洗便宜', '["A"]', '干洗使用化学溶剂清洗。', 'easy', '衣服护理', '["衣服护理","干洗知识"]', NOW(), NOW()),
(7, 24, 'single_choice', '以下哪种方法可让白衬衫更白？A. 淘米水浸泡 B. 蓝墨水一滴泡水 C. 柠檬汁浸泡 D. 以上都可以', '["D"]', '淘米水、蓝墨水、柠檬汁都有增白效果。', 'easy', '衣服护理', '["衣服护理","增白技巧"]', NOW(), NOW()),
(7, 25, 'single_choice', '衣物标签上圆形带叉标志表示？A. 可干洗 B. 不可干洗 C. 可熨烫 D. 不可水洗', '["B"]', '圆形带叉表示不可干洗。', 'easy', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 26, 'single_choice', '毛衣袖口变松，如何恢复？A. 热水浸泡 B. 用皮筋扎住松紧处，蒸汽熨烫或吹风机热风 C. 剪掉 D. 不用管', '["B"]', '热风可使弹性纤维收缩恢复。', 'medium', '衣服护理', '["衣服护理","毛衣护理"]', NOW(), NOW()),
(7, 27, 'single_choice', '去除衣服上的口红印，可用？A. 酒精或发胶喷涂后擦拭 B. 水洗 C. 醋 D. 肥皂', '["A"]', '酒精可溶解口红油脂。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 28, 'single_choice', '以下哪种面料不能暴晒？A. 涤纶 B. 真丝、羊毛、深色棉布 C. 腈纶 D. 尼龙', '["B"]', '真丝羊毛暴晒会褪色变脆。', 'easy', '衣服护理', '["衣服护理","晾晒技巧"]', NOW(), NOW()),
(7, 29, 'single_choice', '洗衣机洗内衣时，最好？A. 与其他衣服混洗 B. 使用内衣洗衣袋，单独洗 C. 手洗 D. 干洗', '["B"]', '洗衣袋可保护内衣不变形。', 'easy', '衣服护理', '["衣服护理","内衣护理"]', NOW(), NOW()),
(7, 30, 'single_choice', '去除衣服上的墨水渍（圆珠笔），可用？A. 酒精或风油精涂抹 B. 水洗 C. 肥皂 D. 洗衣粉', '["A"]', '酒精可溶解圆珠笔墨水。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 31, 'single_choice', '以下哪种是正确存放羽绒服的方法？A. 真空压缩袋长期压缩 B. 宽松悬挂或折叠，保持蓬松 C. 重物压底 D. 潮湿环境', '["B"]', '长期压缩会破坏羽绒蓬松度。', 'easy', '衣服护理', '["衣服护理","羽绒服护理"]', NOW(), NOW()),
(7, 32, 'single_choice', '衣服标签上的熨烫标志“点三个点”表示？A. 低温熨烫 B. 中温熨烫 C. 高温熨烫 D. 不可熨烫', '["C"]', '三点表示最高温熨烫。', 'easy', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 33, 'single_choice', '去除衣服上的草渍，可用？A. 酒精 B. 白醋 C. 盐水 D. 洗衣液', '["A"]', '酒精可分解草渍色素。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 34, 'single_choice', '深色和浅色衣服一起洗涤会导致？A. 串色染色 B. 更干净 C. 节省水 D. 杀菌', '["A"]', '深色褪色会染浅色衣物。', 'easy', '衣服护理', '["衣服护理","洗涤技巧"]', NOW(), NOW()),
(7, 35, 'single_choice', '以下哪种洗衣产品用于去除特殊污渍（如血、奶）？A. 加酶洗衣粉 B. 柔顺剂 C. 漂白水 D. 香皂', '["A"]', '蛋白酶可分解蛋白质污渍。', 'easy', '衣服护理', '["衣服护理","洗涤用品"]', NOW(), NOW()),
(7, 36, 'single_choice', '皮衣表面有轻微霉斑，应？A. 用水擦 B. 用酒精或皮革清洁剂擦拭后通风 C. 暴晒 D. 涂油', '["B"]', '酒精可杀霉，通风干燥防再发。', 'medium', '衣服护理', '["衣服护理","皮衣护理"]', NOW(), NOW()),
(7, 37, 'single_choice', '衣服起静电，可以怎样快速消除？A. 喷水雾或用金属衣架划过 B. 加柔顺剂 C. 暴晒 D. 烘干', '["A"]', '水分和金属可导走静电。', 'easy', '衣服护理', '["衣服护理","静电处理"]', NOW(), NOW()),
(7, 38, 'single_choice', '以下哪种是正确洗涤带装饰珠片的衣服？A. 机洗 B. 翻面放入洗衣袋，手洗或轻柔机洗 C. 干洗 D. 大力搓洗', '["B"]', '翻面加洗衣袋可保护珠片。', 'easy', '衣服护理', '["衣服护理","特殊衣物护理"]', NOW(), NOW()),
(7, 39, 'single_choice', '去除衣服上的指甲油，可用？A. 洗甲水（丙酮）注意不伤面料 B. 水 C. 酒精 D. 汽油', '["A"]', '洗甲水可溶解指甲油。', 'medium', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 40, 'single_choice', '棉麻衣物洗涤后容易皱，最好？A. 带湿晾干拉伸 B. 烘干后直接穿 C. 甩干后不展开 D. 拧干', '["A"]', '带湿晾干时可拉伸平整。', 'easy', '衣服护理', '["衣服护理","棉麻护理"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(7, 41, 'single_choice', '衣服上的泥点，应？A. 干后刷掉再洗 B. 湿时搓洗 C. 热水烫 D. 漂白', '["A"]', '干后刷掉可避免泥渍晕开。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 42, 'single_choice', '以下哪种面料不能使用含氯漂白剂？A. 白色纯棉 B. 彩色棉、羊毛、丝绸 C. 白色涤纶 D. 白色亚麻', '["B"]', '氯漂会破坏彩色和蛋白质纤维。', 'easy', '衣服护理', '["衣服护理","漂白技巧"]', NOW(), NOW()),
(7, 43, 'single_choice', '袜子和其他衣物同洗，应？A. 直接混洗 B. 使用消毒液或分开洗 C. 不用特别处理 D. 高温洗', '["B"]', '袜子易带真菌，建议分开加消毒液。', 'easy', '衣服护理', '["衣服护理","洗涤技巧"]', NOW(), NOW()),
(7, 44, 'single_choice', '去除衣服上的油漆（水性），可用？A. 酒精或肥皂水 B. 汽油 C. 香蕉水 D. 洗洁精', '["A"]', '水性漆可用酒精或肥皂水去除。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 45, 'single_choice', '旗袍等真丝刺绣品，最佳护理方式是？A. 机洗 B. 手洗或干洗，避免搓揉刺绣部位 C. 烘干 D. 暴晒', '["B"]', '刺绣部位需特别保护。', 'easy', '衣服护理', '["衣服护理","真丝护理"]', NOW(), NOW()),
(7, 46, 'single_choice', '衣服标签上的“不可翻转干燥”标志是？A. 正方形内圆带叉 B. 正方形内圆加一点 C. 圆形 D. 三角形', '["A"]', '正方形内圆带叉表示不可烘干。', 'easy', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 47, 'single_choice', '以下哪种方法可去除衣服上的汗味？A. 白醋水浸泡 B. 香水遮盖 C. 加热 D. 烘干', '["A"]', '白醋可中和碱性汗渍并杀菌。', 'easy', '衣服护理', '["衣服护理","去味技巧"]', NOW(), NOW()),
(7, 48, 'single_choice', '羊毛衫晾晒时，应？A. 悬挂晾晒 B. 平铺晾晒，防止拉长 C. 烘干 D. 暴晒', '["B"]', '平铺晾晒可防止羊毛衫变形拉长。', 'easy', '衣服护理', '["衣服护理","羊毛衫护理"]', NOW(), NOW()),
(7, 49, 'single_choice', '去除衣服上的口香糖残留，冷冻后可用？A. 酒精擦拭 B. 刀片刮 C. 胶带粘 D. 以上都可', '["D"]', '多种方法可去除残留。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 50, 'single_choice', '以下哪种是正确保存领带的方法？A. 折叠放抽屉 B. 悬挂或卷起放入专用格 C. 塞口袋 D. 暴晒', '["B"]', '悬挂或卷起可保持领带平整。', 'easy', '衣服护理', '["衣服护理","领带护理"]', NOW(), NOW()),
(7, 51, 'single_choice', '衣物洗涤时，水温过高会导致？A. 去污更强 B. 缩水、褪色、蛋白质污渍凝固 C. 更省电 D. 杀菌彻底', '["B"]', '高温会损伤衣物。', 'easy', '衣服护理', '["衣服护理","洗涤技巧"]', NOW(), NOW()),
(7, 52, 'single_choice', '去除衣服上的蜡油，可用？A. 纸巾覆盖熨烫吸融 B. 水洗 C. 酒精 D. 洗洁精', '["A"]', '加热可使蜡油融化被纸巾吸收。', 'medium', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 53, 'single_choice', '以下哪种面料极易缩水？A. 涤纶 B. 未经预缩处理的纯棉和羊毛 C. 尼龙 D. 氨纶', '["B"]', '天然纤维未经预缩易缩水。', 'easy', '衣服护理', '["衣服护理","面料知识"]', NOW(), NOW()),
(7, 54, 'single_choice', '衣服上的荧光增白剂残留，可在漂洗时加？A. 白醋 B. 小苏打 C. 洗衣液 D. 柔顺剂', '["A"]', '白醋可中和残留。', 'easy', '衣服护理', '["衣服护理","漂洗技巧"]', NOW(), NOW()),
(7, 55, 'single_choice', '牛仔布褪色属于正常现象，如何延缓？A. 少洗，冷水洗，翻面洗 B. 加盐和醋固色 C. 阴干 D. 以上都是', '["D"]', '综合护理可延缓褪色。', 'easy', '衣服护理', '["衣服护理","牛仔裤护理"]', NOW(), NOW()),
(7, 56, 'single_choice', '去除衣服上的番茄酱渍，应先用？A. 冷水刮除残渣，再用洗涤剂 B. 热水 C. 酒精 D. 汽油', '["A"]', '先刮除再洗效果更好。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 57, 'single_choice', '以下哪种衣架最适合挂厚重的大衣？A. 细铁丝衣架 B. 宽肩木质或塑料衣架 C. 塑料夹子 D. 裤架', '["B"]', '宽肩衣架可保持大衣肩部形状。', 'easy', '衣服护理', '["衣服护理","衣架选择"]', NOW(), NOW()),
(7, 58, 'single_choice', '衣服标签上的洗涤温度标志“60”表示？A. 最高60度洗涤 B. 必须60度 C. 不可超过60度 D. 60度以下都行', '["A"]', '60是最高洗涤温度限制。', 'easy', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 59, 'single_choice', '去除衣服上的果汁渍，可用？A. 盐水搓洗后热水洗 B. 白醋 C. 漂白水 D. 酒精', '["A"]', '盐水可防止果汁扩散。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 60, 'single_choice', '以下哪种是正确护理泳衣的方法？A. 每次用后用清水冲洗，阴干 B. 机洗甩干 C. 暴晒消毒 D. 烘干', '["A"]', '清水冲洗可去除氯和盐分。', 'easy', '衣服护理', '["衣服护理","泳衣护理"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(7, 61, 'single_choice', '衣服上的锈渍去除后，应？A. 充分漂洗，避免草酸残留伤纤维 B. 直接穿 C. 熨烫 D. 暴晒', '["A"]', '草酸残留会损伤纤维。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 62, 'single_choice', '以下哪种材质衣物不宜长时间浸泡？A. 棉 B. 羊毛（易缩水毡化） C. 涤纶 D. 锦纶', '["B"]', '羊毛长时间浸泡会毡化缩水。', 'easy', '衣服护理', '["衣服护理","羊毛护理"]', NOW(), NOW()),
(7, 63, 'single_choice', '雪纺（聚酯纤维）衣物洗涤时注意？A. 可高温熨烫 B. 轻柔手洗或机洗，低温熨烫 C. 拧干 D. 暴晒', '["B"]', '雪纺怕高温，需低温熨烫。', 'easy', '衣服护理', '["衣服护理","雪纺护理"]', NOW(), NOW()),
(7, 64, 'single_choice', '去除衣服上的茶渍，可用？A. 甘油和蛋黄混合液 B. 白醋 C. 酒精 D. 汽油', '["A"]', '甘油和蛋黄可分解茶渍。', 'medium', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 65, 'single_choice', '以下哪种是正确存放帽子（棒球帽）的方法？A. 折叠压箱 B. 填充物支撑形状，悬挂或平放 C. 暴晒 D. 潮湿环境', '["B"]', '填充可保持帽型不变。', 'easy', '衣服护理', '["衣服护理","帽子护理"]', NOW(), NOW()),
(7, 66, 'single_choice', '绒面革（翻毛皮）鞋面脏了，应？A. 用水刷 B. 用专用橡皮擦或软毛刷 C. 鞋油 D. 酒精', '["B"]', '专用橡皮擦可清洁绒面不伤皮质。', 'medium', '衣服护理', '["衣服护理","鞋类护理"]', NOW(), NOW()),
(7, 67, 'single_choice', '以下哪种洗衣方法可减少衣物掉毛？A. 加半杯白醋到漂洗水 B. 热水洗 C. 长时间浸泡 D. 烘干', '["A"]', '白醋可软化水质，减少掉毛。', 'easy', '衣服护理', '["衣服护理","洗涤技巧"]', NOW(), NOW()),
(7, 68, 'single_choice', '衣服上的化妆品粉底渍，可用？A. 卸妆油或洗洁精预处理 B. 水洗 C. 酒精 D. 汽油', '["A"]', '卸妆油可溶解粉底。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 69, 'single_choice', '新内衣穿前最好？A. 直接穿 B. 洗涤一次去除甲醛和染料浮色 C. 熨烫 D. 暴晒', '["B"]', '洗涤可去除化学残留。', 'easy', '衣服护理', '["衣服护理","内衣护理"]', NOW(), NOW()),
(7, 70, 'single_choice', '去除衣服上的巧克力渍，应用？A. 冷水浸泡，洗涤剂搓 B. 热水 C. 酒精 D. 汽油', '["A"]', '冷水可防止巧克力融化渗入纤维。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 71, 'single_choice', '以下哪种面料干洗比水洗更安全？A. 纯棉衬衫 B. 羊毛西装和真丝礼服 C. 牛仔裤 D. 涤纶外套', '["B"]', '羊毛和真丝水洗易缩水变形。', 'easy', '衣服护理', '["衣服护理","干洗知识"]', NOW(), NOW()),
(7, 72, 'single_choice', '衣服上的抽丝（勾丝），应？A. 剪断 B. 用针或钩针从反面拉回 C. 胶水粘 D. 不用管', '["B"]', '从反面拉回可修复抽丝。', 'medium', '衣服护理', '["衣服护理","修补技巧"]', NOW(), NOW()),
(7, 73, 'single_choice', '去除衣服上的药膏渍，可用？A. 酒精或甘油 B. 水 C. 醋 D. 洗衣粉', '["A"]', '酒精可溶解药膏油性成分。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 74, 'single_choice', '以下哪种是正确清洗运动服（速干面料）的方法？A. 使用柔顺剂 B. 不用柔顺剂，清水冲洗，阴干 C. 高温烘干 D. 暴晒', '["B"]', '柔顺剂会堵塞速干面料纤维孔。', 'easy', '衣服护理', '["衣服护理","运动服护理"]', NOW(), NOW()),
(7, 75, 'single_choice', '衣服存放时使用樟脑丸，应注意？A. 直接接触衣物 B. 用纸包好挂在衣柜上方，避免直接接触丝绸和羊毛 C. 越多越好 D. 放在衣服口袋', '["B"]', '直接接触会损伤丝绸羊毛。', 'easy', '衣服护理', '["衣服护理","衣物存放"]', NOW(), NOW()),
(7, 76, 'single_choice', '去除衣服上的记号笔墨水，可用？A. 酒精或洗手液 B. 水 C. 醋 D. 洗衣粉', '["A"]', '酒精可溶解记号笔墨水。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 77, 'single_choice', '以下哪种是正确保存婚纱的方法？A. 压缩袋 B. 避光、防潮，用棉布套悬挂或平放，避免氧化变黄 C. 叠放 D. 暴晒', '["B"]', '婚纱需避光防潮保存。', 'easy', '衣服护理', '["衣服护理","婚纱护理"]', NOW(), NOW()),
(7, 78, 'single_choice', '衣服标签上的圆圈内字母“P”表示？A. 可用任何干洗溶剂 B. 可使用四氯乙烯和所有溶剂 C. 仅可使用石油类溶剂 D. 不可干洗', '["B"]', 'P表示可使用四氯乙烯干洗。', 'medium', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 79, 'single_choice', '去除衣服上的黄油或油脂，可用？A. 玉米淀粉吸收后刷掉再洗 B. 水洗 C. 酒精 D. 醋', '["A"]', '玉米淀粉可吸收油脂。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 80, 'single_choice', '领带清洗后，应？A. 悬挂晾干 B. 平铺晾干，避免变形 C. 烘干 D. 拧干', '["B"]', '平铺可保持领带形状。', 'easy', '衣服护理', '["衣服护理","领带护理"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(7, 81, 'single_choice', '以下哪种是正确洗涤渔夫毛衣（厚重羊毛）的方法？A. 机洗 B. 冷水手洗，挤压水分，平铺晾干 C. 热水洗 D. 烘干', '["B"]', '厚重羊毛需冷水手洗，不可拧绞。', 'easy', '衣服护理', '["衣服护理","羊毛护理"]', NOW(), NOW()),
(7, 82, 'single_choice', '去除衣服上的胶水（白乳胶），可用？A. 温水浸泡 B. 酒精 C. 汽油 D. 洗洁精', '["A"]', '温水可使白乳胶软化脱落。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 83, 'single_choice', '衣服上的尿渍（婴儿），应？A. 冷水浸泡，加酶洗涤剂 B. 热水 C. 酒精 D. 漂白水', '["A"]', '冷水可防止蛋白质凝固。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 84, 'single_choice', '以下哪种材质衣物最怕虫蛀？A. 化纤 B. 纯毛和羊毛 C. 棉 D. 麻', '["B"]', '羊毛含有蛋白质，是虫蛀目标。', 'easy', '衣服护理', '["衣服护理","防虫技巧"]', NOW(), NOW()),
(7, 85, 'single_choice', '去除衣服上的烟熏黄渍，可用？A. 白醋和柠檬汁浸泡 B. 漂白水 C. 酒精 D. 汽油', '["A"]', '白醋和柠檬汁可分解黄渍。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 86, 'single_choice', '衣物柔顺剂不可用于？A. 棉质毛巾（降低吸水性）和速干运动服 B. 羊毛衫 C. 真丝 D. 涤纶', '["A"]', '柔顺剂会堵塞纤维影响吸水性。', 'easy', '衣服护理', '["衣服护理","洗涤用品"]', NOW(), NOW()),
(7, 87, 'single_choice', '以下哪种是正确清洗蕾丝衣物？A. 机洗 B. 手洗，放入洗衣袋，轻柔 C. 搓洗 D. 拧干', '["B"]', '蕾丝娇贵，需轻柔手洗。', 'easy', '衣服护理', '["衣服护理","蕾丝护理"]', NOW(), NOW()),
(7, 88, 'single_choice', '衣服上的粉笔渍，可用？A. 抖落或吸尘器，再正常洗 B. 水洗 C. 酒精 D. 汽油', '["A"]', '先抖掉粉笔灰再洗效果更好。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 89, 'single_choice', '以下哪种是正确存放皮草的方法？A. 密封袋 B. 宽肩衣架悬挂，避光，恒温恒湿，专业存放 C. 折叠 D. 暴晒', '["B"]', '皮草需专业存放环境和宽肩衣架。', 'easy', '衣服护理', '["衣服护理","皮草护理"]', NOW(), NOW()),
(7, 90, 'single_choice', '去除衣服上的碘酒渍，可用？A. 酒精或淀粉糊 B. 水 C. 醋 D. 洗衣粉', '["A"]', '酒精可溶解碘，淀粉可吸附。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 91, 'single_choice', '衣服标签上的洗标顺序通常是？A. 水洗-漂白-干燥-熨烫-干洗 B. 任意 C. 熨烫-水洗 D. 干洗-水洗', '["A"]', '洗标通常按此顺序排列。', 'medium', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 92, 'single_choice', '以下哪种是去除衣服上霉味的有效方法？A. 白醋水浸泡后晾晒 B. 香水 C. 烘干 D. 冷冻', '["A"]', '白醋可杀菌去霉味。', 'easy', '衣服护理', '["衣服护理","去味技巧"]', NOW(), NOW()),
(7, 93, 'single_choice', '皮质包包表面刮痕，可用？A. 同色鞋油或皮革护理油轻轻涂抹 B. 水擦 C. 酒精 D. 指甲油', '["A"]', '护理油可填充和遮盖刮痕。', 'easy', '衣服护理', '["衣服护理","皮革护理"]', NOW(), NOW()),
(7, 94, 'single_choice', '衣物印花图案部分，熨烫时应？A. 直接烫 B. 反面熨烫或垫布 C. 高温烫 D. 蒸汽烫', '["B"]', '反烫可保护印花不脱落。', 'easy', '衣服护理', '["衣服护理","熨烫技巧"]', NOW(), NOW()),
(7, 95, 'single_choice', '去除衣服上的青草渍，可用？A. 酒精 B. 热水 C. 洗衣粉 D. 氨水（稀释后）', '["A"]', '酒精可溶解叶绿素。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 96, 'single_choice', '以下哪种是正确清洗羽绒被的方法？A. 频繁洗 B. 大容量洗衣机，中性洗涤剂，低温烘干 C. 干洗 D. 手洗拧干', '["B"]', '羽绒被需大容量机洗低温烘干。', 'easy', '衣服护理', '["衣服护理","羽绒被护理"]', NOW(), NOW()),
(7, 97, 'single_choice', '衣服上的铁屑痕迹，可用？A. 磁铁吸附后草酸处理 B. 水洗 C. 酒精 D. 汽油', '["A"]', '磁铁吸铁屑，草酸去锈痕。', 'medium', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 98, 'single_choice', '丝袜（尼龙）如何洗涤？A. 机洗 B. 手洗，用温和皂液，阴干 C. 烘干 D. 拧干', '["B"]', '丝袜娇贵，需手洗阴干。', 'easy', '衣服护理', '["衣服护理","丝袜护理"]', NOW(), NOW()),
(7, 99, 'single_choice', '以下哪种是正确护理白色皮鞋的方法？A. 暴晒 B. 用白色鞋油或牙膏擦拭，阴干 C. 水洗 D. 酒精', '["B"]', '白色鞋油或牙膏可遮盖污渍。', 'easy', '衣服护理', '["衣服护理","鞋类护理"]', NOW(), NOW()),
(7, 100, 'single_choice', '衣服存放时，为防虫可使用？A. 樟脑丸或雪松木条 B. 花椒 C. 干燥剂 D. 香水', '["A"]', '樟脑丸和雪松是传统防虫剂。', 'easy', '衣服护理', '["衣服护理","防虫技巧"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(7, 101, 'fill_blank', '羊毛衫水洗后缩水，可用______和护发素浸泡拉伸恢复。', '["温水"]', '温水加护发素可放松羊毛纤维。', 'medium', '衣服护理', '["衣服护理","羊毛护理"]', NOW(), NOW()),
(7, 102, 'fill_blank', '衣服标签上的水洗盆加手标志表示______。', '["手洗"]', '手洗标志表示不可机洗。', 'easy', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 103, 'fill_blank', '白色衣物与深色衣物同洗时，可加______防染色。', '["防染片"]', '防染片可吸附游离色素。', 'easy', '衣服护理', '["衣服护理","洗涤技巧"]', NOW(), NOW()),
(7, 104, 'fill_blank', '去除衣服上的血渍，必须用______水浸泡。', '["冷"]', '冷水可防止蛋白质凝固。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 105, 'fill_blank', '真丝衣物不可用______性洗涤剂。', '["碱"]', '碱性会破坏真丝蛋白质。', 'easy', '衣服护理', '["衣服护理","真丝护理"]', NOW(), NOW()),
(7, 106, 'fill_blank', '皮衣存放应使用______衣架。', '["宽肩"]', '宽肩衣架可保持皮衣肩型。', 'easy', '衣服护理', '["衣服护理","皮衣护理"]', NOW(), NOW()),
(7, 107, 'fill_blank', '熨烫裤子挺缝线时，应在反面熨烫并使用______。', '["压烫或木块加压"]', '加压可使裤线更挺。', 'medium', '衣服护理', '["衣服护理","熨烫技巧"]', NOW(), NOW()),
(7, 108, 'fill_blank', '羽绒服清洗后，在烘干机内放入______可帮助拍打羽绒。', '["网球"]', '网球拍打可使羽绒蓬松。', 'easy', '衣服护理', '["衣服护理","羽绒服护理"]', NOW(), NOW()),
(7, 109, 'fill_blank', '去除衣服上的圆珠笔油，可用______。', '["风油精或酒精"]', '风油精可溶解圆珠笔墨水。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 110, 'fill_blank', '羊毛衫起球不应用力拉，而应用______。', '["毛球修剪器"]', '毛球修剪器可温和修剪。', 'easy', '衣服护理', '["衣服护理","羊毛护理"]', NOW(), NOW()),
(7, 111, 'fill_blank', '牛仔裤固色可以使用______加盐浸泡。', '["白醋"]', '白醋加盐可帮助固色。', 'easy', '衣服护理', '["衣服护理","牛仔裤护理"]', NOW(), NOW()),
(7, 112, 'fill_blank', '衬衫熨烫顺序一般为：领子、袖子、______、前身。', '["后背"]', '按此顺序可避免褶皱复烫。', 'easy', '衣服护理', '["衣服护理","熨烫技巧"]', NOW(), NOW()),
(7, 113, 'fill_blank', '衣物柔顺剂不能用于______，因为它会破坏其吸水性。', '["毛巾"]', '柔顺剂会使毛巾不吸水。', 'easy', '衣服护理', '["衣服护理","洗涤用品"]', NOW(), NOW()),
(7, 114, 'fill_blank', '洗标上正方形内画圆表示______。', '["转笼干燥"]', '此标志表示可用烘干机。', 'easy', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW()),
(7, 115, 'fill_blank', '去除衣服上的口香糖，可将衣物放入______冷冻。', '["冰箱"]', '冷冻使口香糖变脆。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 116, 'fill_blank', '羊绒防虫蛀，应存放于______环境中。', '["通风干燥"]', '通风干燥可防虫防霉。', 'easy', '衣服护理', '["衣服护理","羊绒护理"]', NOW(), NOW()),
(7, 117, 'fill_blank', '熨烫蕾丝衣物时，最好使用______。', '["垫布"]', '垫布可保护蕾丝不被烫坏。', 'easy', '衣服护理', '["衣服护理","熨烫技巧"]', NOW(), NOW()),
(7, 118, 'fill_blank', '运动服（速干）洗后不能使用______。', '["柔顺剂"]', '柔顺剂会堵塞速干纤维。', 'easy', '衣服护理', '["衣服护理","运动服护理"]', NOW(), NOW()),
(7, 119, 'fill_blank', '衣服上沾了油漆（油性），应用______擦洗。', '["松节油或汽油"]', '油性漆可溶于有机溶剂。', 'medium', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 120, 'fill_blank', '纯棉衣物暴晒易导致______。', '["褪色和纤维变脆"]', '紫外线会破坏棉纤维。', 'easy', '衣服护理', '["衣服护理","晾晒技巧"]', NOW(), NOW()),
(7, 121, 'fill_blank', '内衣洗涤水温最好不超过______度。', '["30-40"]', '高温会破坏内衣弹性。', 'easy', '衣服护理', '["衣服护理","内衣护理"]', NOW(), NOW()),
(7, 122, 'fill_blank', '丝绸衣物晾晒应在______处。', '["阴凉通风"]', '暴晒会损伤丝绸。', 'easy', '衣服护理', '["衣服护理","真丝护理"]', NOW(), NOW()),
(7, 123, 'fill_blank', '皮革制品沾水后应______。', '["吸干后阴干"]', '不可暴晒或加热。', 'easy', '衣服护理', '["衣服护理","皮革护理"]', NOW(), NOW()),
(7, 124, 'fill_blank', '白色棉袜发黄可用______煮沸浸泡。', '["淘米水或柠檬片"]', '淘米水和柠檬有增白效果。', 'easy', '衣服护理', '["衣服护理","去渍技巧"]', NOW(), NOW()),
(7, 125, 'fill_blank', '衣服标签上圆圈内字母“F”表示可用______干洗。', '["石油类溶剂"]', 'F表示仅限石油类干洗剂。', 'medium', '衣服护理', '["衣服护理","洗涤标志"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(8, 1, 'single_choice', '以下哪种物品最适合清洁厨房台面上的油污？A. 清水 B. 洗洁精加温水 C. 酒精 D. 醋', '["B"]', '洗洁精可乳化油脂去油效果好。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 2, 'single_choice', '去除水壶中的水垢，常用什么家庭材料？A. 洗洁精 B. 白醋或柠檬酸 C. 小苏打 D. 牙膏', '["B"]', '酸可溶解碳酸钙水垢。', 'easy', '清洁卫生', '["清洁卫生","水垢去除"]', NOW(), NOW()),
(8, 3, 'single_choice', '清洁微波炉内部油渍，安全有效的方法是？A. 用钢丝球擦 B. 碗中加水加柠檬片或白醋，加热后蒸汽软化再擦拭 C. 用洗洁精直接涂抹 D. 用酒精喷洒', '["B"]', '蒸汽可软化油污，易于擦拭。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 4, 'single_choice', '马桶清洁时，以下哪项是正确的？A. 洁厕灵和84消毒液混合使用 B. 分开使用，不可混用，先用洁厕灵刷洗后冲净再用消毒液 C. 只用清水 D. 用洗衣粉', '["B"]', '混用会产生有毒氯气。', 'easy', '清洁卫生', '["清洁卫生","卫生间清洁"]', NOW(), NOW()),
(8, 5, 'single_choice', '去除冰箱内部的异味，可使用？A. 柚子皮或活性炭 B. 洗洁精 C. 酒精 D. 漂白水', '["A"]', '活性炭可吸附异味分子。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 6, 'single_choice', '以下哪种材质不能使用84消毒液？A. 白色棉布 B. 彩色衣物和金属 C. 瓷砖 D. 塑料', '["B"]', '84会使彩色衣物褪色并腐蚀金属。', 'easy', '清洁卫生', '["清洁卫生","消毒技巧"]', NOW(), NOW()),
(8, 7, 'single_choice', '清洁油烟机滤网上的重油垢，最佳方法是？A. 用抹布擦 B. 用热水加食用碱或油烟机清洁剂浸泡 C. 用钢丝球干刷 D. 用洗洁精', '["B"]', '碱可皂化油脂，易清洗。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 8, 'single_choice', '玻璃窗户擦完后有痕迹，可用什么工具收水？A. 报纸或玻璃刮 B. 普通抹布 C. 海绵 D. 纸巾', '["A"]', '玻璃刮可一次刮净无水痕。', 'easy', '清洁卫生', '["清洁卫生","玻璃清洁"]', NOW(), NOW()),
(8, 9, 'single_choice', '以下哪种是天然消毒杀菌剂？A. 84消毒液 B. 75%酒精 C. 白醋（部分细菌） D. 以上都是', '["D"]', '三者都有一定消毒作用。', 'easy', '清洁卫生', '["清洁卫生","消毒技巧"]', NOW(), NOW()),
(8, 10, 'single_choice', '去除砧板上的生肉细菌和异味，可用？A. 洗洁精 B. 白醋或柠檬擦洗后冲洗，或撒盐搓洗 C. 酒精 D. 热水', '["B"]', '白醋杀菌，盐搓去异味。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 11, 'single_choice', '清洁不锈钢器具时，应避免使用？A. 洗洁精 B. 钢丝球（会划伤表面） C. 软布 D. 专用清洁剂', '["B"]', '钢丝球会留下划痕，破坏表面。', 'easy', '清洁卫生', '["清洁卫生","不锈钢清洁"]', NOW(), NOW()),
(8, 12, 'single_choice', '以下哪种方法可杀死床上的尘螨？A. 拍打 B. 60度以上热水洗涤或暴晒 C. 凉水洗 D. 吸尘器', '["B"]', '高温可杀死尘螨。', 'easy', '清洁卫生', '["清洁卫生","除螨技巧"]', NOW(), NOW()),
(8, 13, 'single_choice', '清洁木地板时，最好使用？A. 大量水拖 B. 拧干的湿拖把或专用木地板清洁剂 C. 肥皂水 D. 酒精', '["B"]', '木地板怕水，需拧干拖把。', 'easy', '清洁卫生', '["清洁卫生","地板清洁"]', NOW(), NOW()),
(8, 14, 'single_choice', '去除衣服上的油渍（预处理），可用？A. 洗洁精涂抹搓洗 B. 直接扔洗衣机 C. 热水泡 D. 酒精', '["A"]', '洗洁精预处理去油效果好。', 'easy', '清洁卫生', '["清洁卫生","去渍技巧"]', NOW(), NOW()),
(8, 15, 'single_choice', '以下哪种清洁剂不能用于大理石台面？A. 中性清洁剂 B. 酸性清洁剂（如醋、洁厕灵） C. 洗洁精 D. 清水', '["B"]', '酸会腐蚀大理石表面。', 'easy', '清洁卫生', '["清洁卫生","石材清洁"]', NOW(), NOW()),
(8, 16, 'single_choice', '清洁烤箱内部焦渍，可使用？A. 小苏打糊涂抹静置后擦拭 B. 钢丝球 C. 洗洁精 D. 酒精', '["A"]', '小苏打糊可软化焦渍。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 17, 'single_choice', '以下哪种物品不适宜放入洗碗机？A. 陶瓷碗 B. 铸铁锅和木质砧板 C. 不锈钢餐具 D. 耐热玻璃', '["B"]', '铸铁锅会生锈，木质品易变形。', 'easy', '清洁卫生', '["清洁卫生","洗碗机使用"]', NOW(), NOW()),
(8, 18, 'single_choice', '去除茶渍和咖啡渍，可使用？A. 牙膏或小苏打 B. 洗洁精 C. 酒精 D. 油', '["A"]', '牙膏和小苏打可摩擦去渍。', 'easy', '清洁卫生', '["清洁卫生","去渍技巧"]', NOW(), NOW()),
(8, 19, 'single_choice', '拖地时，在水中加入少量什么可使地板更光亮？A. 盐 B. 柔顺剂或白醋 C. 洗洁精 D. 酒精', '["B"]', '柔顺剂可减少静电吸附灰尘。', 'easy', '清洁卫生', '["清洁卫生","地板清洁"]', NOW(), NOW()),
(8, 20, 'single_choice', '清洁电脑键盘的缝隙，最好用？A. 湿抹布 B. 软毛刷或压缩空气罐 C. 水洗 D. 酒精倒', '["B"]', '软毛刷可清缝隙不伤键盘。', 'easy', '清洁卫生', '["清洁卫生","数码产品清洁"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(8, 21, 'single_choice', '以下哪种是去除卫生间霉菌的有效方法？A. 漂白水稀释后喷洒，静置冲洗 B. 洗洁精 C. 清水 D. 酒精', '["A"]', '漂白水可杀灭霉菌孢子。', 'easy', '清洁卫生', '["清洁卫生","卫生间清洁"]', NOW(), NOW()),
(8, 22, 'single_choice', '清洁真皮沙发，应使用？A. 水擦 B. 专用皮革清洁剂和护理油 C. 酒精 D. 洗洁精', '["B"]', '专用产品不伤皮质。', 'easy', '清洁卫生', '["清洁卫生","皮革清洁"]', NOW(), NOW()),
(8, 23, 'single_choice', '以下哪种物品可吸附衣柜内潮湿和异味？A. 干燥剂或竹炭包 B. 香水 C. 樟脑丸 D. 洗衣粉', '["A"]', '竹炭可吸湿除味。', 'easy', '清洁卫生', '["清洁卫生","除湿除味"]', NOW(), NOW()),
(8, 24, 'single_choice', '清洁银器发黑，可用？A. 牙膏擦拭或小苏打铝箔法 B. 洗洁精 C. 钢丝球 D. 酒精', '["A"]', '牙膏可摩擦去除氧化层。', 'easy', '清洁卫生', '["清洁卫生","金属清洁"]', NOW(), NOW()),
(8, 25, 'single_choice', '以下哪种做法不能有效去除房间烟味？A. 开窗通风 B. 白醋水熏蒸 C. 喷洒空气清新剂遮盖 D. 活性炭吸附', '["C"]', '空气清新剂只遮盖不分解。', 'easy', '清洁卫生', '["清洁卫生","空气净化"]', NOW(), NOW()),
(8, 26, 'single_choice', '清洁洗碗池下水道异味，可倒入？A. 小苏打加白醋，热水冲洗 B. 洗洁精 C. 清水 D. 酒精', '["A"]', '酸碱反应可冲走污垢。', 'easy', '清洁卫生', '["清洁卫生","管道清洁"]', NOW(), NOW()),
(8, 27, 'single_choice', '以下哪种材质不能使用蒸汽清洁机？A. 瓷砖 B. 密封木地板 C. 不耐热的塑料和未密封的木材 D. 不锈钢', '["C"]', '不耐热材质会变形损坏。', 'easy', '清洁卫生', '["清洁卫生","蒸汽清洁"]', NOW(), NOW()),
(8, 28, 'single_choice', '去除地毯上的红酒渍，应急方法是？A. 撒盐吸收后吸尘，再用清洁剂 B. 水擦 C. 酒精 D. 洗衣粉', '["A"]', '盐可吸收红酒，防止扩散。', 'easy', '清洁卫生', '["清洁卫生","地毯清洁"]', NOW(), NOW()),
(8, 29, 'single_choice', '清洁普通墙面上的手印，可用？A. 橡皮擦或魔术海绵（纳米海绵） B. 水洗 C. 砂纸 D. 钢丝球', '["A"]', '魔术海绵可物理摩擦去污。', 'easy', '清洁卫生', '["清洁卫生","墙面清洁"]', NOW(), NOW()),
(8, 30, 'single_choice', '以下哪种是正确清洁液晶电视屏幕的方法？A. 酒精直接喷 B. 专用屏幕清洁剂喷软布后轻擦 C. 湿抹布 D. 纸巾干擦', '["B"]', '专用清洁剂不伤涂层。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 31, 'single_choice', '去除锅底烧焦的黑垢，可用？A. 小苏打加水煮沸 B. 钢丝球硬刷 C. 洗洁精 D. 醋', '["A"]', '小苏打可软化焦垢。', 'easy', '清洁卫生', '["清洁卫生","锅具清洁"]', NOW(), NOW()),
(8, 32, 'single_choice', '清洁宠物毛发，哪种工具最有效？A. 普通扫把 B. 橡胶刮毛器或粘毛滚筒 C. 湿抹布 D. 吸尘器', '["B"]', '橡胶可静电吸附毛发。', 'easy', '清洁卫生', '["清洁卫生","宠物清洁"]', NOW(), NOW()),
(8, 33, 'single_choice', '以下哪种消毒液对新型冠状病毒有效？A. 75%酒精 B. 含氯消毒剂（如84） C. 过氧化氢 D. 以上都是', '["D"]', '三者对新冠病毒都有效。', 'easy', '清洁卫生', '["清洁卫生","消毒技巧"]', NOW(), NOW()),
(8, 34, 'single_choice', '清洁榨汁机刀片处残渣，安全方法是？A. 手直接伸入清洗 B. 倒入温水加洗洁精，开机运转清洗 C. 用刷子 D. 冲水', '["B"]', '开机自洗最安全不伤手。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 35, 'single_choice', '去除塑料饭盒上的异味和油渍，可用？A. 小苏打水浸泡 B. 洗洁精 C. 酒精 D. 热水', '["A"]', '小苏打可去油除味。', 'easy', '清洁卫生', '["清洁卫生","塑料制品清洁"]', NOW(), NOW()),
(8, 36, 'single_choice', '以下哪种是正确清洁皮鞋的方法？A. 水洗 B. 先除灰，再上鞋油，最后抛光 C. 酒精擦 D. 暴晒', '["B"]', '正确护理可延长皮鞋寿命。', 'easy', '清洁卫生', '["清洁卫生","鞋类清洁"]', NOW(), NOW()),
(8, 37, 'single_choice', '清洁窗帘（厚重）的最佳频率是？A. 每月 B. 每半年至一年，根据灰尘情况 C. 每周 D. 三年', '["B"]', '厚重窗帘不宜频繁清洗。', 'easy', '清洁卫生', '["清洁卫生","布艺清洁"]', NOW(), NOW()),
(8, 38, 'single_choice', '以下哪种物品可以去除标签残留的胶痕？A. 风油精或酒精 B. 水 C. 洗洁精 D. 醋', '["A"]', '风油精可溶解胶粘剂。', 'easy', '清洁卫生', '["清洁卫生","去胶技巧"]', NOW(), NOW()),
(8, 39, 'single_choice', '清洁洗衣机滚筒内部，可使用？A. 洗衣机槽清洁剂或白醋小苏打空洗 B. 漂白水 C. 洗洁精 D. 酒精', '["A"]', '专用清洁剂可除垢杀菌。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 40, 'single_choice', '以下哪种是去除手上洋葱味的方法？A. 不锈钢皂或白醋搓洗 B. 肥皂 C. 清水 D. 酒精', '["A"]', '不锈钢可中和硫化物异味。', 'easy', '清洁卫生', '["清洁卫生","个人清洁"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(8, 41, 'single_choice', '清洁纱窗上的灰尘，简便方法是？A. 拆卸水洗 B. 用报纸沾水贴纱窗上静置后取下 C. 刷子刷 D. 吸尘器', '["B"]', '湿报纸可吸附灰尘。', 'easy', '清洁卫生', '["清洁卫生","纱窗清洁"]', NOW(), NOW()),
(8, 42, 'single_choice', '以下哪种清洁剂不能混合使用？A. 洗洁精和醋 B. 84消毒液和洁厕灵（产生氯气） C. 小苏打和白醋 D. 酒精和水', '["B"]', '混合会产生剧毒氯气。', 'easy', '清洁卫生', '["清洁卫生","安全警示"]', NOW(), NOW()),
(8, 43, 'single_choice', '清洁键盘上的污渍，应？A. 拔下键帽清洗 B. 倒酒精 C. 用水冲洗 D. 用湿布猛擦', '["A"]', '拔键帽可彻底清洁。', 'medium', '清洁卫生', '["清洁卫生","数码产品清洁"]', NOW(), NOW()),
(8, 44, 'single_choice', '去除浴帘上的霉点，可用？A. 漂白水稀释浸泡 B. 洗洁精 C. 酒精 D. 清水', '["A"]', '漂白水可杀灭霉菌。', 'easy', '清洁卫生', '["清洁卫生","卫生间清洁"]', NOW(), NOW()),
(8, 45, 'single_choice', '以下哪种是正确清洁钻石首饰的方法？A. 牙膏刷 B. 氨水稀释浸泡软刷 C. 超声波清洗机（无裂缝宝石） D. 以上都可以', '["D"]', '多种方法可清洁钻石。', 'easy', '清洁卫生', '["清洁卫生","首饰清洁"]', NOW(), NOW()),
(8, 46, 'single_choice', '清洁木质砧板后，为防止开裂和杀菌，可？A. 涂抹食用油 B. 暴晒 C. 泡水 D. 烘烤', '["A"]', '油可保养木质防止开裂。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 47, 'single_choice', '以下哪种不是有效除螨方法？A. 吸尘器 B. 紫外线灯短时间照射 C. 高温洗涤 D. 低温冷冻', '["B"]', '短时间紫外线杀螨效果有限。', 'medium', '清洁卫生', '["清洁卫生","除螨技巧"]', NOW(), NOW()),
(8, 48, 'single_choice', '清洁咖啡机内部水垢，应使用？A. 专用除垢剂或白醋 B. 洗洁精 C. 酒精 D. 清水', '["A"]', '除垢剂可溶解水垢。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 49, 'single_choice', '以下哪种是清洁黄金饰品的正确方法？A. 牙膏软刷，清水冲洗 B. 漂白水浸泡 C. 钢丝球打磨 D. 酒精', '["A"]', '牙膏可温和去污不伤金。', 'easy', '清洁卫生', '["清洁卫生","首饰清洁"]', NOW(), NOW()),
(8, 50, 'single_choice', '清洁排风扇上的油污，可用？A. 热水加洗洁精浸泡 B. 直接刷 C. 酒精 D. 醋', '["A"]', '热水加洗洁精可软化油污。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 51, 'single_choice', '以下哪项是“清洁卫生”中的“由内向外”原则？A. 先擦桌面再扫地 B. 先扫角落后扫中间 C. 先湿后干 D. 先上后下', '["B"]', '角落先扫，避免灰尘扩散。', 'easy', '清洁卫生', '["清洁卫生","清洁原则"]', NOW(), NOW()),
(8, 52, 'single_choice', '去除汽车玻璃上的油膜，可用？A. 洗洁精或专业油膜去除剂 B. 水 C. 酒精 D. 醋', '["A"]', '洗洁精可乳化油膜。', 'easy', '清洁卫生', '["清洁卫生","玻璃清洁"]', NOW(), NOW()),
(8, 53, 'single_choice', '以下哪种是正确清洁羽绒被的方法？A. 干洗 B. 水洗后低温烘干 C. 暴晒 D. 压缩', '["B"]', '水洗低温烘干最安全。', 'easy', '清洁卫生', '["清洁卫生","布艺清洁"]', NOW(), NOW()),
(8, 54, 'single_choice', '清洁马桶水箱内部，可用？A. 白醋浸泡去除水垢 B. 强酸 C. 钢丝球 D. 漂白水', '["A"]', '白醋可溶解水垢。', 'easy', '清洁卫生', '["清洁卫生","卫生间清洁"]', NOW(), NOW()),
(8, 55, 'single_choice', '以下哪种材质的地毯不能用蒸汽清洗？A. 羊毛 B. 化纤 C. 棉 D. 混纺', '["A"]', '高温蒸汽会使羊毛缩水。', 'easy', '清洁卫生', '["清洁卫生","地毯清洁"]', NOW(), NOW()),
(8, 56, 'single_choice', '去除衣服上的口香糖残留，可用？A. 冰敷后刮除 B. 热水 C. 酒精 D. 洗洁精', '["A"]', '冷冻使口香糖变脆易除。', 'easy', '清洁卫生', '["清洁卫生","去渍技巧"]', NOW(), NOW()),
(8, 57, 'single_choice', '以下哪种是正确清洁空气净化器滤网的方法？A. 水洗（部分可洗）或吸尘器吸 B. 全部水洗 C. 暴晒 D. 酒精', '["A"]', '先看说明书，部分滤网可水洗。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 58, 'single_choice', '清洁白色运动鞋的橡胶边，可用？A. 魔术海绵或牙膏 B. 钢丝球 C. 酒精 D. 洗洁精', '["A"]', '魔术海绵可擦净橡胶。', 'easy', '清洁卫生', '["清洁卫生","鞋类清洁"]', NOW(), NOW()),
(8, 59, 'single_choice', '以下哪种方法能快速除冰箱冷冻室冰霜？A. 断电后放热水关上门 B. 用刀铲 C. 电吹风热风吹（注意防水） D. 以上都可以', '["D"]', '多种方法可加速化冰。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 60, 'single_choice', '清洁水槽下水管堵塞，可先尝试？A. 小苏打加醋，热水冲 B. 铁丝捅 C. 拆管 D. 倒油', '["A"]', '酸碱反应可冲走堵塞物。', 'easy', '清洁卫生', '["清洁卫生","管道清洁"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(8, 61, 'single_choice', '以下哪种是正确清洁眼镜镜片的方法？A. 用纸巾干擦 B. 清水冲洗，洗洁精轻揉，专用布擦干 C. 酒精 D. 衣服角擦', '["B"]', '清水冲洗可避免划伤。', 'easy', '清洁卫生', '["清洁卫生","眼镜清洁"]', NOW(), NOW()),
(8, 62, 'single_choice', '清洁烤箱玻璃门上的油污，可用？A. 小苏打糊 B. 钢丝球 C. 刀片刮 D. 酒精', '["A"]', '小苏打糊不伤玻璃。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 63, 'single_choice', '以下哪种是正确清洁不锈钢水槽的方法？A. 用洗洁精软布，最后擦干 B. 漂白水 C. 钢丝球 D. 醋', '["A"]', '擦干可防止水渍。', 'easy', '清洁卫生', '["清洁卫生","不锈钢清洁"]', NOW(), NOW()),
(8, 64, 'single_choice', '去除卫生间地砖缝隙的霉黑，可用？A. 84消毒液或除霉啫喱涂抹，静置刷洗 B. 洗洁精 C. 酒精 D. 清水', '["A"]', '除霉啫喱可渗透杀霉。', 'easy', '清洁卫生', '["清洁卫生","卫生间清洁"]', NOW(), NOW()),
(8, 65, 'single_choice', '以下哪种是清洁毛绒玩具的正确方法？A. 装入洗衣袋轻柔机洗，阴干 B. 暴晒 C. 水煮 D. 干洗', '["A"]', '洗衣袋可保护玩具。', 'easy', '清洁卫生', '["清洁卫生","布艺清洁"]', NOW(), NOW()),
(8, 66, 'single_choice', '清洁烤盘上的焦糊物，可用？A. 小苏打加过氧化氢制成糊状涂抹 B. 钢丝球 C. 洗洁精 D. 醋', '["A"]', '小苏打和过氧化氢可软化焦糊。', 'medium', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 67, 'single_choice', '以下哪种是正确清洁真丝枕套的方法？A. 冷水手洗，中性洗涤剂，阴干 B. 热水洗 C. 拧干 D. 暴晒', '["A"]', '真丝需冷水手洗阴干。', 'easy', '清洁卫生', '["清洁卫生","布艺清洁"]', NOW(), NOW()),
(8, 68, 'single_choice', '去除水龙头上的水垢，可用？A. 柠檬片或白醋包裹擦拭 B. 钢丝球 C. 洗洁精 D. 酒精', '["A"]', '酸可溶解水垢。', 'easy', '清洁卫生', '["清洁卫生","卫生间清洁"]', NOW(), NOW()),
(8, 69, 'single_choice', '清洁沙发上的液体污渍（如牛奶），应？A. 立即吸干，再用清洁剂 B. 揉搓 C. 电吹风热风 D. 不管', '["A"]', '立即吸干可防止渗入。', 'easy', '清洁卫生', '["清洁卫生","布艺清洁"]', NOW(), NOW()),
(8, 70, 'single_choice', '以下哪种是正确清洁化妆刷的方法？A. 专用洗刷水或橄榄皂，刷头向下冲洗 B. 泡水 C. 酒精 D. 洗洁精', '["A"]', '刷头向下可防止水进刷柄。', 'easy', '清洁卫生', '["清洁卫生","化妆工具清洁"]', NOW(), NOW()),
(8, 71, 'single_choice', '清洁百叶窗上的灰尘，可用？A. 旧袜子套夹子沾醋水擦拭 B. 水冲 C. 刷子 D. 吸尘器', '["A"]', '袜子套夹子可一次擦多片。', 'easy', '清洁卫生', '["清洁卫生","窗帘清洁"]', NOW(), NOW()),
(8, 72, 'single_choice', '以下哪种是正确清洁银饰方法？A. 擦银布或小苏打铝箔法 B. 牙膏 C. 洗洁精 D. 酒精', '["A"]', '擦银布可抛光去氧化。', 'easy', '清洁卫生', '["清洁卫生","首饰清洁"]', NOW(), NOW()),
(8, 73, 'single_choice', '去除墙壁上的蜡笔痕迹，可用？A. 吹风机加热后擦除或小苏打 B. 水 C. 酒精 D. 醋', '["A"]', '加热可使蜡笔软化易擦。', 'easy', '清洁卫生', '["清洁卫生","墙面清洁"]', NOW(), NOW()),
(8, 74, 'single_choice', '清洁切菜板的刀痕内细菌，可用？A. 撒盐柠檬擦拭或双氧水 B. 洗洁精 C. 酒精 D. 热水', '["A"]', '盐和柠檬可杀菌消毒。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 75, 'single_choice', '以下哪种是正确清洁手表表带（金属）的方法？A. 软毛刷沾肥皂水刷洗，清水冲净擦干 B. 泡水 C. 酒精 D. 超声波', '["A"]', '软毛刷可清洁缝隙。', 'easy', '清洁卫生', '["清洁卫生","手表清洁"]', NOW(), NOW()),
(8, 76, 'single_choice', '去除地毯上的墨水渍，可用？A. 牛奶或酒精 B. 水 C. 醋 D. 洗洁精', '["A"]', '牛奶可吸收墨水。', 'medium', '清洁卫生', '["清洁卫生","地毯清洁"]', NOW(), NOW()),
(8, 77, 'single_choice', '以下哪种是正确清理吸尘器尘盒的方法？A. 倒空后水洗（可水洗款）晾干 B. 拍打 C. 酒精 D. 不管', '["A"]', '定期清洁可保持吸力。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 78, 'single_choice', '清洁白色墙壁上的手印和污渍，可用？A. 魔术海绵沾水轻擦 B. 钢丝球 C. 砂纸 D. 酒精', '["A"]', '魔术海绵可物理去污。', 'easy', '清洁卫生', '["清洁卫生","墙面清洁"]', NOW(), NOW()),
(8, 79, 'single_choice', '以下哪种是正确清洁玉石手镯的方法？A. 清水软布，避免化学剂 B. 洗洁精 C. 酒精 D. 热水', '["A"]', '化学剂可能损伤玉石。', 'easy', '清洁卫生', '["清洁卫生","首饰清洁"]', NOW(), NOW()),
(8, 80, 'single_choice', '去除厨房墙壁上的油污贴纸，可用？A. 吹风机加热后撕除，残留用酒精擦 B. 直接撕 C. 水泡 D. 钢丝球', '["A"]', '加热可软化胶粘剂。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(8, 81, 'single_choice', '清洁电热水器内部水垢，需要？A. 专业人员或排空后注入除垢剂 B. 自己拆 C. 不管 D. 洗洁精', '["A"]', '电热水器内部清洁需专业人员。', 'medium', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 82, 'single_choice', '以下哪种是正确清洁珍珠首饰的方法？A. 软布沾清水擦干，避免酸碱 B. 超声波 C. 牙膏 D. 酒精', '["A"]', '珍珠怕酸碱，需温和清洁。', 'easy', '清洁卫生', '["清洁卫生","首饰清洁"]', NOW(), NOW()),
(8, 83, 'single_choice', '清洁烤箱发热管上的油污，应？A. 断电冷却后软刷轻擦，不可用湿布 B. 湿布擦 C. 钢丝球 D. 酒精', '["A"]', '湿擦可能损坏发热管。', 'medium', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 84, 'single_choice', '去除不锈钢锅上的彩虹色斑，可用？A. 白醋擦拭 B. 洗洁精 C. 小苏打 D. 酒精', '["A"]', '白醋可去除氧化色斑。', 'easy', '清洁卫生', '["清洁卫生","锅具清洁"]', NOW(), NOW()),
(8, 85, 'single_choice', '以下哪种是正确清洁健身瑜伽垫的方法？A. 稀释醋水或专用喷雾擦拭，阴干 B. 机洗 C. 暴晒 D. 泡水', '["A"]', '醋水可消毒不伤材质。', 'easy', '清洁卫生', '["清洁卫生","运动用品清洁"]', NOW(), NOW()),
(8, 86, 'single_choice', '清洁车门内饰（织物）的污渍，可用？A. 泡沫清洁剂+软毛刷 B. 水洗 C. 酒精 D. 漂白水', '["A"]', '泡沫清洁剂不伤内饰且易干。', 'easy', '清洁卫生', '["清洁卫生","汽车清洁"]', NOW(), NOW()),
(8, 87, 'single_choice', '以下哪种可以有效去除新装修房间的甲醛？A. 通风+活性炭 B. 醋熏 C. 水盆 D. 柚子皮', '["A"]', '通风最有效，活性炭吸附。', 'easy', '清洁卫生', '["清洁卫生","空气净化"]', NOW(), NOW()),
(8, 88, 'single_choice', '清洁电风扇叶片和网罩，方法为？A. 拆下温水和洗洁精浸泡刷洗，晾干 B. 水冲 C. 酒精 D. 干擦', '["A"]', '拆洗可彻底清洁。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 89, 'single_choice', '去除衣服上的铁锈，可用？A. 柠檬汁和盐搓洗后暴晒 B. 洗洁精 C. 酒精 D. 漂白水', '["A"]', '柠檬汁可溶解铁锈。', 'easy', '清洁卫生', '["清洁卫生","去渍技巧"]', NOW(), NOW()),
(8, 90, 'single_choice', '以下哪种是正确清洁奶瓶的方法？A. 拆解后用奶瓶刷和专用清洁剂，消毒柜或煮沸消毒 B. 洗洁精冲冲 C. 酒精 D. 清水', '["A"]', '消毒对婴儿健康重要。', 'easy', '清洁卫生', '["清洁卫生","婴儿用品清洁"]', NOW(), NOW()),
(8, 91, 'single_choice', '清洁燃气灶炉头火盖上的积碳和堵塞，可用？A. 牙签或细针疏通，小苏打浸泡 B. 钢丝球 C. 水冲 D. 酒精', '["A"]', '牙签可疏通火孔不伤炉头。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 92, 'single_choice', '以下哪种是正确清洁皮鞋内里（汗渍）的方法？A. 小苏打粉撒入静置后倒出，通风 B. 水洗 C. 酒精 D. 暴晒', '["A"]', '小苏打可吸湿除味。', 'easy', '清洁卫生', '["清洁卫生","鞋类清洁"]', NOW(), NOW()),
(8, 93, 'single_choice', '清洁窗帘挂钩轨道内的灰尘，可用？A. 旧牙刷或吸尘器细吸头 B. 水 C. 酒精 D. 抹布', '["A"]', '牙刷可刷缝除灰。', 'easy', '清洁卫生', '["清洁卫生","窗帘清洁"]', NOW(), NOW()),
(8, 94, 'single_choice', '去除白色台面上的记号笔迹，可用？A. 酒精擦拭 B. 水 C. 洗洁精 D. 醋', '["A"]', '酒精可溶解记号笔墨水。', 'easy', '清洁卫生', '["清洁卫生","去渍技巧"]', NOW(), NOW()),
(8, 95, 'single_choice', '以下哪种是正确清洁咖啡杯内壁茶渍的方法？A. 碎蛋壳加醋摇晃或盐巴擦洗 B. 洗洁精 C. 钢丝球 D. 酒精', '["A"]', '碎蛋壳可摩擦去渍不伤瓷。', 'easy', '清洁卫生', '["清洁卫生","杯具清洁"]', NOW(), NOW()),
(8, 96, 'single_choice', '清洁空调过滤网，应？A. 取下用软刷和清水冲洗，阴干 B. 暴晒 C. 酒精 D. 洗洁精', '["A"]', '阴干可防止变形。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 97, 'single_choice', '去除衣服上的口香糖残留（已冷冻刮除后），可用？A. 酒精擦拭残留胶痕 B. 水洗 C. 醋 D. 洗衣粉', '["A"]', '酒精可溶解残余胶粘剂。', 'easy', '清洁卫生', '["清洁卫生","去渍技巧"]', NOW(), NOW()),
(8, 98, 'single_choice', '以下哪种是正确清洁银质刀叉的方法？A. 小苏打热水浸泡 B. 钢丝球 C. 洗洁精 D. 酒精', '["A"]', '小苏打热水可去氧化。', 'easy', '清洁卫生', '["清洁卫生","餐具清洁"]', NOW(), NOW()),
(8, 99, 'single_choice', '清洁马桶刷本身，应？A. 每次用后清洁剂冲洗并悬挂沥干 B. 放回底座 C. 不管 D. 烘干', '["A"]', '清洁后沥干可防霉。', 'easy', '清洁卫生', '["清洁卫生","卫生间清洁"]', NOW(), NOW()),
(8, 100, 'single_choice', '清洁地面时，以下顺序正确的是？A. 先扫后拖，由里向外 B. 先拖后扫 C. 边扫边拖 D. 只拖不扫', '["A"]', '先扫后拖可避免拖把粘尘。', 'easy', '清洁卫生', '["清洁卫生","地面清洁"]', NOW(), NOW());
INSERT INTO `quiz_questions` (`quiz_id`, `position`, `question_type`, `stem`, `correct_answer`, `explanation`, `difficulty`, `category`, `tags`, `created_at`, `updated_at`) VALUES
(8, 101, 'fill_blank', '84消毒液使用时需按比例______，避免原液直接接触皮肤。', '["稀释"]', '原液腐蚀性强。', 'easy', '清洁卫生', '["清洁卫生","消毒技巧"]', NOW(), NOW()),
(8, 102, 'fill_blank', '去除水垢的天然材料是______。', '["白醋或柠檬酸"]', '酸可溶解水垢。', 'easy', '清洁卫生', '["清洁卫生","水垢去除"]', NOW(), NOW()),
(8, 103, 'fill_blank', '清洁玻璃时，用______刮水可避免水痕。', '["玻璃刮"]', '玻璃刮一次成型无水痕。', 'easy', '清洁卫生', '["清洁卫生","玻璃清洁"]', NOW(), NOW()),
