(8, 105, 'fill_blank', '洁厕灵和漂白水混合会产生有毒气体______。', '["氯气"]', '氯气剧毒可致命。', 'easy', '清洁卫生', '["清洁卫生","安全警示"]', NOW(), NOW()),
(8, 106, 'fill_blank', '去除厨房重油污可用______加开水浸泡。', '["食用碱"]', '碱可皂化油脂。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 107, 'fill_blank', '洗衣机槽建议每______个月清洗一次。', '["3-6"]', '定期清洗可防霉菌滋生。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 108, 'fill_blank', '冰箱密封条发霉可用______或除霉啫喱清洁。', '["稀释漂白水"]', '漂白水可杀灭霉菌。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 109, 'fill_blank', '木质砧板保养需定期涂抹______。', '["食用油（矿物油或橄榄油）"]', '油可防裂防霉。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 110, 'fill_blank', '纳米海绵（魔术擦）的清洁原理是______，不宜用于光滑漆面。', '["物理摩擦"]', '摩擦会划伤光滑表面。', 'medium', '清洁卫生', '["清洁卫生","清洁工具"]', NOW(), NOW()),
(8, 111, 'fill_blank', '空调过滤网建议每______清洗一次。', '["半个月至一个月"]', '定期清洗保持空气清新。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 112, 'fill_blank', '除螨的有效方法是______以上的高温或冷冻。', '["60度"]', '高温可杀死尘螨。', 'easy', '清洁卫生', '["清洁卫生","除螨技巧"]', NOW(), NOW()),
(8, 113, 'fill_blank', '去除地毯上的宠物尿渍，应先用______吸干再酶清洁剂。', '["纸巾"]', '先吸干可防扩散。', 'easy', '清洁卫生', '["清洁卫生","地毯清洁"]', NOW(), NOW()),
(8, 114, 'fill_blank', '不锈钢器具清洁后应______，防止水渍。', '["擦干"]', '擦干可无水印。', 'easy', '清洁卫生', '["清洁卫生","不锈钢清洁"]', NOW(), NOW()),
(8, 115, 'fill_blank', '冰箱除味可以用______或咖啡渣。', '["活性炭"]', '活性炭吸附异味。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 116, 'fill_blank', '微波炉加热柠檬水去味后，需______。', '["擦拭内壁"]', '需擦去软化污渍。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 117, 'fill_blank', '清洁皮沙发禁用______性清洁剂。', '["碱或酒精"]', '碱性会损伤皮面。', 'easy', '清洁卫生', '["清洁卫生","皮革清洁"]', NOW(), NOW()),
(8, 118, 'fill_blank', '银饰变黑是因为与______反应生成硫化银。', '["硫"]', '空气中硫导致氧化。', 'easy', '清洁卫生', '["清洁卫生","首饰清洁"]', NOW(), NOW()),
(8, 119, 'fill_blank', '拖地水中加______可消毒杀菌。', '["滴露或84（按比例）"]', '适量消毒液可杀菌。', 'easy', '清洁卫生', '["清洁卫生","地板清洁"]', NOW(), NOW()),
(8, 120, 'fill_blank', '纱窗清洁可贴______吸附灰尘。', '["湿报纸"]', '湿报纸可粘灰。', 'easy', '清洁卫生', '["清洁卫生","纱窗清洁"]', NOW(), NOW()),
(8, 121, 'fill_blank', '油烟机接油盒清理前可铺______方便清洁。', '["保鲜膜或纸巾"]', '铺膜方便倒油。', 'easy', '清洁卫生', '["清洁卫生","厨房清洁"]', NOW(), NOW()),
(8, 122, 'fill_blank', '去除标签胶痕可用______。', '["风油精"]', '风油精可溶解胶粘剂。', 'easy', '清洁卫生', '["清洁卫生","去胶技巧"]', NOW(), NOW()),
(8, 123, 'fill_blank', '马桶水箱内放______可长期清洁（避免与洁厕灵同用）。', '["蓝泡泡或白醋"]', '蓝泡泡缓释清洁。', 'easy', '清洁卫生', '["清洁卫生","卫生间清洁"]', NOW(), NOW()),
(8, 124, 'fill_blank', '烤箱清洁小苏打糊需静置______小时。', '["8-12"]', '静置软化焦渍。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW()),
(8, 125, 'fill_blank', '清洁洗衣机橡胶圈霉斑可用______。', '["除霉啫喱"]', '除霉啫喱可渗透杀霉。', 'easy', '清洁卫生', '["清洁卫生","家电清洁"]', NOW(), NOW());
